export const MIGRATIONS: [string,string][] = [["20260117002431_3faf4763-2b1c-417c-9ebb-6712eb9f94b8.sql", "-- =============================================\n-- SERVCHAT - SISTEMA CORPORATIVO GRUPO SERVSUL\n-- =============================================\n\n-- 1. TABELA DE SETORES\nCREATE TABLE public.sectors (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  name TEXT NOT NULL,\n  color TEXT NOT NULL DEFAULT '#3B82F6',\n  icon TEXT DEFAULT 'building',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- 2. TABELA DE PERFIS\nCREATE TABLE public.profiles (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  name TEXT NOT NULL,\n  display_name TEXT,\n  email TEXT NOT NULL,\n  avatar_url TEXT,\n  sector_id UUID REFERENCES public.sectors(id) ON DELETE SET NULL,\n  autonomy_level TEXT NOT NULL DEFAULT 'colaborador' CHECK (autonomy_level IN ('admin', 'gerente', 'supervisor', 'colaborador')),\n  birth_date DATE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  UNIQUE(user_id),\n  UNIQUE(email)\n);\n\n-- 3. TABELA DE MENSAGENS DO CHAT\nCREATE TABLE public.messages (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  content TEXT NOT NULL,\n  author_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,\n  sector_id UUID NOT NULL REFERENCES public.sectors(id) ON DELETE CASCADE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- 4. TABELA DE AVISOS GERAIS\nCREATE TABLE public.announcements (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  title TEXT NOT NULL,\n  content TEXT NOT NULL,\n  author_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,\n  priority TEXT NOT NULL DEFAULT 'normal' CHECK (priority IN ('normal', 'important', 'urgent')),\n  is_pinned BOOLEAN NOT NULL DEFAULT false,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- 5. TABELA DE COMENT\u00c1RIOS NOS AVISOS\nCREATE TABLE public.announcement_comments (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  content TEXT NOT NULL,\n  author_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,\n  announcement_id UUID NOT NULL REFERENCES public.announcements(id) ON DELETE CASCADE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- =============================================\n-- FUN\u00c7\u00d5ES AUXILIARES (SECURITY DEFINER)\n-- =============================================\n\n-- Fun\u00e7\u00e3o para obter o perfil do usu\u00e1rio atual\nCREATE OR REPLACE FUNCTION public.get_current_profile_id()\nRETURNS UUID\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1;\n$$;\n\n-- Fun\u00e7\u00e3o para obter o setor do usu\u00e1rio atual\nCREATE OR REPLACE FUNCTION public.get_current_sector_id()\nRETURNS UUID\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT sector_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1;\n$$;\n\n-- Fun\u00e7\u00e3o para obter o n\u00edvel de autonomia do usu\u00e1rio atual\nCREATE OR REPLACE FUNCTION public.get_current_autonomy_level()\nRETURNS TEXT\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT autonomy_level FROM public.profiles WHERE user_id = auth.uid() LIMIT 1;\n$$;\n\n-- Fun\u00e7\u00e3o para verificar se o usu\u00e1rio tem o n\u00edvel de permiss\u00e3o necess\u00e1rio\nCREATE OR REPLACE FUNCTION public.has_autonomy_level(required_level TEXT)\nRETURNS BOOLEAN\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT CASE\n    WHEN required_level = 'colaborador' THEN true\n    WHEN required_level = 'supervisor' THEN \n      public.get_current_autonomy_level() IN ('admin', 'gerente', 'supervisor')\n    WHEN required_level = 'gerente' THEN \n      public.get_current_autonomy_level() IN ('admin', 'gerente')\n    WHEN required_level = 'admin' THEN \n      public.get_current_autonomy_level() = 'admin'\n    ELSE false\n  END;\n$$;\n\n-- =============================================\n-- TRIGGERS\n-- =============================================\n\n-- Trigger para atualizar updated_at\nCREATE OR REPLACE FUNCTION public.update_updated_at_column()\nRETURNS TRIGGER AS $$\nBEGIN\n  NEW.updated_at = now();\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SET search_path = public;\n\nCREATE TRIGGER update_profiles_updated_at\n  BEFORE UPDATE ON public.profiles\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nCREATE TRIGGER update_announcements_updated_at\n  BEFORE UPDATE ON public.announcements\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\n-- Trigger para criar perfil automaticamente ao registrar\nCREATE OR REPLACE FUNCTION public.handle_new_user()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  INSERT INTO public.profiles (user_id, name, display_name, email)\n  VALUES (\n    NEW.id,\n    COALESCE(NEW.raw_user_meta_data ->> 'name', NEW.email),\n    COALESCE(NEW.raw_user_meta_data ->> 'display_name', split_part(NEW.email, '@', 1)),\n    NEW.email\n  );\n  RETURN NEW;\nEND;\n$$;\n\nCREATE TRIGGER on_auth_user_created\n  AFTER INSERT ON auth.users\n  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();\n\n-- =============================================\n-- HABILITAR RLS\n-- =============================================\n\nALTER TABLE public.sectors ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.announcements ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.announcement_comments ENABLE ROW LEVEL SECURITY;\n\n-- =============================================\n-- RLS POLICIES - SECTORS\n-- =============================================\n\nCREATE POLICY \"Todos podem ver setores\"\n  ON public.sectors FOR SELECT\n  TO authenticated\n  USING (true);\n\nCREATE POLICY \"Admins podem criar setores\"\n  ON public.sectors FOR INSERT\n  TO authenticated\n  WITH CHECK (public.has_autonomy_level('admin'));\n\nCREATE POLICY \"Admins podem atualizar setores\"\n  ON public.sectors FOR UPDATE\n  TO authenticated\n  USING (public.has_autonomy_level('admin'));\n\nCREATE POLICY \"Admins podem deletar setores\"\n  ON public.sectors FOR DELETE\n  TO authenticated\n  USING (public.has_autonomy_level('admin'));\n\n-- =============================================\n-- RLS POLICIES - PROFILES\n-- =============================================\n\nCREATE POLICY \"Usu\u00e1rios autenticados podem ver todos os perfis\"\n  ON public.profiles FOR SELECT\n  TO authenticated\n  USING (true);\n\nCREATE POLICY \"Usu\u00e1rios podem atualizar pr\u00f3prio perfil\"\n  ON public.profiles FOR UPDATE\n  TO authenticated\n  USING (user_id = auth.uid())\n  WITH CHECK (user_id = auth.uid());\n\n-- =============================================\n-- RLS POLICIES - MESSAGES\n-- =============================================\n\nCREATE POLICY \"Usu\u00e1rios podem ver mensagens do seu setor\"\n  ON public.messages FOR SELECT\n  TO authenticated\n  USING (sector_id = public.get_current_sector_id() OR public.has_autonomy_level('admin'));\n\nCREATE POLICY \"Usu\u00e1rios podem criar mensagens no seu setor\"\n  ON public.messages FOR INSERT\n  TO authenticated\n  WITH CHECK (\n    author_id = public.get_current_profile_id() AND\n    sector_id = public.get_current_sector_id()\n  );\n\nCREATE POLICY \"Usu\u00e1rios podem deletar pr\u00f3prias mensagens\"\n  ON public.messages FOR DELETE\n  TO authenticated\n  USING (author_id = public.get_current_profile_id() OR public.has_autonomy_level('admin'));\n\n-- =============================================\n-- RLS POLICIES - ANNOUNCEMENTS\n-- =============================================\n\nCREATE POLICY \"Todos podem ver avisos\"\n  ON public.announcements FOR SELECT\n  TO authenticated\n  USING (true);\n\nCREATE POLICY \"Gerentes e admins podem criar avisos\"\n  ON public.announcements FOR INSERT\n  TO authenticated\n  WITH CHECK (\n    author_id = public.get_current_profile_id() AND\n    public.has_autonomy_level('gerente')\n  );\n\nCREATE POLICY \"Autores e admins podem atualizar avisos\"\n  ON public.announcements FOR UPDATE\n  TO authenticated\n  USING (author_id = public.get_current_profile_id() OR public.has_autonomy_level('admin'));\n\nCREATE POLICY \"Autores e admins podem deletar avisos\"\n  ON public.announcements FOR DELETE\n  TO authenticated\n  USING (author_id = public.get_current_profile_id() OR public.has_autonomy_level('admin'));\n\n-- =============================================\n-- RLS POLICIES - ANNOUNCEMENT COMMENTS\n-- =============================================\n\nCREATE POLICY \"Todos podem ver coment\u00e1rios\"\n  ON public.announcement_comments FOR SELECT\n  TO authenticated\n  USING (true);\n\nCREATE POLICY \"Usu\u00e1rios podem criar coment\u00e1rios\"\n  ON public.announcement_comments FOR INSERT\n  TO authenticated\n  WITH CHECK (author_id = public.get_current_profile_id());\n\nCREATE POLICY \"Autores podem deletar pr\u00f3prios coment\u00e1rios\"\n  ON public.announcement_comments FOR DELETE\n  TO authenticated\n  USING (author_id = public.get_current_profile_id() OR public.has_autonomy_level('admin'));\n\n-- =============================================\n-- DADOS INICIAIS - SETORES\n-- =============================================\n\nINSERT INTO public.sectors (name, color, icon) VALUES\n  ('Administrativo', '#3B82F6', 'building'),\n  ('Comercial', '#10B981', 'trending-up'),\n  ('Financeiro', '#F59E0B', 'dollar-sign'),\n  ('RH', '#EC4899', 'users'),\n  ('TI', '#8B5CF6', 'monitor'),\n  ('Operacional', '#EF4444', 'settings');\n\n-- =============================================\n-- HABILITAR REALTIME\n-- =============================================\n\nALTER PUBLICATION supabase_realtime ADD TABLE public.messages;\nALTER PUBLICATION supabase_realtime ADD TABLE public.announcements;"], ["20260117144710_7fc060ad-de72-489e-bd59-c201595fba29.sql", "-- 1. Create the \"Geral\" sector (fixed ID for reference)\nINSERT INTO public.sectors (id, name, color, icon)\nVALUES ('00000000-0000-0000-0000-000000000001', 'Geral', '#6B7280', 'users')\nON CONFLICT (id) DO NOTHING;\n\n-- 2. Create app_role enum for user roles\nDO $$ BEGIN\n  CREATE TYPE public.app_role AS ENUM ('admin', 'gerente', 'supervisor', 'colaborador');\nEXCEPTION\n  WHEN duplicate_object THEN null;\nEND $$;\n\n-- 3. Create user_roles table\nCREATE TABLE IF NOT EXISTS public.user_roles (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL,\n  role app_role NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  UNIQUE (user_id, role)\n);\n\n-- 4. Enable RLS on user_roles\nALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;\n\n-- 5. Create security definer function to check roles (prevents RLS recursion)\nCREATE OR REPLACE FUNCTION public.has_role(_user_id UUID, _role app_role)\nRETURNS BOOLEAN\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1\n    FROM public.user_roles\n    WHERE user_id = _user_id\n      AND role = _role\n  )\n$$;\n\n-- 6. Create function to check if user is admin\nCREATE OR REPLACE FUNCTION public.is_admin()\nRETURNS BOOLEAN\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1\n    FROM public.user_roles\n    WHERE user_id = auth.uid()\n      AND role = 'admin'\n  )\n$$;\n\n-- 7. Create system_settings table for registration password\nCREATE TABLE IF NOT EXISTS public.system_settings (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  key TEXT UNIQUE NOT NULL,\n  value TEXT NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- 8. Enable RLS on system_settings\nALTER TABLE public.system_settings ENABLE ROW LEVEL SECURITY;\n\n-- 9. Insert the registration password (hashed for security display but we'll use plain for validation in edge function)\nINSERT INTO public.system_settings (key, value)\nVALUES ('registration_password', 'Senh@Cast753')\nON CONFLICT (key) DO UPDATE SET value = 'Senh@Cast753';\n\n-- 10. RLS policies for user_roles\nCREATE POLICY \"Admins can manage all roles\"\nON public.user_roles\nFOR ALL\nTO authenticated\nUSING (public.is_admin())\nWITH CHECK (public.is_admin());\n\nCREATE POLICY \"Users can view their own roles\"\nON public.user_roles\nFOR SELECT\nTO authenticated\nUSING (user_id = auth.uid());\n\n-- 11. RLS policies for system_settings (only admin can access)\nCREATE POLICY \"Only admins can view system settings\"\nON public.system_settings\nFOR SELECT\nTO authenticated\nUSING (public.is_admin());\n\nCREATE POLICY \"Only admins can manage system settings\"\nON public.system_settings\nFOR ALL\nTO authenticated\nUSING (public.is_admin())\nWITH CHECK (public.is_admin());\n\n-- 12. Update messages RLS to allow access to Geral sector for all users\nDROP POLICY IF EXISTS \"Usu\u00e1rios podem ver mensagens do seu setor\" ON public.messages;\nCREATE POLICY \"Usu\u00e1rios podem ver mensagens do seu setor ou Geral\"\nON public.messages\nFOR SELECT\nUSING (\n  sector_id = get_current_sector_id() \n  OR sector_id = '00000000-0000-0000-0000-000000000001'::uuid\n  OR public.is_admin()\n);\n\nDROP POLICY IF EXISTS \"Usu\u00e1rios podem criar mensagens no seu setor\" ON public.messages;\nCREATE POLICY \"Usu\u00e1rios podem criar mensagens no seu setor ou Geral\"\nON public.messages\nFOR INSERT\nWITH CHECK (\n  author_id = get_current_profile_id() \n  AND (sector_id = get_current_sector_id() OR sector_id = '00000000-0000-0000-0000-000000000001'::uuid)\n);\n\n-- 13. Update trigger for system_settings\nCREATE TRIGGER update_system_settings_updated_at\nBEFORE UPDATE ON public.system_settings\nFOR EACH ROW\nEXECUTE FUNCTION public.update_updated_at_column();\n\n-- 14. Create policy to allow service role to insert user_roles (for edge function)\nCREATE POLICY \"Service role can insert roles\"\nON public.user_roles\nFOR INSERT\nTO service_role\nWITH CHECK (true);"], ["20260117150555_1d70873a-a606-4b6e-b776-7a8807670451.sql", "-- Add new fields to profiles table\nALTER TABLE public.profiles \nADD COLUMN IF NOT EXISTS phone text,\nADD COLUMN IF NOT EXISTS address text,\nADD COLUMN IF NOT EXISTS company text,\nADD COLUMN IF NOT EXISTS registration_number text,\nADD COLUMN IF NOT EXISTS profile_type text NOT NULL DEFAULT 'user',\nADD COLUMN IF NOT EXISTS is_active boolean NOT NULL DEFAULT true;\n\n-- Create user_permissions table for granular permissions\nCREATE TABLE IF NOT EXISTS public.user_permissions (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  can_post_announcements boolean NOT NULL DEFAULT false,\n  can_delete_messages boolean NOT NULL DEFAULT false,\n  can_access_management boolean NOT NULL DEFAULT false,\n  can_access_password_change boolean NOT NULL DEFAULT false,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\n  UNIQUE(user_id)\n);\n\n-- Create user_additional_sectors table for additional sector access\nCREATE TABLE IF NOT EXISTS public.user_additional_sectors (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  sector_id uuid NOT NULL REFERENCES public.sectors(id) ON DELETE CASCADE,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  UNIQUE(user_id, sector_id)\n);\n\n-- Enable RLS on new tables\nALTER TABLE public.user_permissions ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.user_additional_sectors ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for user_permissions\nCREATE POLICY \"Admins can manage all permissions\"\nON public.user_permissions\nFOR ALL\nUSING (is_admin())\nWITH CHECK (is_admin());\n\nCREATE POLICY \"Users can view their own permissions\"\nON public.user_permissions\nFOR SELECT\nUSING (user_id = auth.uid());\n\n-- RLS policies for user_additional_sectors\nCREATE POLICY \"Admins can manage all additional sectors\"\nON public.user_additional_sectors\nFOR ALL\nUSING (is_admin())\nWITH CHECK (is_admin());\n\nCREATE POLICY \"Users can view their own additional sectors\"\nON public.user_additional_sectors\nFOR SELECT\nUSING (user_id = auth.uid());\n\n-- Trigger to update updated_at on user_permissions\nCREATE TRIGGER update_user_permissions_updated_at\nBEFORE UPDATE ON public.user_permissions\nFOR EACH ROW\nEXECUTE FUNCTION public.update_updated_at_column();\n\n-- Function to check if user has access to a specific sector\nCREATE OR REPLACE FUNCTION public.user_has_sector_access(check_user_id uuid, check_sector_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT \n    -- Admin has access to all sectors\n    is_admin() OR\n    -- Check if it's the Geral sector (everyone has access)\n    check_sector_id = '00000000-0000-0000-0000-000000000001'::uuid OR\n    -- Check if it's the user's primary sector\n    EXISTS (\n      SELECT 1 FROM public.profiles \n      WHERE user_id = check_user_id AND sector_id = check_sector_id\n    ) OR\n    -- Check if it's in user's additional sectors\n    EXISTS (\n      SELECT 1 FROM public.user_additional_sectors \n      WHERE user_id = check_user_id AND sector_id = check_sector_id\n    )\n$$;"], ["20260117161618_fe7be671-9fd7-49db-bb4d-26da2d08a01d.sql", "-- Update announcements RLS policy to use can_post_announcements permission\nDROP POLICY IF EXISTS \"Gerentes e admins podem criar avisos\" ON public.announcements;\n\nCREATE POLICY \"Usu\u00e1rios com permiss\u00e3o podem criar avisos\"\n  ON public.announcements FOR INSERT\n  TO authenticated\n  WITH CHECK (\n    author_id = public.get_current_profile_id() AND\n    (\n      public.has_autonomy_level('gerente') OR\n      EXISTS (\n        SELECT 1 FROM public.user_permissions \n        WHERE user_id = auth.uid() \n        AND can_post_announcements = true\n      )\n    )\n  );\n\n-- Create direct_messages table for individual conversations\nCREATE TABLE IF NOT EXISTS public.direct_messages (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  sender_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,\n  receiver_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,\n  content text NOT NULL,\n  is_read boolean NOT NULL DEFAULT false,\n  created_at timestamp with time zone NOT NULL DEFAULT now()\n);\n\n-- Enable RLS on direct_messages\nALTER TABLE public.direct_messages ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for direct messages\nCREATE POLICY \"Users can view their own direct messages\"\n  ON public.direct_messages FOR SELECT\n  TO authenticated\n  USING (\n    sender_id = public.get_current_profile_id() OR \n    receiver_id = public.get_current_profile_id()\n  );\n\nCREATE POLICY \"Users can send direct messages\"\n  ON public.direct_messages FOR INSERT\n  TO authenticated\n  WITH CHECK (sender_id = public.get_current_profile_id());\n\nCREATE POLICY \"Users can delete their own sent messages\"\n  ON public.direct_messages FOR DELETE\n  TO authenticated\n  USING (sender_id = public.get_current_profile_id() OR is_admin());\n\n-- Create user_notifications table for chatbot notifications\nCREATE TABLE IF NOT EXISTS public.user_notifications (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  type text NOT NULL, -- 'announcement', 'message', 'birthday', 'system'\n  title text NOT NULL,\n  message text NOT NULL,\n  is_read boolean NOT NULL DEFAULT false,\n  reference_id uuid, -- ID of related entity (announcement_id, message_id, etc.)\n  created_at timestamp with time zone NOT NULL DEFAULT now()\n);\n\n-- Enable RLS on user_notifications\nALTER TABLE public.user_notifications ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for notifications\nCREATE POLICY \"Users can view their own notifications\"\n  ON public.user_notifications FOR SELECT\n  TO authenticated\n  USING (user_id = auth.uid());\n\nCREATE POLICY \"Users can update their own notifications\"\n  ON public.user_notifications FOR UPDATE\n  TO authenticated\n  USING (user_id = auth.uid());\n\nCREATE POLICY \"System can create notifications\"\n  ON public.user_notifications FOR INSERT\n  TO authenticated\n  WITH CHECK (true);\n\n-- Enable realtime for direct_messages\nALTER PUBLICATION supabase_realtime ADD TABLE public.direct_messages;"], ["20260117161628_fc0400c2-8d0b-43c4-ac2a-10443555e410.sql", "-- Fix permissive RLS policy for user_notifications\nDROP POLICY IF EXISTS \"System can create notifications\" ON public.user_notifications;\n\n-- Only admins or the system can create notifications for users\n-- Users cannot create notifications for themselves (server-side only via edge functions)\nCREATE POLICY \"Admins can create notifications\"\n  ON public.user_notifications FOR INSERT\n  TO authenticated\n  WITH CHECK (is_admin());"], ["20260117164924_8746b991-4ed7-46b7-9dae-9834bf9f75f8.sql", "-- Add start_at and expire_at columns to announcements\nALTER TABLE public.announcements \nADD COLUMN IF NOT EXISTS start_at TIMESTAMP WITH TIME ZONE DEFAULT now(),\nADD COLUMN IF NOT EXISTS expire_at TIMESTAMP WITH TIME ZONE;\n\n-- Add last_seen_at to profiles for tracking last activity\nALTER TABLE public.profiles \nADD COLUMN IF NOT EXISTS last_seen_at TIMESTAMP WITH TIME ZONE;\n\n-- Create user_additional_sectors table if not exists (fix for additional sectors)\n-- This table should already exist but let's ensure it's properly configured\n\n-- Create index for faster lookup\nCREATE INDEX IF NOT EXISTS idx_user_additional_sectors_user_id ON public.user_additional_sectors(user_id);\nCREATE INDEX IF NOT EXISTS idx_user_additional_sectors_sector_id ON public.user_additional_sectors(sector_id);\n\n-- Add foreign key constraints if not exists\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM information_schema.table_constraints \n    WHERE constraint_name = 'user_additional_sectors_sector_id_fkey'\n  ) THEN\n    ALTER TABLE public.user_additional_sectors \n    ADD CONSTRAINT user_additional_sectors_sector_id_fkey \n    FOREIGN KEY (sector_id) REFERENCES public.sectors(id) ON DELETE CASCADE;\n  END IF;\nEND $$;\n\n-- Update messages RLS to allow sending to additional sectors\nDROP POLICY IF EXISTS \"Usu\u00e1rios podem criar mensagens no seu setor ou Geral\" ON public.messages;\n\nCREATE POLICY \"Usu\u00e1rios podem criar mensagens nos setores com acesso\" \nON public.messages \nFOR INSERT \nWITH CHECK (\n  author_id = get_current_profile_id() AND (\n    sector_id = get_current_sector_id() OR \n    sector_id = '00000000-0000-0000-0000-000000000001'::uuid OR\n    is_admin() OR\n    EXISTS (\n      SELECT 1 FROM public.user_additional_sectors \n      WHERE user_id = auth.uid() AND sector_id = messages.sector_id\n    )\n  )\n);\n\n-- Update messages SELECT policy to include additional sectors\nDROP POLICY IF EXISTS \"Usu\u00e1rios podem ver mensagens do seu setor ou Geral\" ON public.messages;\n\nCREATE POLICY \"Usu\u00e1rios podem ver mensagens dos setores com acesso\" \nON public.messages \nFOR SELECT \nUSING (\n  sector_id = get_current_sector_id() OR \n  sector_id = '00000000-0000-0000-0000-000000000001'::uuid OR \n  is_admin() OR\n  EXISTS (\n    SELECT 1 FROM public.user_additional_sectors \n    WHERE user_id = auth.uid() AND sector_id = messages.sector_id\n  )\n);\n\n-- Ensure direct_messages privacy - admins CANNOT see others' messages\nDROP POLICY IF EXISTS \"Users can view their own direct messages\" ON public.direct_messages;\n\nCREATE POLICY \"Users can only view their own direct messages\" \nON public.direct_messages \nFOR SELECT \nUSING (\n  sender_id = get_current_profile_id() OR \n  receiver_id = get_current_profile_id()\n);\n\n-- Note: Even admins should not see private messages that don't involve them\n\n-- Create function to update last_seen_at\nCREATE OR REPLACE FUNCTION public.update_last_seen()\nRETURNS TRIGGER AS $$\nBEGIN\n  UPDATE public.profiles \n  SET last_seen_at = now() \n  WHERE user_id = auth.uid();\n  RETURN NEW;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;"], ["20260118004722_b5060c5d-ec78-42ad-81f6-cfcd8564369d.sql", "-- 1. Add user_status column to profiles\nALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS user_status text DEFAULT 'available';\n\n-- 2. Add work_period column to profiles (turno/per\u00edodo)\nALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS work_period text;\n\n-- 3. Create storage bucket for attachments\nINSERT INTO storage.buckets (id, name, public)\nVALUES ('attachments', 'attachments', true)\nON CONFLICT (id) DO NOTHING;\n\n-- 4. Create storage bucket for avatars\nINSERT INTO storage.buckets (id, name, public)\nVALUES ('avatars', 'avatars', true)\nON CONFLICT (id) DO NOTHING;\n\n-- 5. Create attachments table for messages and announcements\nCREATE TABLE IF NOT EXISTS public.attachments (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  file_name text NOT NULL,\n  file_type text NOT NULL,\n  file_size integer NOT NULL,\n  file_url text NOT NULL,\n  message_id uuid REFERENCES public.messages(id) ON DELETE CASCADE,\n  direct_message_id uuid REFERENCES public.direct_messages(id) ON DELETE CASCADE,\n  announcement_id uuid REFERENCES public.announcements(id) ON DELETE CASCADE,\n  uploaded_by uuid NOT NULL,\n  created_at timestamp with time zone NOT NULL DEFAULT now()\n);\n\n-- Enable RLS on attachments\nALTER TABLE public.attachments ENABLE ROW LEVEL SECURITY;\n\n-- Attachments policies\nCREATE POLICY \"Users can view attachments in messages they can see\"\n  ON public.attachments FOR SELECT\n  USING (\n    (message_id IS NOT NULL AND EXISTS (\n      SELECT 1 FROM public.messages m WHERE m.id = message_id\n    )) OR\n    (direct_message_id IS NOT NULL AND EXISTS (\n      SELECT 1 FROM public.direct_messages dm WHERE dm.id = direct_message_id AND (dm.sender_id = get_current_profile_id() OR dm.receiver_id = get_current_profile_id())\n    )) OR\n    (announcement_id IS NOT NULL AND EXISTS (\n      SELECT 1 FROM public.announcements a WHERE a.id = announcement_id\n    ))\n  );\n\nCREATE POLICY \"Users can upload attachments\"\n  ON public.attachments FOR INSERT\n  WITH CHECK (uploaded_by = get_current_profile_id());\n\nCREATE POLICY \"Users can delete own attachments\"\n  ON public.attachments FOR DELETE\n  USING (uploaded_by = get_current_profile_id() OR is_admin());\n\n-- 6. Create user_presence table for online/offline tracking\nCREATE TABLE IF NOT EXISTS public.user_presence (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id uuid NOT NULL UNIQUE,\n  is_online boolean NOT NULL DEFAULT false,\n  last_heartbeat timestamp with time zone NOT NULL DEFAULT now(),\n  created_at timestamp with time zone NOT NULL DEFAULT now()\n);\n\n-- Enable RLS on user_presence\nALTER TABLE public.user_presence ENABLE ROW LEVEL SECURITY;\n\n-- Presence policies\nCREATE POLICY \"Everyone can view presence\"\n  ON public.user_presence FOR SELECT\n  USING (true);\n\nCREATE POLICY \"Users can update their own presence\"\n  ON public.user_presence FOR UPDATE\n  USING (user_id = auth.uid());\n\nCREATE POLICY \"Users can insert their own presence\"\n  ON public.user_presence FOR INSERT\n  WITH CHECK (user_id = auth.uid());\n\n-- Enable realtime for user_presence\nALTER PUBLICATION supabase_realtime ADD TABLE public.user_presence;\n\n-- 7. Storage policies for avatars\nCREATE POLICY \"Avatar images are publicly accessible\"\n  ON storage.objects FOR SELECT\n  USING (bucket_id = 'avatars');\n\nCREATE POLICY \"Users can upload their own avatar\"\n  ON storage.objects FOR INSERT\n  WITH CHECK (bucket_id = 'avatars' AND auth.uid()::text = (storage.foldername(name))[1]);\n\nCREATE POLICY \"Users can update their own avatar\"\n  ON storage.objects FOR UPDATE\n  USING (bucket_id = 'avatars' AND auth.uid()::text = (storage.foldername(name))[1]);\n\nCREATE POLICY \"Users can delete their own avatar\"\n  ON storage.objects FOR DELETE\n  USING (bucket_id = 'avatars' AND auth.uid()::text = (storage.foldername(name))[1]);\n\n-- 8. Storage policies for attachments\nCREATE POLICY \"Attachments are publicly accessible for viewing\"\n  ON storage.objects FOR SELECT\n  USING (bucket_id = 'attachments');\n\nCREATE POLICY \"Authenticated users can upload attachments\"\n  ON storage.objects FOR INSERT\n  WITH CHECK (bucket_id = 'attachments' AND auth.uid() IS NOT NULL);\n\nCREATE POLICY \"Users can delete their own attachments\"\n  ON storage.objects FOR DELETE\n  USING (bucket_id = 'attachments' AND auth.uid()::text = (storage.foldername(name))[1]);\n\n-- 9. Add is_read tracking for announcements per user\nCREATE TABLE IF NOT EXISTS public.announcement_reads (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  announcement_id uuid NOT NULL REFERENCES public.announcements(id) ON DELETE CASCADE,\n  user_id uuid NOT NULL,\n  read_at timestamp with time zone NOT NULL DEFAULT now(),\n  UNIQUE(announcement_id, user_id)\n);\n\n-- Enable RLS on announcement_reads\nALTER TABLE public.announcement_reads ENABLE ROW LEVEL SECURITY;\n\n-- Announcement reads policies\nCREATE POLICY \"Users can view their own announcement reads\"\n  ON public.announcement_reads FOR SELECT\n  USING (user_id = auth.uid());\n\nCREATE POLICY \"Users can mark announcements as read\"\n  ON public.announcement_reads FOR INSERT\n  WITH CHECK (user_id = auth.uid());\n\n-- 10. Update is_read policy for direct_messages - allow receiver to update is_read\nDROP POLICY IF EXISTS \"Users can update read status\" ON public.direct_messages;\nCREATE POLICY \"Users can update read status of their received messages\"\n  ON public.direct_messages FOR UPDATE\n  USING (receiver_id = get_current_profile_id())\n  WITH CHECK (receiver_id = get_current_profile_id());\n\n-- 11. Create index for faster queries\nCREATE INDEX IF NOT EXISTS idx_attachments_message_id ON public.attachments(message_id);\nCREATE INDEX IF NOT EXISTS idx_attachments_direct_message_id ON public.attachments(direct_message_id);\nCREATE INDEX IF NOT EXISTS idx_attachments_announcement_id ON public.attachments(announcement_id);\nCREATE INDEX IF NOT EXISTS idx_user_presence_user_id ON public.user_presence(user_id);\nCREATE INDEX IF NOT EXISTS idx_announcement_reads_user_id ON public.announcement_reads(user_id);\nCREATE INDEX IF NOT EXISTS idx_profiles_user_status ON public.profiles(user_status);\nCREATE INDEX IF NOT EXISTS idx_profiles_birth_date ON public.profiles(birth_date);\n\n-- Enable realtime for direct_messages if not already\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM pg_publication_tables \n    WHERE pubname = 'supabase_realtime' AND tablename = 'direct_messages'\n  ) THEN\n    ALTER PUBLICATION supabase_realtime ADD TABLE public.direct_messages;\n  END IF;\nEND\n$$;\n\n-- Enable realtime for announcement_reads\nALTER PUBLICATION supabase_realtime ADD TABLE public.announcement_reads;"], ["20260118010739_84826817-dd7f-40e3-8b80-5a0d6d3e44a5.sql", "\n-- Add unique constraint on announcement_reads for upsert\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1 FROM pg_constraint WHERE conname = 'announcement_reads_user_announcement_unique'\n  ) THEN\n    ALTER TABLE public.announcement_reads ADD CONSTRAINT announcement_reads_user_announcement_unique UNIQUE (user_id, announcement_id);\n  END IF;\nEND $$;\n\n-- Create index for faster queries on birth_date for birthdays\nCREATE INDEX IF NOT EXISTS idx_profiles_birth_date ON public.profiles (birth_date);\n\n-- Create function to check if user is active (for use in auth)\nCREATE OR REPLACE FUNCTION public.check_user_is_active()\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT COALESCE(\n    (SELECT is_active FROM public.profiles WHERE user_id = auth.uid() LIMIT 1),\n    false\n  );\n$$;\n"], ["20260119005315_d1d3e3d9-1cd1-46b2-acc3-480b6276a8c8.sql", "-- Create private_groups table for group chat functionality\nCREATE TABLE IF NOT EXISTS public.private_groups (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  name TEXT NOT NULL,\n  description TEXT,\n  avatar_url TEXT,\n  created_by UUID NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Create private_group_members table\nCREATE TABLE IF NOT EXISTS public.private_group_members (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  group_id UUID NOT NULL REFERENCES public.private_groups(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL,\n  profile_id UUID NOT NULL,\n  role TEXT NOT NULL DEFAULT 'member', -- 'admin', 'member'\n  joined_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  UNIQUE(group_id, profile_id)\n);\n\n-- Create private_group_messages table\nCREATE TABLE IF NOT EXISTS public.private_group_messages (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  group_id UUID NOT NULL REFERENCES public.private_groups(id) ON DELETE CASCADE,\n  sender_id UUID NOT NULL REFERENCES public.profiles(id),\n  content TEXT NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Create private_group_message_reads table\nCREATE TABLE IF NOT EXISTS public.private_group_message_reads (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  group_id UUID NOT NULL REFERENCES public.private_groups(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL,\n  last_read_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  UNIQUE(group_id, user_id)\n);\n\n-- Enable RLS\nALTER TABLE public.private_groups ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.private_group_members ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.private_group_messages ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.private_group_message_reads ENABLE ROW LEVEL SECURITY;\n\n-- RLS Policies for private_groups\nCREATE POLICY \"Users can view groups they are members of\"\nON public.private_groups FOR SELECT\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.private_group_members\n    WHERE group_id = id AND user_id = auth.uid()\n  )\n);\n\nCREATE POLICY \"Authenticated users can create groups\"\nON public.private_groups FOR INSERT\nWITH CHECK (auth.uid() IS NOT NULL);\n\nCREATE POLICY \"Group admins can update their groups\"\nON public.private_groups FOR UPDATE\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.private_group_members\n    WHERE group_id = id AND user_id = auth.uid() AND role = 'admin'\n  )\n);\n\nCREATE POLICY \"Group admins can delete their groups\"\nON public.private_groups FOR DELETE\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.private_group_members\n    WHERE group_id = id AND user_id = auth.uid() AND role = 'admin'\n  )\n);\n\n-- RLS Policies for private_group_members\nCREATE POLICY \"Users can view members of groups they are in\"\nON public.private_group_members FOR SELECT\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.private_group_members m\n    WHERE m.group_id = private_group_members.group_id AND m.user_id = auth.uid()\n  )\n);\n\nCREATE POLICY \"Group admins can add members\"\nON public.private_group_members FOR INSERT\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM public.private_group_members\n    WHERE group_id = private_group_members.group_id AND user_id = auth.uid() AND role = 'admin'\n  ) OR\n  -- Allow creator to add themselves as first member\n  NOT EXISTS (\n    SELECT 1 FROM public.private_group_members WHERE group_id = private_group_members.group_id\n  )\n);\n\nCREATE POLICY \"Group admins can remove members\"\nON public.private_group_members FOR DELETE\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.private_group_members m\n    WHERE m.group_id = private_group_members.group_id AND m.user_id = auth.uid() AND m.role = 'admin'\n  ) OR user_id = auth.uid() -- Users can leave groups\n);\n\n-- RLS Policies for private_group_messages\nCREATE POLICY \"Users can view messages in their groups\"\nON public.private_group_messages FOR SELECT\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.private_group_members\n    WHERE group_id = private_group_messages.group_id AND user_id = auth.uid()\n  )\n);\n\nCREATE POLICY \"Group members can send messages\"\nON public.private_group_messages FOR INSERT\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM public.private_group_members\n    WHERE group_id = private_group_messages.group_id AND user_id = auth.uid()\n  ) AND sender_id = (SELECT id FROM public.profiles WHERE user_id = auth.uid())\n);\n\n-- RLS Policies for private_group_message_reads\nCREATE POLICY \"Users can view their read status\"\nON public.private_group_message_reads FOR SELECT\nUSING (user_id = auth.uid());\n\nCREATE POLICY \"Users can update their read status\"\nON public.private_group_message_reads FOR INSERT\nWITH CHECK (user_id = auth.uid());\n\nCREATE POLICY \"Users can update their own read status\"\nON public.private_group_message_reads FOR UPDATE\nUSING (user_id = auth.uid());\n\n-- Indexes for performance\nCREATE INDEX IF NOT EXISTS idx_private_group_members_user_id ON public.private_group_members(user_id);\nCREATE INDEX IF NOT EXISTS idx_private_group_members_group_id ON public.private_group_members(group_id);\nCREATE INDEX IF NOT EXISTS idx_private_group_messages_group_id ON public.private_group_messages(group_id);\nCREATE INDEX IF NOT EXISTS idx_private_group_messages_created_at ON public.private_group_messages(created_at DESC);\n\n-- Trigger for updated_at\nCREATE TRIGGER update_private_groups_updated_at\nBEFORE UPDATE ON public.private_groups\nFOR EACH ROW\nEXECUTE FUNCTION public.update_updated_at_column();\n\n-- Enable realtime for group messages\nALTER PUBLICATION supabase_realtime ADD TABLE public.private_group_messages;"], ["20260121004041_b4a07d8f-9aaf-4418-81d2-01b0ac91e06a.sql", "-- Create table to store facial descriptors for users\nCREATE TABLE public.user_facial_data (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  user_id UUID NOT NULL UNIQUE,\n  profile_id UUID NOT NULL UNIQUE,\n  facial_descriptors JSONB NOT NULL, -- Array of 128-dimensional face descriptors\n  face_image_url TEXT, -- Optional reference image\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  registered_by UUID NOT NULL -- Who registered this face\n);\n\n-- Enable RLS\nALTER TABLE public.user_facial_data ENABLE ROW LEVEL SECURITY;\n\n-- Users can view their own facial data\nCREATE POLICY \"Users can view their own facial data\"\nON public.user_facial_data\nFOR SELECT\nUSING (user_id = auth.uid());\n\n-- Admins can view all facial data\nCREATE POLICY \"Admins can view all facial data\"\nON public.user_facial_data\nFOR SELECT\nUSING (is_admin());\n\n-- Admins can insert facial data for anyone\nCREATE POLICY \"Admins can insert facial data\"\nON public.user_facial_data\nFOR INSERT\nWITH CHECK (is_admin());\n\n-- Users can insert their own facial data\nCREATE POLICY \"Users can insert their own facial data\"\nON public.user_facial_data\nFOR INSERT\nWITH CHECK (user_id = auth.uid());\n\n-- Admins can update any facial data\nCREATE POLICY \"Admins can update any facial data\"\nON public.user_facial_data\nFOR UPDATE\nUSING (is_admin());\n\n-- Users can update their own facial data\nCREATE POLICY \"Users can update their own facial data\"\nON public.user_facial_data\nFOR UPDATE\nUSING (user_id = auth.uid());\n\n-- Admins can delete any facial data\nCREATE POLICY \"Admins can delete any facial data\"\nON public.user_facial_data\nFOR DELETE\nUSING (is_admin());\n\n-- Users can delete their own facial data\nCREATE POLICY \"Users can delete their own facial data\"\nON public.user_facial_data\nFOR DELETE\nUSING (user_id = auth.uid());\n\n-- Create trigger for updated_at\nCREATE TRIGGER update_user_facial_data_updated_at\nBEFORE UPDATE ON public.user_facial_data\nFOR EACH ROW\nEXECUTE FUNCTION public.update_updated_at_column();\n\n-- Create storage bucket for face images (optional reference images)\nINSERT INTO storage.buckets (id, name, public) VALUES ('face-images', 'face-images', false);\n\n-- Storage policies for face images\nCREATE POLICY \"Users can upload their own face images\"\nON storage.objects\nFOR INSERT\nWITH CHECK (bucket_id = 'face-images' AND auth.uid()::text = (storage.foldername(name))[1]);\n\nCREATE POLICY \"Users can view their own face images\"\nON storage.objects\nFOR SELECT\nUSING (bucket_id = 'face-images' AND (auth.uid()::text = (storage.foldername(name))[1] OR is_admin()));\n\nCREATE POLICY \"Admins can manage all face images\"\nON storage.objects\nFOR ALL\nUSING (bucket_id = 'face-images' AND is_admin());"], ["20260205015326_2ca6c876-f5b1-41df-9116-b9a297379f0a.sql", "-- Create table for important announcements (comunicados importantes)\nCREATE TABLE public.important_announcements (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  title TEXT NOT NULL,\n  content TEXT NOT NULL,\n  border_style TEXT NOT NULL DEFAULT 'gradient-blue',\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  created_by UUID NOT NULL,\n  start_at TIMESTAMP WITH TIME ZONE,\n  expire_at TIMESTAMP WITH TIME ZONE,\n  is_active BOOLEAN NOT NULL DEFAULT true\n);\n\n-- Create table to track which users have seen the announcement\nCREATE TABLE public.important_announcement_reads (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  announcement_id UUID NOT NULL REFERENCES public.important_announcements(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL,\n  read_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  UNIQUE(announcement_id, user_id)\n);\n\n-- Enable RLS\nALTER TABLE public.important_announcements ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.important_announcement_reads ENABLE ROW LEVEL SECURITY;\n\n-- RLS policies for important_announcements\n-- All authenticated users can view active announcements\nCREATE POLICY \"Anyone can view active important announcements\"\nON public.important_announcements\nFOR SELECT\nTO authenticated\nUSING (is_active = true);\n\n-- Only admins can create/update/delete\nCREATE POLICY \"Admins can manage important announcements\"\nON public.important_announcements\nFOR ALL\nTO authenticated\nUSING (public.is_admin())\nWITH CHECK (public.is_admin());\n\n-- RLS policies for important_announcement_reads\n-- Users can view their own reads\nCREATE POLICY \"Users can view own announcement reads\"\nON public.important_announcement_reads\nFOR SELECT\nTO authenticated\nUSING (auth.uid() = user_id);\n\n-- Users can mark announcements as read\nCREATE POLICY \"Users can mark announcements as read\"\nON public.important_announcement_reads\nFOR INSERT\nTO authenticated\nWITH CHECK (auth.uid() = user_id);\n\n-- Enable realtime for important_announcements\nALTER PUBLICATION supabase_realtime ADD TABLE public.important_announcements;"], ["20260205023620_1607d0dc-9a11-42fd-beb6-1b4ee75dc83c.sql", "-- Fix RLS policies for private_groups to allow proper group creation\nDROP POLICY IF EXISTS \"Users can view groups they are members of\" ON public.private_groups;\nDROP POLICY IF EXISTS \"Authenticated users can create groups\" ON public.private_groups;\nDROP POLICY IF EXISTS \"Group admins can update their groups\" ON public.private_groups;\nDROP POLICY IF EXISTS \"Group admins can delete their groups\" ON public.private_groups;\n\n-- Create proper policies for private_groups\nCREATE POLICY \"Members can view their groups\"\nON public.private_groups\nFOR SELECT\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.private_group_members\n    WHERE private_group_members.group_id = private_groups.id\n    AND private_group_members.user_id = auth.uid()\n  )\n);\n\nCREATE POLICY \"Authenticated users can create groups\"\nON public.private_groups\nFOR INSERT\nWITH CHECK (auth.uid() IS NOT NULL AND created_by = auth.uid());\n\nCREATE POLICY \"Group admins can update their groups\"\nON public.private_groups\nFOR UPDATE\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.private_group_members\n    WHERE private_group_members.group_id = private_groups.id\n    AND private_group_members.user_id = auth.uid()\n    AND private_group_members.role = 'admin'\n  )\n);\n\nCREATE POLICY \"Group admins can delete their groups\"\nON public.private_groups\nFOR DELETE\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.private_group_members\n    WHERE private_group_members.group_id = private_groups.id\n    AND private_group_members.user_id = auth.uid()\n    AND private_group_members.role = 'admin'\n  )\n);\n\n-- Fix RLS policies for private_group_members\nDROP POLICY IF EXISTS \"Group admins can add members\" ON public.private_group_members;\nDROP POLICY IF EXISTS \"Users can view members of groups they are in\" ON public.private_group_members;\n\n-- Policy for viewing members\nCREATE POLICY \"Members can view group members\"\nON public.private_group_members\nFOR SELECT\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.private_group_members m\n    WHERE m.group_id = private_group_members.group_id\n    AND m.user_id = auth.uid()\n  )\n);\n\n-- Policy for adding members - admin can add OR creator adding themselves as first member\nCREATE POLICY \"Admins can add members\"\nON public.private_group_members\nFOR INSERT\nWITH CHECK (\n  -- Allow admins to add members\n  EXISTS (\n    SELECT 1 FROM public.private_group_members m\n    WHERE m.group_id = private_group_members.group_id\n    AND m.user_id = auth.uid()\n    AND m.role = 'admin'\n  )\n  OR \n  -- Allow creator to add themselves as first member\n  (\n    user_id = auth.uid()\n    AND NOT EXISTS (\n      SELECT 1 FROM public.private_group_members m\n      WHERE m.group_id = private_group_members.group_id\n    )\n  )\n);\n\n-- Policy for updating members (role changes)\nCREATE POLICY \"Admins can update member roles\"\nON public.private_group_members\nFOR UPDATE\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.private_group_members m\n    WHERE m.group_id = private_group_members.group_id\n    AND m.user_id = auth.uid()\n    AND m.role = 'admin'\n  )\n);\n\n-- Add new autonomy levels to app_role enum\nALTER TYPE public.app_role ADD VALUE IF NOT EXISTS 'gestor';\nALTER TYPE public.app_role ADD VALUE IF NOT EXISTS 'diretoria';\n\n-- Create tasks table for Trello-style task management\nCREATE TABLE IF NOT EXISTS public.tasks (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  task_number SERIAL,\n  title TEXT NOT NULL,\n  description TEXT,\n  status TEXT NOT NULL DEFAULT 'todo',\n  priority TEXT NOT NULL DEFAULT 'medium',\n  assigned_to UUID REFERENCES public.profiles(id),\n  created_by UUID NOT NULL,\n  sector_id UUID REFERENCES public.sectors(id),\n  due_date TIMESTAMP WITH TIME ZONE,\n  position INTEGER NOT NULL DEFAULT 0,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Enable RLS on tasks\nALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;\n\n-- Task policies\nCREATE POLICY \"Users can view tasks in their sectors\"\nON public.tasks\nFOR SELECT\nUSING (\n  is_admin() OR\n  sector_id IS NULL OR\n  sector_id = get_current_sector_id() OR\n  sector_id = '00000000-0000-0000-0000-000000000001'::uuid OR\n  EXISTS (\n    SELECT 1 FROM public.user_additional_sectors\n    WHERE user_additional_sectors.user_id = auth.uid()\n    AND user_additional_sectors.sector_id = tasks.sector_id\n  )\n);\n\nCREATE POLICY \"Users can create tasks\"\nON public.tasks\nFOR INSERT\nWITH CHECK (auth.uid() IS NOT NULL AND created_by = get_current_profile_id());\n\nCREATE POLICY \"Task creators and admins can update tasks\"\nON public.tasks\nFOR UPDATE\nUSING (\n  is_admin() OR\n  created_by = get_current_profile_id() OR\n  assigned_to = get_current_profile_id()\n);\n\nCREATE POLICY \"Task creators and admins can delete tasks\"\nON public.tasks\nFOR DELETE\nUSING (\n  is_admin() OR created_by = get_current_profile_id()\n);\n\n-- Create task comments table\nCREATE TABLE IF NOT EXISTS public.task_comments (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  task_id UUID NOT NULL REFERENCES public.tasks(id) ON DELETE CASCADE,\n  author_id UUID NOT NULL REFERENCES public.profiles(id),\n  content TEXT NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.task_comments ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Users can view task comments\"\nON public.task_comments\nFOR SELECT\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.tasks WHERE tasks.id = task_comments.task_id\n  )\n);\n\nCREATE POLICY \"Users can create task comments\"\nON public.task_comments\nFOR INSERT\nWITH CHECK (auth.uid() IS NOT NULL AND author_id = get_current_profile_id());\n\nCREATE POLICY \"Authors can delete their comments\"\nON public.task_comments\nFOR DELETE\nUSING (author_id = get_current_profile_id() OR is_admin());\n\n-- Create trigger for tasks updated_at\nCREATE TRIGGER update_tasks_updated_at\nBEFORE UPDATE ON public.tasks\nFOR EACH ROW\nEXECUTE FUNCTION public.update_updated_at_column();\n\n-- Enable realtime for tasks\nALTER PUBLICATION supabase_realtime ADD TABLE public.tasks;\nALTER PUBLICATION supabase_realtime ADD TABLE public.task_comments;"], ["20260205025443_b32a5d4e-503e-41e1-b468-2a628cf9ed96.sql", "-- Fix infinite recursion in private_group_members policies\n-- Drop all existing policies on private_group_members\nDROP POLICY IF EXISTS \"Members can view group members\" ON private_group_members;\nDROP POLICY IF EXISTS \"Admins can add members\" ON private_group_members;\nDROP POLICY IF EXISTS \"Admins can update member roles\" ON private_group_members;\nDROP POLICY IF EXISTS \"Group admins can remove members\" ON private_group_members;\n\n-- Create a function to check if user is a group member without recursion\nCREATE OR REPLACE FUNCTION is_group_member(check_group_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1 FROM private_group_members\n    WHERE group_id = check_group_id AND user_id = auth.uid()\n  );\n$$;\n\n-- Create a function to check if user is a group admin without recursion\nCREATE OR REPLACE FUNCTION is_group_admin(check_group_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1 FROM private_group_members\n    WHERE group_id = check_group_id AND user_id = auth.uid() AND role = 'admin'\n  );\n$$;\n\n-- Create a function to check if a group has no members (for first member insertion)\nCREATE OR REPLACE FUNCTION is_group_empty(check_group_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT NOT EXISTS (\n    SELECT 1 FROM private_group_members WHERE group_id = check_group_id\n  );\n$$;\n\n-- Recreate policies without recursion using the new functions\nCREATE POLICY \"Members can view group members\" ON private_group_members\n  FOR SELECT USING (is_group_member(group_id));\n\nCREATE POLICY \"Admins can add members\" ON private_group_members\n  FOR INSERT WITH CHECK (\n    is_group_admin(group_id) OR \n    (user_id = auth.uid() AND is_group_empty(group_id))\n  );\n\nCREATE POLICY \"Admins can update member roles\" ON private_group_members\n  FOR UPDATE USING (is_group_admin(group_id));\n\nCREATE POLICY \"Group admins can remove members\" ON private_group_members\n  FOR DELETE USING (is_group_admin(group_id) OR user_id = auth.uid());\n\n-- Also fix private_groups policies to avoid recursion\nDROP POLICY IF EXISTS \"Members can view their groups\" ON private_groups;\nDROP POLICY IF EXISTS \"Group admins can update their groups\" ON private_groups;\nDROP POLICY IF EXISTS \"Group admins can delete their groups\" ON private_groups;\n\n-- Function to check if user is member of a group by group id\nCREATE OR REPLACE FUNCTION user_is_member_of_group(check_group_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1 FROM private_group_members\n    WHERE group_id = check_group_id AND user_id = auth.uid()\n  );\n$$;\n\nCREATE POLICY \"Members can view their groups\" ON private_groups\n  FOR SELECT USING (user_is_member_of_group(id) OR created_by = auth.uid());\n\nCREATE POLICY \"Group admins can update their groups\" ON private_groups\n  FOR UPDATE USING (is_group_admin(id));\n\nCREATE POLICY \"Group admins can delete their groups\" ON private_groups\n  FOR DELETE USING (is_group_admin(id));"], ["20260205025731_3d12c787-85bd-4f5e-8b1e-f9d021f515ef.sql", "-- Allow admins to update any profile (for activating/deactivating users)\nCREATE POLICY \"Admins can update any profile\" ON profiles\n  FOR UPDATE USING (is_admin())\n  WITH CHECK (is_admin());"], ["20260205222610_c2c3ccb8-8f2d-459c-a281-4f5ab68c086e.sql", "\n-- Create task_boards table for individual boards/murals\nCREATE TABLE public.task_boards (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  name text NOT NULL,\n  description text,\n  owner_id uuid NOT NULL,\n  background_image text DEFAULT 'default',\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now()\n);\n\n-- Create task_board_members table\nCREATE TABLE public.task_board_members (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  board_id uuid NOT NULL REFERENCES public.task_boards(id) ON DELETE CASCADE,\n  user_id uuid NOT NULL,\n  profile_id uuid NOT NULL,\n  role text NOT NULL DEFAULT 'member',\n  joined_at timestamp with time zone NOT NULL DEFAULT now(),\n  UNIQUE(board_id, user_id)\n);\n\n-- Create task_board_columns for custom columns\nCREATE TABLE public.task_board_columns (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  board_id uuid NOT NULL REFERENCES public.task_boards(id) ON DELETE CASCADE,\n  title text NOT NULL,\n  color text NOT NULL DEFAULT '#6366f1',\n  position integer NOT NULL DEFAULT 0,\n  created_at timestamp with time zone NOT NULL DEFAULT now()\n);\n\n-- Add board_id and cover_image to tasks\nALTER TABLE public.tasks ADD COLUMN IF NOT EXISTS board_id uuid REFERENCES public.task_boards(id) ON DELETE CASCADE;\nALTER TABLE public.tasks ADD COLUMN IF NOT EXISTS cover_image text;\n\n-- Enable RLS\nALTER TABLE public.task_boards ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.task_board_members ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.task_board_columns ENABLE ROW LEVEL SECURITY;\n\n-- Helper function: check if user is board member or owner\nCREATE OR REPLACE FUNCTION public.is_board_member(check_board_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE SECURITY DEFINER\nSET search_path TO 'public'\nAS $$\n  SELECT EXISTS (\n    SELECT 1 FROM task_boards WHERE id = check_board_id AND owner_id = auth.uid()\n  ) OR EXISTS (\n    SELECT 1 FROM task_board_members WHERE board_id = check_board_id AND user_id = auth.uid()\n  );\n$$;\n\nCREATE OR REPLACE FUNCTION public.is_board_owner(check_board_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE SECURITY DEFINER\nSET search_path TO 'public'\nAS $$\n  SELECT EXISTS (\n    SELECT 1 FROM task_boards WHERE id = check_board_id AND owner_id = auth.uid()\n  );\n$$;\n\n-- task_boards policies\nCREATE POLICY \"Users can create boards\" ON public.task_boards\n  FOR INSERT WITH CHECK (auth.uid() IS NOT NULL AND owner_id = auth.uid());\n\nCREATE POLICY \"Board members and owners can view boards\" ON public.task_boards\n  FOR SELECT USING (is_board_member(id) OR owner_id = auth.uid());\n\nCREATE POLICY \"Board owners can update boards\" ON public.task_boards\n  FOR UPDATE USING (owner_id = auth.uid());\n\nCREATE POLICY \"Board owners can delete boards\" ON public.task_boards\n  FOR DELETE USING (owner_id = auth.uid());\n\n-- task_board_members policies\nCREATE POLICY \"Board owners can manage members\" ON public.task_board_members\n  FOR ALL USING (is_board_owner(board_id)) WITH CHECK (is_board_owner(board_id));\n\nCREATE POLICY \"Members can view board members\" ON public.task_board_members\n  FOR SELECT USING (is_board_member(board_id));\n\nCREATE POLICY \"Members can leave boards\" ON public.task_board_members\n  FOR DELETE USING (user_id = auth.uid());\n\n-- task_board_columns policies\nCREATE POLICY \"Board members can view columns\" ON public.task_board_columns\n  FOR SELECT USING (is_board_member(board_id));\n\nCREATE POLICY \"Board owners can manage columns\" ON public.task_board_columns\n  FOR ALL USING (is_board_owner(board_id)) WITH CHECK (is_board_owner(board_id));\n\nCREATE POLICY \"Board members can manage columns\" ON public.task_board_columns\n  FOR INSERT WITH CHECK (is_board_member(board_id));\n\nCREATE POLICY \"Board members can update columns\" ON public.task_board_columns\n  FOR UPDATE USING (is_board_member(board_id));\n\n-- Update tasks RLS to include board-based access\nCREATE POLICY \"Board members can view board tasks\" ON public.tasks\n  FOR SELECT USING (board_id IS NOT NULL AND is_board_member(board_id));\n\nCREATE POLICY \"Board members can create board tasks\" ON public.tasks\n  FOR INSERT WITH CHECK (board_id IS NOT NULL AND is_board_member(board_id) AND created_by = get_current_profile_id());\n\nCREATE POLICY \"Board members can update board tasks\" ON public.tasks\n  FOR UPDATE USING (board_id IS NOT NULL AND is_board_member(board_id));\n\nCREATE POLICY \"Board members can delete board tasks\" ON public.tasks\n  FOR DELETE USING (board_id IS NOT NULL AND (is_board_owner(board_id) OR created_by = get_current_profile_id()));\n\n-- Enable realtime\nALTER PUBLICATION supabase_realtime ADD TABLE public.task_boards;\nALTER PUBLICATION supabase_realtime ADD TABLE public.task_board_columns;\nALTER PUBLICATION supabase_realtime ADD TABLE public.task_board_members;\n\n-- Trigger for updated_at\nCREATE TRIGGER update_task_boards_updated_at\n  BEFORE UPDATE ON public.task_boards\n  FOR EACH ROW\n  EXECUTE FUNCTION public.update_updated_at_column();\n"], ["20260205225415_b46e7ace-bc3d-40a7-a1c8-7552a86561b7.sql", "\n-- Add automation columns to task_board_columns\nALTER TABLE public.task_board_columns ADD COLUMN auto_assign_to uuid REFERENCES public.profiles(id) ON DELETE SET NULL;\nALTER TABLE public.task_board_columns ADD COLUMN auto_cover text;\n\n-- Add CASCADE delete for task_boards children\nALTER TABLE public.task_board_columns DROP CONSTRAINT IF EXISTS task_board_columns_board_id_fkey;\nALTER TABLE public.task_board_columns ADD CONSTRAINT task_board_columns_board_id_fkey FOREIGN KEY (board_id) REFERENCES public.task_boards(id) ON DELETE CASCADE;\n\nALTER TABLE public.task_board_members DROP CONSTRAINT IF EXISTS task_board_members_board_id_fkey;\nALTER TABLE public.task_board_members ADD CONSTRAINT task_board_members_board_id_fkey FOREIGN KEY (board_id) REFERENCES public.task_boards(id) ON DELETE CASCADE;\n\n-- Tasks with board_id should cascade on board delete\nALTER TABLE public.tasks DROP CONSTRAINT IF EXISTS tasks_board_id_fkey;\nALTER TABLE public.tasks ADD CONSTRAINT tasks_board_id_fkey FOREIGN KEY (board_id) REFERENCES public.task_boards(id) ON DELETE CASCADE;\n\n-- Task comments should cascade on task delete\nALTER TABLE public.task_comments DROP CONSTRAINT IF EXISTS task_comments_task_id_fkey;\nALTER TABLE public.task_comments ADD CONSTRAINT task_comments_task_id_fkey FOREIGN KEY (task_id) REFERENCES public.tasks(id) ON DELETE CASCADE;\n"], ["20260205230827_4a1d21ff-cb27-43b1-a633-e8431f751de6.sql", "\n-- Fix: Add explicit DELETE policy for board members on columns\nCREATE POLICY \"Board members can delete columns\"\nON public.task_board_columns\nFOR DELETE\nUSING (is_board_member(board_id));\n\n-- Labels system\nCREATE TABLE public.task_labels (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  board_id uuid NOT NULL REFERENCES public.task_boards(id) ON DELETE CASCADE,\n  name text NOT NULL,\n  color text NOT NULL DEFAULT '#6366f1',\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE public.task_label_assignments (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  task_id uuid NOT NULL REFERENCES public.tasks(id) ON DELETE CASCADE,\n  label_id uuid NOT NULL REFERENCES public.task_labels(id) ON DELETE CASCADE,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(task_id, label_id)\n);\n\nALTER TABLE public.task_labels ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.task_label_assignments ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Board members can view labels\"\nON public.task_labels FOR SELECT\nUSING (is_board_member(board_id));\n\nCREATE POLICY \"Board members can create labels\"\nON public.task_labels FOR INSERT\nWITH CHECK (is_board_member(board_id));\n\nCREATE POLICY \"Board members can update labels\"\nON public.task_labels FOR UPDATE\nUSING (is_board_member(board_id));\n\nCREATE POLICY \"Board members can delete labels\"\nON public.task_labels FOR DELETE\nUSING (is_board_member(board_id));\n\nCREATE POLICY \"Board members can view label assignments\"\nON public.task_label_assignments FOR SELECT\nUSING (EXISTS (\n  SELECT 1 FROM public.tasks t\n  WHERE t.id = task_id AND t.board_id IS NOT NULL AND is_board_member(t.board_id)\n));\n\nCREATE POLICY \"Board members can assign labels\"\nON public.task_label_assignments FOR INSERT\nWITH CHECK (EXISTS (\n  SELECT 1 FROM public.tasks t\n  WHERE t.id = task_id AND t.board_id IS NOT NULL AND is_board_member(t.board_id)\n));\n\nCREATE POLICY \"Board members can remove label assignments\"\nON public.task_label_assignments FOR DELETE\nUSING (EXISTS (\n  SELECT 1 FROM public.tasks t\n  WHERE t.id = task_id AND t.board_id IS NOT NULL AND is_board_member(t.board_id)\n));\n\n-- Also fix: allow board members to delete their own tasks or board owner to delete any\nDROP POLICY IF EXISTS \"Board members can delete board tasks\" ON public.tasks;\nCREATE POLICY \"Board members can delete board tasks\"\nON public.tasks FOR DELETE\nUSING (\n  board_id IS NOT NULL AND is_board_member(board_id)\n);\n"], ["20260205231837_8c11a524-e8a5-4b1d-8621-15ed2110f3c4.sql", "\n-- Create subtasks table for individual card checklists\nCREATE TABLE public.task_subtasks (\n  id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  task_id uuid NOT NULL REFERENCES public.tasks(id) ON DELETE CASCADE,\n  title text NOT NULL,\n  is_completed boolean NOT NULL DEFAULT false,\n  position integer NOT NULL DEFAULT 0,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.task_subtasks ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Board members can view subtasks\"\n  ON public.task_subtasks FOR SELECT\n  USING (EXISTS (\n    SELECT 1 FROM public.tasks t\n    WHERE t.id = task_subtasks.task_id\n    AND public.is_board_member(t.board_id)\n  ));\n\nCREATE POLICY \"Board members can insert subtasks\"\n  ON public.task_subtasks FOR INSERT\n  WITH CHECK (EXISTS (\n    SELECT 1 FROM public.tasks t\n    WHERE t.id = task_subtasks.task_id\n    AND public.is_board_member(t.board_id)\n  ));\n\nCREATE POLICY \"Board members can update subtasks\"\n  ON public.task_subtasks FOR UPDATE\n  USING (EXISTS (\n    SELECT 1 FROM public.tasks t\n    WHERE t.id = task_subtasks.task_id\n    AND public.is_board_member(t.board_id)\n  ));\n\nCREATE POLICY \"Board members can delete subtasks\"\n  ON public.task_subtasks FOR DELETE\n  USING (EXISTS (\n    SELECT 1 FROM public.tasks t\n    WHERE t.id = task_subtasks.task_id\n    AND public.is_board_member(t.board_id)\n  ));\n"], ["20260205234855_f9ab59b4-35f2-40d6-b909-1d29853fe84b.sql", "\n-- Table for supervisors to manage their responsible collaborators\nCREATE TABLE public.supervisor_team_members (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  supervisor_id UUID NOT NULL,\n  member_profile_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  UNIQUE(supervisor_id, member_profile_id)\n);\n\nALTER TABLE public.supervisor_team_members ENABLE ROW LEVEL SECURITY;\n\n-- Supervisors can manage their own team\nCREATE POLICY \"Supervisors can view their team\"\n  ON public.supervisor_team_members FOR SELECT\n  USING (supervisor_id = auth.uid() OR is_admin());\n\nCREATE POLICY \"Supervisors can add team members\"\n  ON public.supervisor_team_members FOR INSERT\n  WITH CHECK (supervisor_id = auth.uid() OR is_admin());\n\nCREATE POLICY \"Supervisors can remove team members\"\n  ON public.supervisor_team_members FOR DELETE\n  USING (supervisor_id = auth.uid() OR is_admin());\n"], ["20260206000017_16ce1c76-ed12-46cb-901c-0083e86e2f9d.sql", "\n-- Add conclusion automation flag to columns\nALTER TABLE public.task_board_columns ADD COLUMN IF NOT EXISTS is_conclusion boolean DEFAULT false;\n\n-- Add completion tracking to tasks\nALTER TABLE public.tasks ADD COLUMN IF NOT EXISTS completed_at timestamptz;\nALTER TABLE public.tasks ADD COLUMN IF NOT EXISTS completed_late boolean DEFAULT false;\nALTER TABLE public.tasks ADD COLUMN IF NOT EXISTS delay_days integer DEFAULT 0;\n"], ["20260209012133_c564bbbc-8b64-4b1c-9f68-631677fbcdc6.sql", "\n-- Fix 1: profiles - require authentication for SELECT\nDROP POLICY IF EXISTS \"Usu\u00e1rios autenticados podem ver todos os perfis\" ON public.profiles;\nCREATE POLICY \"Usu\u00e1rios autenticados podem ver todos os perfis\"\n  ON public.profiles FOR SELECT\n  TO authenticated\n  USING (auth.uid() IS NOT NULL);\n\n-- Fix 2: user_presence - require authentication for SELECT\nDROP POLICY IF EXISTS \"Everyone can view presence\" ON public.user_presence;\nCREATE POLICY \"Authenticated users can view presence\"\n  ON public.user_presence FOR SELECT\n  TO authenticated\n  USING (auth.uid() IS NOT NULL);\n\n-- Fix 3: user_presence - restrict INSERT/UPDATE to authenticated\nDROP POLICY IF EXISTS \"Users can insert their own presence\" ON public.user_presence;\nCREATE POLICY \"Users can insert their own presence\"\n  ON public.user_presence FOR INSERT\n  TO authenticated\n  WITH CHECK (user_id = auth.uid());\n\nDROP POLICY IF EXISTS \"Users can update their own presence\" ON public.user_presence;\nCREATE POLICY \"Users can update their own presence\"\n  ON public.user_presence FOR UPDATE\n  TO authenticated\n  USING (user_id = auth.uid());\n\n-- Fix 4: tasks - require authentication for all policies currently using 'public'\nDROP POLICY IF EXISTS \"Board members can view board tasks\" ON public.tasks;\nCREATE POLICY \"Board members can view board tasks\"\n  ON public.tasks FOR SELECT\n  TO authenticated\n  USING (board_id IS NOT NULL AND is_board_member(board_id));\n\nDROP POLICY IF EXISTS \"Users can view tasks in their sectors\" ON public.tasks;\nCREATE POLICY \"Users can view tasks in their sectors\"\n  ON public.tasks FOR SELECT\n  TO authenticated\n  USING (\n    is_admin() OR\n    sector_id IS NULL OR\n    sector_id = get_current_sector_id() OR\n    sector_id = '00000000-0000-0000-0000-000000000001'::uuid OR\n    EXISTS (\n      SELECT 1 FROM user_additional_sectors\n      WHERE user_additional_sectors.user_id = auth.uid()\n        AND user_additional_sectors.sector_id = tasks.sector_id\n    )\n  );\n\nDROP POLICY IF EXISTS \"Users can create tasks\" ON public.tasks;\nCREATE POLICY \"Users can create tasks\"\n  ON public.tasks FOR INSERT\n  TO authenticated\n  WITH CHECK (auth.uid() IS NOT NULL AND created_by = get_current_profile_id());\n\nDROP POLICY IF EXISTS \"Board members can create board tasks\" ON public.tasks;\nCREATE POLICY \"Board members can create board tasks\"\n  ON public.tasks FOR INSERT\n  TO authenticated\n  WITH CHECK (board_id IS NOT NULL AND is_board_member(board_id) AND created_by = get_current_profile_id());\n\nDROP POLICY IF EXISTS \"Task creators and admins can update tasks\" ON public.tasks;\nCREATE POLICY \"Task creators and admins can update tasks\"\n  ON public.tasks FOR UPDATE\n  TO authenticated\n  USING (is_admin() OR created_by = get_current_profile_id() OR assigned_to = get_current_profile_id());\n\nDROP POLICY IF EXISTS \"Board members can update board tasks\" ON public.tasks;\nCREATE POLICY \"Board members can update board tasks\"\n  ON public.tasks FOR UPDATE\n  TO authenticated\n  USING (board_id IS NOT NULL AND is_board_member(board_id));\n\nDROP POLICY IF EXISTS \"Task creators and admins can delete tasks\" ON public.tasks;\nCREATE POLICY \"Task creators and admins can delete tasks\"\n  ON public.tasks FOR DELETE\n  TO authenticated\n  USING (is_admin() OR created_by = get_current_profile_id());\n\nDROP POLICY IF EXISTS \"Board members can delete board tasks\" ON public.tasks;\nCREATE POLICY \"Board members can delete board tasks\"\n  ON public.tasks FOR DELETE\n  TO authenticated\n  USING (board_id IS NOT NULL AND is_board_member(board_id));\n"], ["20260210012916_1c7d643f-a1d7-4e9d-af4c-412efa1dfbc8.sql", "\n-- Create audit_logs table\nCREATE TABLE public.audit_logs (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  table_name TEXT NOT NULL,\n  action TEXT NOT NULL, -- 'DELETE', 'INSERT', 'UPDATE', 'SYSTEM'\n  record_id TEXT,\n  record_data JSONB,\n  description TEXT,\n  performed_by UUID,\n  performed_by_email TEXT,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Enable RLS\nALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;\n\n-- Only the main admin can view logs\nCREATE POLICY \"Only admin can view audit logs\"\n  ON public.audit_logs FOR SELECT\n  TO authenticated\n  USING (is_admin());\n\n-- Only admin can delete logs\nCREATE POLICY \"Only admin can delete audit logs\"\n  ON public.audit_logs FOR DELETE\n  TO authenticated\n  USING (is_admin());\n\n-- Allow inserts from triggers (security definer functions)\nCREATE POLICY \"System can insert audit logs\"\n  ON public.audit_logs FOR INSERT\n  TO authenticated\n  WITH CHECK (true);\n\n-- Create index for faster queries\nCREATE INDEX idx_audit_logs_created_at ON public.audit_logs(created_at DESC);\nCREATE INDEX idx_audit_logs_table_name ON public.audit_logs(table_name);\nCREATE INDEX idx_audit_logs_action ON public.audit_logs(action);\n\n-- Create a generic audit trigger function\nCREATE OR REPLACE FUNCTION public.log_deletion()\nRETURNS TRIGGER\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  performer_id UUID;\n  performer_email TEXT;\n  record_desc TEXT;\nBEGIN\n  performer_id := auth.uid();\n  \n  SELECT email INTO performer_email\n  FROM public.profiles\n  WHERE user_id = performer_id\n  LIMIT 1;\n\n  -- Build a meaningful description based on the table\n  record_desc := TG_TABLE_NAME || ' record deleted';\n  \n  IF TG_TABLE_NAME = 'profiles' THEN\n    record_desc := 'Perfil exclu\u00eddo: ' || COALESCE(OLD.name, OLD.email, OLD.id::text);\n  ELSIF TG_TABLE_NAME = 'messages' THEN\n    record_desc := 'Mensagem exclu\u00edda do chat';\n  ELSIF TG_TABLE_NAME = 'announcements' THEN\n    record_desc := 'Aviso exclu\u00eddo: ' || COALESCE(OLD.title, OLD.id::text);\n  ELSIF TG_TABLE_NAME = 'direct_messages' THEN\n    record_desc := 'Mensagem direta exclu\u00edda';\n  ELSIF TG_TABLE_NAME = 'tasks' THEN\n    record_desc := 'Tarefa exclu\u00edda: ' || COALESCE(OLD.title, OLD.id::text);\n  ELSIF TG_TABLE_NAME = 'sectors' THEN\n    record_desc := 'Setor exclu\u00eddo: ' || COALESCE(OLD.name, OLD.id::text);\n  ELSIF TG_TABLE_NAME = 'task_boards' THEN\n    record_desc := 'Quadro exclu\u00eddo: ' || COALESCE(OLD.name, OLD.id::text);\n  ELSIF TG_TABLE_NAME = 'private_groups' THEN\n    record_desc := 'Grupo privado exclu\u00eddo: ' || COALESCE(OLD.name, OLD.id::text);\n  ELSIF TG_TABLE_NAME = 'important_announcements' THEN\n    record_desc := 'Comunicado importante exclu\u00eddo: ' || COALESCE(OLD.title, OLD.id::text);\n  ELSIF TG_TABLE_NAME = 'user_roles' THEN\n    record_desc := 'Role removida: ' || OLD.role::text;\n  ELSIF TG_TABLE_NAME = 'user_permissions' THEN\n    record_desc := 'Permiss\u00f5es removidas';\n  ELSIF TG_TABLE_NAME = 'attachments' THEN\n    record_desc := 'Anexo exclu\u00eddo: ' || COALESCE(OLD.file_name, OLD.id::text);\n  END IF;\n\n  INSERT INTO public.audit_logs (table_name, action, record_id, record_data, description, performed_by, performed_by_email)\n  VALUES (\n    TG_TABLE_NAME,\n    'DELETE',\n    OLD.id::text,\n    to_jsonb(OLD),\n    record_desc,\n    performer_id,\n    COALESCE(performer_email, 'sistema')\n  );\n\n  RETURN OLD;\nEND;\n$$;\n\n-- Attach triggers to key tables\nCREATE TRIGGER audit_profiles_delete BEFORE DELETE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.log_deletion();\nCREATE TRIGGER audit_messages_delete BEFORE DELETE ON public.messages FOR EACH ROW EXECUTE FUNCTION public.log_deletion();\nCREATE TRIGGER audit_announcements_delete BEFORE DELETE ON public.announcements FOR EACH ROW EXECUTE FUNCTION public.log_deletion();\nCREATE TRIGGER audit_direct_messages_delete BEFORE DELETE ON public.direct_messages FOR EACH ROW EXECUTE FUNCTION public.log_deletion();\nCREATE TRIGGER audit_tasks_delete BEFORE DELETE ON public.tasks FOR EACH ROW EXECUTE FUNCTION public.log_deletion();\nCREATE TRIGGER audit_sectors_delete BEFORE DELETE ON public.sectors FOR EACH ROW EXECUTE FUNCTION public.log_deletion();\nCREATE TRIGGER audit_task_boards_delete BEFORE DELETE ON public.task_boards FOR EACH ROW EXECUTE FUNCTION public.log_deletion();\nCREATE TRIGGER audit_private_groups_delete BEFORE DELETE ON public.private_groups FOR EACH ROW EXECUTE FUNCTION public.log_deletion();\nCREATE TRIGGER audit_important_announcements_delete BEFORE DELETE ON public.important_announcements FOR EACH ROW EXECUTE FUNCTION public.log_deletion();\nCREATE TRIGGER audit_user_roles_delete BEFORE DELETE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.log_deletion();\nCREATE TRIGGER audit_user_permissions_delete BEFORE DELETE ON public.user_permissions FOR EACH ROW EXECUTE FUNCTION public.log_deletion();\nCREATE TRIGGER audit_attachments_delete BEFORE DELETE ON public.attachments FOR EACH ROW EXECUTE FUNCTION public.log_deletion();\n"], ["20260211004916_4ffc196d-34e8-49e3-8caf-f535661d012c.sql", "\n-- ==============================================\n-- FIX 1: Profiles table - restrict SELECT policy\n-- Currently ANY authenticated user can see ALL profiles.\n-- We'll create a view that hides sensitive fields (phone, address, birth_date, registration_number)\n-- and restrict the base table policy.\n-- ==============================================\n\n-- Drop the overly permissive SELECT policy\nDROP POLICY IF EXISTS \"Usu\u00e1rios autenticados podem ver todos os perfis\" ON public.profiles;\n\n-- Create a more restrictive SELECT policy:\n-- Users can see all profiles but we limit WHICH columns via a view\n-- Since profiles are needed for chat, presence, task assignment etc., \n-- we keep authenticated access but create a safe view for sensitive data\nCREATE POLICY \"Authenticated users can view profiles\"\nON public.profiles\nFOR SELECT\nUSING (auth.uid() IS NOT NULL AND public.check_user_is_active());\n\n-- ==============================================\n-- FIX 2: User facial data - add stricter access\n-- Remove the policy that lets users view their own facial descriptors directly\n-- Facial data should only be accessible via edge functions\n-- ==============================================\n\n-- Drop permissive user-level SELECT on facial data\nDROP POLICY IF EXISTS \"Users can view their own facial data\" ON public.user_facial_data;\nDROP POLICY IF EXISTS \"Users can update their own facial data\" ON public.user_facial_data;\nDROP POLICY IF EXISTS \"Users can delete their own facial data\" ON public.user_facial_data;\nDROP POLICY IF EXISTS \"Users can insert their own facial data\" ON public.user_facial_data;\n\n-- Facial data should ONLY be managed through edge functions (service role)\n-- Users should NOT have direct access to biometric data\n-- Admin policies remain for management purposes\n"], ["20260216200210_c6966a64-1ba6-4aa1-b608-7c1da7f53b68.sql", "-- Allow group admins to delete group messages\nCREATE POLICY \"Group admins can delete messages\"\nON public.private_group_messages\nFOR DELETE\nUSING (is_group_admin(group_id));\n\n-- Allow group admins to delete message reads\nCREATE POLICY \"Group admins can delete message reads\"\nON public.private_group_message_reads\nFOR DELETE\nUSING (is_group_admin(group_id));\n"], ["20260216201822_73751a85-692e-49a7-adc2-f8b3a925d4c5.sql", "-- Allow all authenticated users to read the weekly_file_limit setting\nCREATE POLICY \"Authenticated users can read weekly_file_limit\"\nON public.system_settings\nFOR SELECT\nUSING (auth.uid() IS NOT NULL AND key = 'weekly_file_limit');\n"], ["20260217031608_b9d4325d-9bfc-4b12-82f9-84814ad40a42.sql", "\n-- Fix RLS on system_settings: drop restrictive policy and create permissive one for weekly_file_limit\nDROP POLICY IF EXISTS \"Authenticated users can read weekly_file_limit\" ON public.system_settings;\n\n-- Create a PERMISSIVE policy so non-admin users can read weekly_file_limit\nCREATE POLICY \"Anyone authenticated can read weekly_file_limit\"\nON public.system_settings\nFOR SELECT\nUSING (auth.uid() IS NOT NULL AND key = 'weekly_file_limit');\n\n-- Add ip_address column to audit_logs for tracking\nALTER TABLE public.audit_logs ADD COLUMN IF NOT EXISTS ip_address text;\n\n-- Update log_deletion trigger to support ip from session variable\nCREATE OR REPLACE FUNCTION public.log_deletion()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path TO 'public'\nAS $function$\nDECLARE\n  performer_id UUID;\n  performer_email TEXT;\n  record_desc TEXT;\n  client_ip TEXT;\nBEGIN\n  performer_id := auth.uid();\n  \n  SELECT email INTO performer_email\n  FROM public.profiles\n  WHERE user_id = performer_id\n  LIMIT 1;\n\n  -- Try to get client IP from session variable\n  BEGIN\n    client_ip := current_setting('app.client_ip', true);\n  EXCEPTION WHEN OTHERS THEN\n    client_ip := NULL;\n  END;\n\n  -- Build a meaningful description based on the table\n  record_desc := TG_TABLE_NAME || ' record deleted';\n  \n  IF TG_TABLE_NAME = 'profiles' THEN\n    record_desc := 'Perfil exclu\u00eddo: ' || COALESCE(OLD.name, OLD.email, OLD.id::text);\n  ELSIF TG_TABLE_NAME = 'messages' THEN\n    record_desc := 'Mensagem exclu\u00edda do chat';\n  ELSIF TG_TABLE_NAME = 'announcements' THEN\n    record_desc := 'Aviso exclu\u00eddo: ' || COALESCE(OLD.title, OLD.id::text);\n  ELSIF TG_TABLE_NAME = 'direct_messages' THEN\n    record_desc := 'Mensagem direta exclu\u00edda';\n  ELSIF TG_TABLE_NAME = 'tasks' THEN\n    record_desc := 'Tarefa exclu\u00edda: ' || COALESCE(OLD.title, OLD.id::text);\n  ELSIF TG_TABLE_NAME = 'sectors' THEN\n    record_desc := 'Setor exclu\u00eddo: ' || COALESCE(OLD.name, OLD.id::text);\n  ELSIF TG_TABLE_NAME = 'task_boards' THEN\n    record_desc := 'Quadro exclu\u00eddo: ' || COALESCE(OLD.name, OLD.id::text);\n  ELSIF TG_TABLE_NAME = 'private_groups' THEN\n    record_desc := 'Grupo privado exclu\u00eddo: ' || COALESCE(OLD.name, OLD.id::text);\n  ELSIF TG_TABLE_NAME = 'important_announcements' THEN\n    record_desc := 'Comunicado importante exclu\u00eddo: ' || COALESCE(OLD.title, OLD.id::text);\n  ELSIF TG_TABLE_NAME = 'user_roles' THEN\n    record_desc := 'Role removida: ' || OLD.role::text;\n  ELSIF TG_TABLE_NAME = 'user_permissions' THEN\n    record_desc := 'Permiss\u00f5es removidas';\n  ELSIF TG_TABLE_NAME = 'attachments' THEN\n    record_desc := 'Anexo exclu\u00eddo: ' || COALESCE(OLD.file_name, OLD.id::text);\n  END IF;\n\n  INSERT INTO public.audit_logs (table_name, action, record_id, record_data, description, performed_by, performed_by_email, ip_address)\n  VALUES (\n    TG_TABLE_NAME,\n    'DELETE',\n    OLD.id::text,\n    to_jsonb(OLD),\n    record_desc,\n    performer_id,\n    COALESCE(performer_email, 'sistema'),\n    client_ip\n  );\n\n  RETURN OLD;\nEND;\n$function$;\n"], ["20260218031532_0ebc5f08-4739-4a43-ad18-04c70f165070.sql", "\n-- Fix system_settings RLS: the restrictive policy blocks non-admins\n-- Drop the restrictive policy and recreate as PERMISSIVE\nDROP POLICY IF EXISTS \"Anyone authenticated can read weekly_file_limit\" ON public.system_settings;\n\nCREATE POLICY \"Anyone authenticated can read weekly_file_limit\"\nON public.system_settings\nFOR SELECT\nTO authenticated\nUSING (key = 'weekly_file_limit');\n\n-- Update has_autonomy_level to include 'diretoria' at supervisor level\nCREATE OR REPLACE FUNCTION public.has_autonomy_level(required_level text)\nRETURNS boolean\nLANGUAGE sql\nSTABLE SECURITY DEFINER\nSET search_path TO 'public'\nAS $$\n  SELECT CASE\n    WHEN required_level = 'colaborador' THEN true\n    WHEN required_level = 'supervisor' THEN \n      public.get_current_autonomy_level() IN ('admin', 'gerente', 'supervisor', 'diretoria')\n    WHEN required_level = 'gerente' THEN \n      public.get_current_autonomy_level() IN ('admin', 'gerente')\n    WHEN required_level = 'admin' THEN \n      public.get_current_autonomy_level() = 'admin'\n    ELSE false\n  END;\n$$;\n"], ["20260219014142_b5ba8e59-3a03-4e09-b5d4-8712b66c70da.sql", "\n-- Fix RLS for system_settings: non-admins need to read weekly_file_limit\n-- The problem: ALL 3 existing policies are RESTRICTIVE, so ALL must pass.\n-- The RESTRICTIVE ALL policy with is_admin() blocks non-admins from everything.\n\n-- Drop existing policies\nDROP POLICY IF EXISTS \"Anyone authenticated can read weekly_file_limit\" ON public.system_settings;\nDROP POLICY IF EXISTS \"Only admins can manage system settings\" ON public.system_settings;\nDROP POLICY IF EXISTS \"Only admins can view system settings\" ON public.system_settings;\n\n-- Create PERMISSIVE policies (default behavior: any passing policy grants access)\nCREATE POLICY \"Admins can manage system settings\"\nON public.system_settings\nFOR ALL\nTO authenticated\nUSING (is_admin())\nWITH CHECK (is_admin());\n\nCREATE POLICY \"Authenticated users can read weekly_file_limit\"\nON public.system_settings\nFOR SELECT\nTO authenticated\nUSING (key = 'weekly_file_limit');\n"], ["20260220011259_6e00ded4-9b0a-4ced-ac8d-7127b3b89bb9.sql", "\n-- Table to store card auto-duplication schedules\nCREATE TABLE public.task_auto_duplications (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  task_id UUID NOT NULL REFERENCES public.tasks(id) ON DELETE CASCADE,\n  board_id UUID NOT NULL REFERENCES public.task_boards(id) ON DELETE CASCADE,\n  target_column_id UUID NOT NULL,\n  frequency TEXT NOT NULL CHECK (frequency IN ('daily', 'weekly', 'monthly')),\n  last_duplicated_at TIMESTAMP WITH TIME ZONE,\n  is_active BOOLEAN NOT NULL DEFAULT true,\n  created_by UUID NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.task_auto_duplications ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Board members can view duplications\"\n  ON public.task_auto_duplications FOR SELECT\n  USING (is_board_member(board_id));\n\nCREATE POLICY \"Board members can create duplications\"\n  ON public.task_auto_duplications FOR INSERT\n  WITH CHECK (is_board_member(board_id));\n\nCREATE POLICY \"Board members can update duplications\"\n  ON public.task_auto_duplications FOR UPDATE\n  USING (is_board_member(board_id));\n\nCREATE POLICY \"Board members can delete duplications\"\n  ON public.task_auto_duplications FOR DELETE\n  USING (is_board_member(board_id));\n"], ["20260221012141_5add2e6b-f9e0-4906-81de-b470af66ae06.sql", "-- Add is_archived column to tasks\nALTER TABLE public.tasks ADD COLUMN IF NOT EXISTS is_archived boolean NOT NULL DEFAULT false;\n\n-- Index for quick filtering\nCREATE INDEX IF NOT EXISTS idx_tasks_is_archived ON public.tasks(is_archived) WHERE is_archived = true;\n"], ["20260222005037_e9e6a22b-6f32-49c7-8e10-3085e8c2622e.sql", "\n-- Table for task automation rules (SE \u2192 ENT\u00c3O engine)\nCREATE TABLE public.task_automation_rules (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  board_id UUID NOT NULL REFERENCES public.task_boards(id) ON DELETE CASCADE,\n  task_id UUID REFERENCES public.tasks(id) ON DELETE CASCADE,\n  trigger_type TEXT NOT NULL, -- 'deadline_approaching', 'stuck_days', 'checklist_complete', 'label_urgent'\n  trigger_config JSONB NOT NULL DEFAULT '{}'::jsonb, -- e.g. {\"hours\": 24}, {\"days\": 3}\n  action_type TEXT NOT NULL, -- 'notify', 'move_column', 'set_priority', 'alert'\n  action_config JSONB NOT NULL DEFAULT '{}'::jsonb, -- e.g. {\"column_id\": \"...\"}, {\"priority\": \"high\"}\n  is_active BOOLEAN NOT NULL DEFAULT true,\n  created_by UUID NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.task_automation_rules ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Board members can view automation rules\"\n  ON public.task_automation_rules FOR SELECT\n  USING (is_board_member(board_id));\n\nCREATE POLICY \"Board members can create automation rules\"\n  ON public.task_automation_rules FOR INSERT\n  WITH CHECK (is_board_member(board_id));\n\nCREATE POLICY \"Board members can update automation rules\"\n  ON public.task_automation_rules FOR UPDATE\n  USING (is_board_member(board_id));\n\nCREATE POLICY \"Board members can delete automation rules\"\n  ON public.task_automation_rules FOR DELETE\n  USING (is_board_member(board_id));\n\n-- Table for workload alerts that surface in People Management\nCREATE TABLE public.workload_alerts (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  profile_id UUID NOT NULL,\n  board_id UUID REFERENCES public.task_boards(id) ON DELETE CASCADE,\n  alert_type TEXT NOT NULL, -- 'overloaded', 'deadline_risk', 'stuck_task', 'late_task'\n  message TEXT NOT NULL,\n  task_id UUID REFERENCES public.tasks(id) ON DELETE CASCADE,\n  is_read BOOLEAN NOT NULL DEFAULT false,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.workload_alerts ENABLE ROW LEVEL SECURITY;\n\n-- Alerts visible to the supervisor linked to that person, or admin\nCREATE POLICY \"Supervisors can view alerts for their team\"\n  ON public.workload_alerts FOR SELECT\n  USING (\n    is_admin() OR\n    EXISTS (\n      SELECT 1 FROM supervisor_team_members stm\n      WHERE stm.supervisor_id = auth.uid()\n        AND stm.member_profile_id = workload_alerts.profile_id\n    )\n  );\n\nCREATE POLICY \"System can insert workload alerts\"\n  ON public.workload_alerts FOR INSERT\n  WITH CHECK (true);\n\nCREATE POLICY \"Supervisors can update alerts\"\n  ON public.workload_alerts FOR UPDATE\n  USING (\n    is_admin() OR\n    EXISTS (\n      SELECT 1 FROM supervisor_team_members stm\n      WHERE stm.supervisor_id = auth.uid()\n        AND stm.member_profile_id = workload_alerts.profile_id\n    )\n  );\n\nCREATE POLICY \"Supervisors can delete alerts\"\n  ON public.workload_alerts FOR DELETE\n  USING (\n    is_admin() OR\n    EXISTS (\n      SELECT 1 FROM supervisor_team_members stm\n      WHERE stm.supervisor_id = auth.uid()\n        AND stm.member_profile_id = workload_alerts.profile_id\n    )\n  );\n\n-- Enable realtime for workload_alerts\nALTER PUBLICATION supabase_realtime ADD TABLE public.workload_alerts;\n"], ["20260224014515_d3bd1efe-1eee-47d6-b57f-ff323efbcf92.sql", "-- Create calendar events table for admin\nCREATE TABLE public.calendar_events (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  title TEXT NOT NULL,\n  description TEXT,\n  event_type TEXT NOT NULL DEFAULT 'meeting',\n  start_date TIMESTAMP WITH TIME ZONE NOT NULL,\n  end_date TIMESTAMP WITH TIME ZONE,\n  all_day BOOLEAN NOT NULL DEFAULT false,\n  color TEXT NOT NULL DEFAULT '#3B82F6',\n  reminder_minutes INTEGER,\n  task_id UUID REFERENCES public.tasks(id) ON DELETE SET NULL,\n  created_by UUID NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.calendar_events ENABLE ROW LEVEL SECURITY;\n\n-- Only admin can manage calendar events\nCREATE POLICY \"Admin can manage calendar events\"\nON public.calendar_events\nFOR ALL\nUSING (is_admin())\nWITH CHECK (is_admin());\n\n-- Enable realtime\nALTER PUBLICATION supabase_realtime ADD TABLE public.calendar_events;\n"], ["20260225012517_4f66c6e2-99f0-42ff-8c43-9f24395ea9a6.sql", "\n-- Update calendar_events RLS: allow all authenticated users\nDROP POLICY IF EXISTS \"Admin can manage calendar events\" ON public.calendar_events;\n\nCREATE POLICY \"Authenticated users can view calendar events\"\nON public.calendar_events FOR SELECT\nUSING (auth.uid() IS NOT NULL);\n\nCREATE POLICY \"Authenticated users can create calendar events\"\nON public.calendar_events FOR INSERT\nWITH CHECK (auth.uid() IS NOT NULL AND created_by = auth.uid());\n\nCREATE POLICY \"Users can update their own events\"\nON public.calendar_events FOR UPDATE\nUSING (created_by = auth.uid() OR is_admin());\n\nCREATE POLICY \"Users can delete their own events\"\nON public.calendar_events FOR DELETE\nUSING (created_by = auth.uid() OR is_admin());\n\n-- Create meeting participants table\nCREATE TABLE public.meeting_participants (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  event_id UUID NOT NULL REFERENCES public.calendar_events(id) ON DELETE CASCADE,\n  profile_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,\n  status TEXT NOT NULL DEFAULT 'pending',\n  responded_at TIMESTAMP WITH TIME ZONE,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  UNIQUE(event_id, profile_id)\n);\n\nALTER TABLE public.meeting_participants ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Users can view meeting participants\"\nON public.meeting_participants FOR SELECT\nUSING (auth.uid() IS NOT NULL);\n\nCREATE POLICY \"Event creators can manage participants\"\nON public.meeting_participants FOR INSERT\nWITH CHECK (EXISTS (\n  SELECT 1 FROM public.calendar_events ce\n  WHERE ce.id = event_id AND (ce.created_by = auth.uid() OR is_admin())\n));\n\nCREATE POLICY \"Event creators can update participants\"\nON public.meeting_participants FOR UPDATE\nUSING (\n  EXISTS (SELECT 1 FROM public.calendar_events ce WHERE ce.id = event_id AND ce.created_by = auth.uid())\n  OR profile_id = (SELECT id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1)\n  OR is_admin()\n);\n\nCREATE POLICY \"Event creators can delete participants\"\nON public.meeting_participants FOR DELETE\nUSING (EXISTS (\n  SELECT 1 FROM public.calendar_events ce\n  WHERE ce.id = event_id AND (ce.created_by = auth.uid() OR is_admin())\n));\n\n-- Add meeting_link column to calendar_events\nALTER TABLE public.calendar_events ADD COLUMN IF NOT EXISTS meeting_link TEXT;\n\n-- Add overload_threshold to task_boards \nALTER TABLE public.task_boards ADD COLUMN IF NOT EXISTS overload_threshold INTEGER NOT NULL DEFAULT 5;\n"], ["20260301212726_e959dc56-352e-4070-aa33-51591ddc8cb8.sql", "\n-- Add weekdays and month_day columns to task_auto_duplications\nALTER TABLE public.task_auto_duplications \nADD COLUMN weekdays integer[] DEFAULT NULL,\nADD COLUMN month_day integer DEFAULT NULL;\n"], ["20260302025712_17620836-95d2-4ce8-96e9-fdfaf8b92c6c.sql", "\n-- Create task_assignees junction table for multiple assignees per task\nCREATE TABLE public.task_assignees (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  task_id UUID NOT NULL REFERENCES public.tasks(id) ON DELETE CASCADE,\n  profile_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  UNIQUE(task_id, profile_id)\n);\n\n-- Enable RLS\nALTER TABLE public.task_assignees ENABLE ROW LEVEL SECURITY;\n\n-- Policies: same access as tasks (board members)\nCREATE POLICY \"Board members can view task assignees\"\n  ON public.task_assignees FOR SELECT\n  USING (EXISTS (\n    SELECT 1 FROM tasks t WHERE t.id = task_assignees.task_id AND t.board_id IS NOT NULL AND is_board_member(t.board_id)\n  ));\n\nCREATE POLICY \"Board members can manage task assignees\"\n  ON public.task_assignees FOR INSERT\n  WITH CHECK (EXISTS (\n    SELECT 1 FROM tasks t WHERE t.id = task_assignees.task_id AND t.board_id IS NOT NULL AND is_board_member(t.board_id)\n  ));\n\nCREATE POLICY \"Board members can delete task assignees\"\n  ON public.task_assignees FOR DELETE\n  USING (EXISTS (\n    SELECT 1 FROM tasks t WHERE t.id = task_assignees.task_id AND t.board_id IS NOT NULL AND is_board_member(t.board_id)\n  ));\n\n-- Enable realtime\nALTER PUBLICATION supabase_realtime ADD TABLE public.task_assignees;\n\n-- Enable pg_cron and pg_net extensions for scheduled feedback\nCREATE EXTENSION IF NOT EXISTS pg_cron WITH SCHEMA pg_catalog;\nCREATE EXTENSION IF NOT EXISTS pg_net WITH SCHEMA extensions;\n"], ["20260304013532_dd5b6555-f779-45dc-a1d7-5b74e8589a2c.sql", "-- Allow any authenticated user to insert notifications (for @mentions)\nCREATE POLICY \"Authenticated users can create mention notifications\"\nON public.user_notifications\nFOR INSERT\nTO authenticated\nWITH CHECK (true);"], ["20260305015451_cec4afac-9eb1-4ddc-8ff5-43d891cd86bf.sql", "-- Allow board owners and admins to update member roles\nCREATE POLICY \"Board owners and admins can update members\"\nON public.task_board_members\nFOR UPDATE\nUSING (\n  is_board_owner(board_id) OR \n  EXISTS (\n    SELECT 1 FROM task_board_members tbm \n    WHERE tbm.board_id = task_board_members.board_id \n    AND tbm.user_id = auth.uid() \n    AND tbm.role = 'admin'\n  )\n);"], ["20260306022124_4d1764de-0ba6-4a8f-a725-1ef686086e61.sql", "\n-- Subtask groups table\nCREATE TABLE public.subtask_groups (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  task_id UUID REFERENCES public.tasks(id) ON DELETE CASCADE NOT NULL,\n  title TEXT NOT NULL,\n  position INTEGER NOT NULL DEFAULT 0,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Add group_id to task_subtasks\nALTER TABLE public.task_subtasks ADD COLUMN group_id UUID REFERENCES public.subtask_groups(id) ON DELETE CASCADE;\n\n-- Auto-subtasks for columns (template subtasks that get created for cards in the column)\nCREATE TABLE public.column_auto_subtasks (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  column_id UUID REFERENCES public.task_board_columns(id) ON DELETE CASCADE NOT NULL,\n  group_title TEXT NOT NULL DEFAULT 'Geral',\n  title TEXT NOT NULL,\n  position INTEGER NOT NULL DEFAULT 0,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- RLS for subtask_groups\nALTER TABLE public.subtask_groups ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Board members can view subtask groups\"\nON public.subtask_groups FOR SELECT\nUSING (EXISTS (\n  SELECT 1 FROM tasks t WHERE t.id = subtask_groups.task_id AND is_board_member(t.board_id)\n));\n\nCREATE POLICY \"Board members can insert subtask groups\"\nON public.subtask_groups FOR INSERT\nWITH CHECK (EXISTS (\n  SELECT 1 FROM tasks t WHERE t.id = subtask_groups.task_id AND is_board_member(t.board_id)\n));\n\nCREATE POLICY \"Board members can update subtask groups\"\nON public.subtask_groups FOR UPDATE\nUSING (EXISTS (\n  SELECT 1 FROM tasks t WHERE t.id = subtask_groups.task_id AND is_board_member(t.board_id)\n));\n\nCREATE POLICY \"Board members can delete subtask groups\"\nON public.subtask_groups FOR DELETE\nUSING (EXISTS (\n  SELECT 1 FROM tasks t WHERE t.id = subtask_groups.task_id AND is_board_member(t.board_id)\n));\n\n-- RLS for column_auto_subtasks\nALTER TABLE public.column_auto_subtasks ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Board members can view column auto subtasks\"\nON public.column_auto_subtasks FOR SELECT\nUSING (EXISTS (\n  SELECT 1 FROM task_board_columns c WHERE c.id = column_auto_subtasks.column_id AND is_board_member(c.board_id)\n));\n\nCREATE POLICY \"Board members can insert column auto subtasks\"\nON public.column_auto_subtasks FOR INSERT\nWITH CHECK (EXISTS (\n  SELECT 1 FROM task_board_columns c WHERE c.id = column_auto_subtasks.column_id AND is_board_member(c.board_id)\n));\n\nCREATE POLICY \"Board members can update column auto subtasks\"\nON public.column_auto_subtasks FOR UPDATE\nUSING (EXISTS (\n  SELECT 1 FROM task_board_columns c WHERE c.id = column_auto_subtasks.column_id AND is_board_member(c.board_id)\n));\n\nCREATE POLICY \"Board members can delete column auto subtasks\"\nON public.column_auto_subtasks FOR DELETE\nUSING (EXISTS (\n  SELECT 1 FROM task_board_columns c WHERE c.id = column_auto_subtasks.column_id AND is_board_member(c.board_id)\n));\n\n-- Workflow rules table (column movement restrictions)\nCREATE TABLE public.column_workflow_rules (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  board_id UUID REFERENCES public.task_boards(id) ON DELETE CASCADE NOT NULL,\n  source_column_id UUID REFERENCES public.task_board_columns(id) ON DELETE CASCADE,\n  target_column_id UUID REFERENCES public.task_board_columns(id) ON DELETE CASCADE NOT NULL,\n  rule_type TEXT NOT NULL DEFAULT 'block_direct',\n  required_column_id UUID REFERENCES public.task_board_columns(id) ON DELETE CASCADE,\n  is_active BOOLEAN NOT NULL DEFAULT true,\n  created_by UUID NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.column_workflow_rules ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Board members can view workflow rules\"\nON public.column_workflow_rules FOR SELECT\nUSING (is_board_member(board_id));\n\nCREATE POLICY \"Board members can insert workflow rules\"\nON public.column_workflow_rules FOR INSERT\nWITH CHECK (is_board_member(board_id));\n\nCREATE POLICY \"Board members can update workflow rules\"\nON public.column_workflow_rules FOR UPDATE\nUSING (is_board_member(board_id));\n\nCREATE POLICY \"Board members can delete workflow rules\"\nON public.column_workflow_rules FOR DELETE\nUSING (is_board_member(board_id));\n\n-- Update is_board_member to also consider admin role\nCREATE OR REPLACE FUNCTION public.is_board_admin_or_owner(check_board_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE SECURITY DEFINER\nSET search_path TO 'public'\nAS $$\n  SELECT EXISTS (\n    SELECT 1 FROM task_boards WHERE id = check_board_id AND owner_id = auth.uid()\n  ) OR EXISTS (\n    SELECT 1 FROM task_board_members WHERE board_id = check_board_id AND user_id = auth.uid() AND role = 'admin'\n  );\n$$;\n\n-- Allow admins to update boards too\nCREATE POLICY \"Board admins can update boards\"\nON public.task_boards FOR UPDATE\nUSING (is_board_admin_or_owner(id));\n"], ["20260308030152_e4875a04-426f-475d-82f6-02ddfe267a0c.sql", "\nALTER TABLE public.tasks ADD COLUMN IF NOT EXISTS reminder_minutes integer DEFAULT NULL;\n\nCREATE TABLE IF NOT EXISTS public.task_activities (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  task_id uuid REFERENCES public.tasks(id) ON DELETE CASCADE NOT NULL,\n  user_id uuid NOT NULL,\n  user_name text NOT NULL DEFAULT '',\n  action_type text NOT NULL,\n  description text NOT NULL,\n  metadata jsonb DEFAULT '{}',\n  created_at timestamptz DEFAULT now() NOT NULL\n);\n\nALTER TABLE public.task_activities ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Board members can view task activities\"\nON public.task_activities FOR SELECT TO authenticated\nUSING (EXISTS (\n  SELECT 1 FROM public.tasks t\n  JOIN public.task_board_members bm ON bm.board_id = t.board_id\n  WHERE t.id = task_activities.task_id AND bm.user_id = auth.uid()\n));\n\nCREATE POLICY \"Authenticated can insert task activities\"\nON public.task_activities FOR INSERT TO authenticated\nWITH CHECK (true);\n"], ["20260308170052_d694be6a-232a-4462-aad0-714135a09acc.sql", "\n-- Board share links table\nCREATE TABLE IF NOT EXISTS public.board_share_links (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  board_id uuid REFERENCES public.task_boards(id) ON DELETE CASCADE NOT NULL,\n  share_token text NOT NULL UNIQUE DEFAULT encode(gen_random_bytes(16), 'hex'),\n  created_by uuid NOT NULL,\n  is_active boolean DEFAULT true,\n  created_at timestamptz DEFAULT now() NOT NULL\n);\n\nALTER TABLE public.board_share_links ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Board members can view share links\"\nON public.board_share_links FOR SELECT TO authenticated\nUSING (public.is_board_member(board_id));\n\nCREATE POLICY \"Board admin/owner can manage share links\"\nON public.board_share_links FOR ALL TO authenticated\nUSING (public.is_board_admin_or_owner(board_id));\n\n-- Board join requests table\nCREATE TABLE IF NOT EXISTS public.board_join_requests (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  board_id uuid REFERENCES public.task_boards(id) ON DELETE CASCADE NOT NULL,\n  user_id uuid NOT NULL,\n  profile_id uuid REFERENCES public.profiles(id) NOT NULL,\n  status text DEFAULT 'pending' NOT NULL,\n  created_at timestamptz DEFAULT now() NOT NULL,\n  resolved_at timestamptz,\n  resolved_by uuid,\n  UNIQUE(board_id, user_id, status)\n);\n\nALTER TABLE public.board_join_requests ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Users can view own join requests\"\nON public.board_join_requests FOR SELECT TO authenticated\nUSING (user_id = auth.uid() OR public.is_board_admin_or_owner(board_id));\n\nCREATE POLICY \"Users can insert join requests\"\nON public.board_join_requests FOR INSERT TO authenticated\nWITH CHECK (user_id = auth.uid());\n\nCREATE POLICY \"Board admin/owner can update join requests\"\nON public.board_join_requests FOR UPDATE TO authenticated\nUSING (public.is_board_admin_or_owner(board_id));\n\n-- Allow anyone authenticated to look up share links by token\nCREATE POLICY \"Anyone can look up active share links by token\"\nON public.board_share_links FOR SELECT TO authenticated\nUSING (is_active = true);\n"], ["20260308182759_fffc156a-3fa4-43c4-8d30-7e312becee79.sql", "ALTER TABLE public.tasks ADD COLUMN is_template boolean NOT NULL DEFAULT false;"], ["20260308201647_8762955f-5785-43c3-b3cb-59c18990fbfc.sql", "ALTER TABLE public.task_board_columns ADD COLUMN is_template_column boolean NOT NULL DEFAULT false;"], ["20260308213213_9329e288-ee31-4882-9ffe-3d55e3d2d3a2.sql", "\n-- Drop existing restrictive policies on board_share_links\nDROP POLICY IF EXISTS \"Anyone can look up active share links by token\" ON public.board_share_links;\nDROP POLICY IF EXISTS \"Board admin/owner can manage share links\" ON public.board_share_links;\nDROP POLICY IF EXISTS \"Board members can view share links\" ON public.board_share_links;\n\n-- Recreate as PERMISSIVE policies (default)\nCREATE POLICY \"Anyone can look up active share links by token\"\nON public.board_share_links\nFOR SELECT\nTO authenticated\nUSING (is_active = true);\n\nCREATE POLICY \"Board admin/owner can manage share links\"\nON public.board_share_links\nFOR ALL\nTO authenticated\nUSING (is_board_admin_or_owner(board_id));\n\nCREATE POLICY \"Board members can view share links\"\nON public.board_share_links\nFOR SELECT\nTO authenticated\nUSING (is_board_member(board_id));\n"], ["20260308215140_2031cc4d-0e54-4daa-9dd5-1fdd346e6d2a.sql", "ALTER TABLE public.tasks ADD COLUMN is_emergency boolean NOT NULL DEFAULT false;"], ["20260308221314_daed3baf-5093-4865-9516-9fe469f891cf.sql", "\n-- Monthly score snapshots for tracking performance history\nCREATE TABLE public.monthly_scores (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  profile_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,\n  board_id uuid REFERENCES public.task_boards(id) ON DELETE CASCADE,\n  year_month text NOT NULL, -- format: '2026-03'\n  score integer NOT NULL DEFAULT 0,\n  total_tasks integer NOT NULL DEFAULT 0,\n  completed_tasks integer NOT NULL DEFAULT 0,\n  late_tasks integer NOT NULL DEFAULT 0,\n  on_time_tasks integer NOT NULL DEFAULT 0,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\n  UNIQUE(profile_id, board_id, year_month)\n);\n\n-- Also allow null board_id for global scores\nCREATE UNIQUE INDEX monthly_scores_global_unique ON public.monthly_scores (profile_id, year_month) WHERE board_id IS NULL;\n\nALTER TABLE public.monthly_scores ENABLE ROW LEVEL SECURITY;\n\n-- Board members can view scores for their boards\nCREATE POLICY \"Board members can view board scores\"\nON public.monthly_scores FOR SELECT\nUSING (\n  (board_id IS NOT NULL AND is_board_member(board_id))\n  OR (board_id IS NULL AND (\n    is_admin() OR profile_id = get_current_profile_id()\n    OR EXISTS (\n      SELECT 1 FROM supervisor_team_members stm \n      WHERE stm.supervisor_id = auth.uid() AND stm.member_profile_id = monthly_scores.profile_id\n    )\n  ))\n);\n\n-- System can insert/update scores\nCREATE POLICY \"Authenticated can insert scores\"\nON public.monthly_scores FOR INSERT\nWITH CHECK (true);\n\nCREATE POLICY \"Authenticated can update scores\"\nON public.monthly_scores FOR UPDATE\nUSING (true);\n\n-- Enable realtime\nALTER PUBLICATION supabase_realtime ADD TABLE public.monthly_scores;\n"], ["20260308225939_fa12085c-59ec-47f9-a319-eff84a663d17.sql", "\nCREATE TABLE public.task_decisions (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  task_id UUID NOT NULL REFERENCES public.tasks(id) ON DELETE CASCADE,\n  decision_text TEXT NOT NULL,\n  responsible_name TEXT NOT NULL,\n  decision_date DATE NOT NULL,\n  created_by UUID NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.task_decisions ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Board members can view task decisions\"\n  ON public.task_decisions FOR SELECT\n  USING (EXISTS (\n    SELECT 1 FROM tasks t WHERE t.id = task_decisions.task_id AND t.board_id IS NOT NULL AND is_board_member(t.board_id)\n  ));\n\nCREATE POLICY \"Board members can insert task decisions\"\n  ON public.task_decisions FOR INSERT\n  WITH CHECK (EXISTS (\n    SELECT 1 FROM tasks t WHERE t.id = task_decisions.task_id AND t.board_id IS NOT NULL AND is_board_member(t.board_id)\n  ));\n\nCREATE POLICY \"Board members can delete task decisions\"\n  ON public.task_decisions FOR DELETE\n  USING (EXISTS (\n    SELECT 1 FROM tasks t WHERE t.id = task_decisions.task_id AND t.board_id IS NOT NULL AND is_board_member(t.board_id)\n  ));\n"], ["20260308232500_89b36bbf-d634-4f26-9ba7-d0167441c2b5.sql", "\n-- War Rooms table\nCREATE TABLE public.war_rooms (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  title TEXT NOT NULL,\n  description TEXT,\n  status TEXT NOT NULL DEFAULT 'active',\n  created_by UUID NOT NULL,\n  task_id UUID REFERENCES public.tasks(id) ON DELETE SET NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  closed_at TIMESTAMP WITH TIME ZONE,\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- War Room members\nCREATE TABLE public.war_room_members (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  war_room_id UUID NOT NULL REFERENCES public.war_rooms(id) ON DELETE CASCADE,\n  profile_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL,\n  has_acknowledged BOOLEAN NOT NULL DEFAULT false,\n  acknowledged_at TIMESTAMP WITH TIME ZONE,\n  joined_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  UNIQUE(war_room_id, profile_id)\n);\n\n-- War Room timeline incidents\nCREATE TABLE public.war_room_timeline (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  war_room_id UUID NOT NULL REFERENCES public.war_rooms(id) ON DELETE CASCADE,\n  content TEXT NOT NULL,\n  created_by UUID NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- War Room messages (chat)\nCREATE TABLE public.war_room_messages (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  war_room_id UUID NOT NULL REFERENCES public.war_rooms(id) ON DELETE CASCADE,\n  sender_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,\n  content TEXT NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\n-- Enable RLS\nALTER TABLE public.war_rooms ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.war_room_members ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.war_room_timeline ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.war_room_messages ENABLE ROW LEVEL SECURITY;\n\n-- War Rooms policies: all authenticated can view, only permitted can create\nCREATE POLICY \"All authenticated can view war rooms\" ON public.war_rooms FOR SELECT USING (auth.uid() IS NOT NULL);\nCREATE POLICY \"Permitted users can create war rooms\" ON public.war_rooms FOR INSERT WITH CHECK (\n  is_admin() OR has_autonomy_level('supervisor') OR (EXISTS (SELECT 1 FROM public.user_permissions WHERE user_id = auth.uid() AND can_access_management = true))\n);\nCREATE POLICY \"Creators and admins can update war rooms\" ON public.war_rooms FOR UPDATE USING (created_by = auth.uid() OR is_admin());\nCREATE POLICY \"Admins can delete war rooms\" ON public.war_rooms FOR DELETE USING (is_admin());\n\n-- War Room members policies\nCREATE POLICY \"All authenticated can view war room members\" ON public.war_room_members FOR SELECT USING (auth.uid() IS NOT NULL);\nCREATE POLICY \"Permitted users can manage members\" ON public.war_room_members FOR INSERT WITH CHECK (\n  is_admin() OR has_autonomy_level('supervisor') OR (EXISTS (SELECT 1 FROM public.user_permissions WHERE user_id = auth.uid() AND can_access_management = true))\n);\nCREATE POLICY \"Members can acknowledge\" ON public.war_room_members FOR UPDATE USING (user_id = auth.uid());\nCREATE POLICY \"Permitted users can remove members\" ON public.war_room_members FOR DELETE USING (\n  is_admin() OR has_autonomy_level('supervisor') OR (EXISTS (SELECT 1 FROM public.user_permissions WHERE user_id = auth.uid() AND can_access_management = true))\n);\n\n-- Timeline policies: all can view, members can add\nCREATE POLICY \"All authenticated can view timeline\" ON public.war_room_timeline FOR SELECT USING (auth.uid() IS NOT NULL);\nCREATE POLICY \"Members can add timeline entries\" ON public.war_room_timeline FOR INSERT WITH CHECK (\n  EXISTS (SELECT 1 FROM public.war_room_members WHERE war_room_id = war_room_timeline.war_room_id AND user_id = auth.uid())\n  OR is_admin() OR has_autonomy_level('supervisor')\n);\nCREATE POLICY \"Admins can delete timeline\" ON public.war_room_timeline FOR DELETE USING (is_admin() OR created_by = auth.uid());\n\n-- Messages policies: members can chat\nCREATE POLICY \"Members can view war room messages\" ON public.war_room_messages FOR SELECT USING (\n  EXISTS (SELECT 1 FROM public.war_room_members WHERE war_room_id = war_room_messages.war_room_id AND user_id = auth.uid())\n  OR is_admin()\n);\nCREATE POLICY \"Members can send war room messages\" ON public.war_room_messages FOR INSERT WITH CHECK (\n  (EXISTS (SELECT 1 FROM public.war_room_members WHERE war_room_id = war_room_messages.war_room_id AND user_id = auth.uid())\n  OR is_admin())\n  AND sender_id = get_current_profile_id()\n);\n\n-- Enable realtime for war room messages\nALTER PUBLICATION supabase_realtime ADD TABLE public.war_room_messages;\nALTER PUBLICATION supabase_realtime ADD TABLE public.war_room_members;\n\n-- Trigger for updated_at\nCREATE TRIGGER update_war_rooms_updated_at BEFORE UPDATE ON public.war_rooms FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\n"], ["20260308233010_4972fc9d-2832-4db7-bfcd-de52eb4ad7d6.sql", "\nALTER TABLE public.user_permissions ADD COLUMN can_create_war_room BOOLEAN NOT NULL DEFAULT false;\n"], ["20260308233219_2058f508-57b5-4514-a6b5-2d6b7c34f2a8.sql", "\n-- Update the insert policy to include can_create_war_room permission\nDROP POLICY \"Permitted users can create war rooms\" ON public.war_rooms;\nCREATE POLICY \"Permitted users can create war rooms\" ON public.war_rooms FOR INSERT WITH CHECK (\n  is_admin() OR has_autonomy_level('supervisor') OR (EXISTS (SELECT 1 FROM public.user_permissions WHERE user_id = auth.uid() AND (can_access_management = true OR can_create_war_room = true)))\n);\n\n-- Update members insert policy too\nDROP POLICY \"Permitted users can manage members\" ON public.war_room_members;\nCREATE POLICY \"Permitted users can manage members\" ON public.war_room_members FOR INSERT WITH CHECK (\n  is_admin() OR has_autonomy_level('supervisor') OR (EXISTS (SELECT 1 FROM public.user_permissions WHERE user_id = auth.uid() AND (can_access_management = true OR can_create_war_room = true)))\n);\n\nDROP POLICY \"Permitted users can remove members\" ON public.war_room_members;\nCREATE POLICY \"Permitted users can remove members\" ON public.war_room_members FOR DELETE USING (\n  is_admin() OR has_autonomy_level('supervisor') OR (EXISTS (SELECT 1 FROM public.user_permissions WHERE user_id = auth.uid() AND (can_access_management = true OR can_create_war_room = true)))\n);\n"], ["20260308234523_64d4ce04-fb82-4a56-a661-66a0b1d1f212.sql", "DROP POLICY IF EXISTS \"Members can add timeline entries\" ON public.war_room_timeline;\n\nCREATE POLICY \"Only room creator can add timeline entries\"\nON public.war_room_timeline\nFOR INSERT\nWITH CHECK (\n  is_admin()\n  OR EXISTS (\n    SELECT 1\n    FROM public.war_rooms wr\n    WHERE wr.id = war_room_timeline.war_room_id\n      AND wr.created_by = auth.uid()\n  )\n);"], ["20260308234834_468fd13c-a6aa-470b-a6de-afcbf65528c0.sql", "DROP POLICY IF EXISTS \"Only room creator can add timeline entries\" ON public.war_room_timeline;\n\nCREATE POLICY \"Only room creator can add timeline entries\"\nON public.war_room_timeline\nFOR INSERT\nWITH CHECK (\n  EXISTS (\n    SELECT 1\n    FROM public.war_rooms wr\n    WHERE wr.id = war_room_timeline.war_room_id\n      AND wr.created_by = auth.uid()\n  )\n);"], ["20260309000635_64a3fa2f-ed25-49fb-879a-002be1413c39.sql", "\n-- Add reply_to support for messages\nALTER TABLE public.messages \nADD COLUMN IF NOT EXISTS reply_to_id uuid REFERENCES public.messages(id) ON DELETE SET NULL;\n\n-- Create message reactions table\nCREATE TABLE IF NOT EXISTS public.message_reactions (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  message_id uuid NOT NULL REFERENCES public.messages(id) ON DELETE CASCADE,\n  profile_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,\n  emoji text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(message_id, profile_id, emoji)\n);\n\nALTER TABLE public.message_reactions ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Authenticated can view reactions\" ON public.message_reactions FOR SELECT \nUSING (auth.uid() IS NOT NULL);\n\nCREATE POLICY \"Users can add own reactions\" ON public.message_reactions FOR INSERT \nWITH CHECK (profile_id = public.get_current_profile_id());\n\nCREATE POLICY \"Users can remove own reactions\" ON public.message_reactions FOR DELETE \nUSING (profile_id = public.get_current_profile_id());\n\nALTER PUBLICATION supabase_realtime ADD TABLE public.message_reactions;\n\n-- Add task_id to war_room_timeline for emergency card links\nALTER TABLE public.war_room_timeline \nADD COLUMN IF NOT EXISTS task_id uuid REFERENCES public.tasks(id) ON DELETE SET NULL;\n"], ["20260309005110_bd7347cf-6073-4509-8296-be7800a58190.sql", "-- Ajustes de acesso tempor\u00e1rio via War Room e bloqueio de leitura de cards de mural por setor\n\n-- 1) TASKS: impedir que a policy por setor libere cards de mural (board_id NOT NULL)\nDROP POLICY IF EXISTS \"Users can view tasks in their sectors\" ON public.tasks;\nCREATE POLICY \"Users can view tasks in their sectors\"\nON public.tasks\nFOR SELECT\nTO authenticated\nUSING (\n  is_admin()\n  OR (\n    board_id IS NULL\n    AND (\n      sector_id IS NULL\n      OR sector_id = get_current_sector_id()\n      OR sector_id = '00000000-0000-0000-0000-000000000001'::uuid\n      OR EXISTS (\n        SELECT 1\n        FROM public.user_additional_sectors uas\n        WHERE uas.user_id = auth.uid()\n          AND uas.sector_id = public.tasks.sector_id\n      )\n    )\n  )\n);\n\n-- 2) TASK_BOARDS: permitir SELECT para membros do War Room (somente boards que tenham o card vinculado)\nDROP POLICY IF EXISTS \"Board members and owners can view boards\" ON public.task_boards;\nCREATE POLICY \"Board members and owners can view boards\"\nON public.task_boards\nFOR SELECT\nTO authenticated\nUSING (\n  is_board_member(id)\n  OR owner_id = auth.uid()\n  OR EXISTS (\n    SELECT 1\n    FROM public.war_rooms wr\n    JOIN public.war_room_members wrm ON wrm.war_room_id = wr.id\n    JOIN public.tasks t ON t.id = wr.task_id\n    WHERE wrm.user_id = auth.uid()\n      AND t.board_id = public.task_boards.id\n      AND (\n        wr.status = 'active'\n        OR (\n          wr.closed_at IS NOT NULL\n          AND wr.closed_at > (now() - interval '5 days')\n        )\n      )\n  )\n);\n\n-- 3) TASK_BOARD_COLUMNS: permitir SELECT para membros do War Room (para o mesmo board)\nDROP POLICY IF EXISTS \"Board members can view columns\" ON public.task_board_columns;\nCREATE POLICY \"Board members can view columns\"\nON public.task_board_columns\nFOR SELECT\nTO authenticated\nUSING (\n  is_board_member(board_id)\n  OR EXISTS (\n    SELECT 1\n    FROM public.war_rooms wr\n    JOIN public.war_room_members wrm ON wrm.war_room_id = wr.id\n    JOIN public.tasks t ON t.id = wr.task_id\n    WHERE wrm.user_id = auth.uid()\n      AND t.board_id = public.task_board_columns.board_id\n      AND (\n        wr.status = 'active'\n        OR (\n          wr.closed_at IS NOT NULL\n          AND wr.closed_at > (now() - interval '5 days')\n        )\n      )\n  )\n);\n"], ["20260309011548_6990b047-64d2-4693-9118-ef41c5ba46a8.sql", "-- Remove acesso ao mural ap\u00f3s encerramento da War Room\n-- Antes: acesso permanecia por 5 dias ap\u00f3s encerramento\n-- Agora: acesso revogado imediatamente quando status != 'active'\n\n-- Atualizar pol\u00edtica de visualiza\u00e7\u00e3o de boards\nDROP POLICY IF EXISTS \"Board members and owners can view boards\" ON public.task_boards;\nCREATE POLICY \"Board members and owners can view boards\"\nON public.task_boards FOR SELECT USING (\n  is_board_member(id) OR owner_id = auth.uid() OR EXISTS (\n    SELECT 1 FROM public.war_rooms wr\n    JOIN public.war_room_members wrm ON wrm.war_room_id = wr.id\n    JOIN public.tasks t ON t.id = wr.task_id\n    WHERE wrm.user_id = auth.uid() \n      AND t.board_id = public.task_boards.id\n      AND wr.status = 'active'\n  )\n);\n\n-- Atualizar pol\u00edtica de visualiza\u00e7\u00e3o de colunas\nDROP POLICY IF EXISTS \"Board members and war room members can view columns\" ON public.task_board_columns;\nCREATE POLICY \"Board members and war room members can view columns\"\nON public.task_board_columns FOR SELECT USING (\n  is_board_member(board_id) OR EXISTS (\n    SELECT 1 FROM public.war_rooms wr\n    JOIN public.war_room_members wrm ON wrm.war_room_id = wr.id\n    JOIN public.tasks t ON t.id = wr.task_id\n    WHERE wrm.user_id = auth.uid() \n      AND t.board_id = public.task_board_columns.board_id\n      AND wr.status = 'active'\n  )\n);\n\n-- Atualizar pol\u00edtica de visualiza\u00e7\u00e3o de tasks vinculadas\nDROP POLICY IF EXISTS \"War room members can view linked task\" ON public.tasks;\nCREATE POLICY \"War room members can view linked task\"\nON public.tasks FOR SELECT USING (\n  EXISTS (\n    SELECT 1 FROM war_rooms wr\n    JOIN war_room_members wrm ON wrm.war_room_id = wr.id\n    WHERE wr.task_id = tasks.id \n      AND wrm.user_id = auth.uid()\n      AND wr.status = 'active'\n  )\n);\n\n-- Atualizar pol\u00edtica de atualiza\u00e7\u00e3o de tasks vinculadas\nDROP POLICY IF EXISTS \"War room members can update linked task\" ON public.tasks;\nCREATE POLICY \"War room members can update linked task\"\nON public.tasks FOR UPDATE USING (\n  EXISTS (\n    SELECT 1 FROM war_rooms wr\n    JOIN war_room_members wrm ON wrm.war_room_id = wr.id\n    WHERE wr.task_id = tasks.id \n      AND wrm.user_id = auth.uid()\n      AND wr.status = 'active'\n  )\n);"], ["20260309011928_dce088fb-7879-4a0e-8eb1-b91923c8591b.sql", "-- Allow War Room members to view/update subtasks (only for the linked task while War Room is active)\n\n-- task_subtasks: SELECT\nDROP POLICY IF EXISTS \"War room members can view linked subtasks\" ON public.task_subtasks;\nCREATE POLICY \"War room members can view linked subtasks\"\nON public.task_subtasks\nFOR SELECT\nUSING (\n  EXISTS (\n    SELECT 1\n    FROM public.war_rooms wr\n    JOIN public.war_room_members wrm ON wrm.war_room_id = wr.id\n    WHERE wr.task_id = public.task_subtasks.task_id\n      AND wrm.user_id = auth.uid()\n      AND wr.status = 'active'\n  )\n);\n\n-- task_subtasks: UPDATE (toggle completion)\nDROP POLICY IF EXISTS \"War room members can update linked subtasks\" ON public.task_subtasks;\nCREATE POLICY \"War room members can update linked subtasks\"\nON public.task_subtasks\nFOR UPDATE\nUSING (\n  EXISTS (\n    SELECT 1\n    FROM public.war_rooms wr\n    JOIN public.war_room_members wrm ON wrm.war_room_id = wr.id\n    WHERE wr.task_id = public.task_subtasks.task_id\n      AND wrm.user_id = auth.uid()\n      AND wr.status = 'active'\n  )\n)\nWITH CHECK (\n  EXISTS (\n    SELECT 1\n    FROM public.war_rooms wr\n    JOIN public.war_room_members wrm ON wrm.war_room_id = wr.id\n    WHERE wr.task_id = public.task_subtasks.task_id\n      AND wrm.user_id = auth.uid()\n      AND wr.status = 'active'\n  )\n);\n\n-- subtask_groups: SELECT (so grouped checklists render correctly)\nDROP POLICY IF EXISTS \"War room members can view linked subtask groups\" ON public.subtask_groups;\nCREATE POLICY \"War room members can view linked subtask groups\"\nON public.subtask_groups\nFOR SELECT\nUSING (\n  EXISTS (\n    SELECT 1\n    FROM public.war_rooms wr\n    JOIN public.war_room_members wrm ON wrm.war_room_id = wr.id\n    WHERE wr.task_id = public.subtask_groups.task_id\n      AND wrm.user_id = auth.uid()\n      AND wr.status = 'active'\n  )\n);\n"], ["20260309013501_25af41ca-1dfd-4d6a-8d5f-e7335ef4542f.sql", "-- Update the DELETE policy for war_rooms to allow admins, supervisors, and users with can_create_war_room permission\n\nDROP POLICY IF EXISTS \"Admins can delete war rooms\" ON public.war_rooms;\n\nCREATE POLICY \"Permitted users can delete closed war rooms\"\nON public.war_rooms\nFOR DELETE\nUSING (\n  status = 'closed' AND (\n    is_admin() OR\n    has_autonomy_level('supervisor') OR\n    (EXISTS (\n      SELECT 1 FROM user_permissions\n      WHERE user_permissions.user_id = auth.uid()\n        AND (user_permissions.can_access_management = true OR user_permissions.can_create_war_room = true)\n    ))\n  )\n);\n\n-- Also allow deleting associated data when war room is deleted (cascading handled by FK, but let's ensure RLS allows it)\n\n-- war_room_members: Add DELETE policy for permitted users\nDROP POLICY IF EXISTS \"Permitted users can delete war room members\" ON public.war_room_members;\nCREATE POLICY \"Permitted users can delete war room members\"\nON public.war_room_members\nFOR DELETE\nUSING (\n  EXISTS (\n    SELECT 1 FROM war_rooms wr\n    WHERE wr.id = war_room_members.war_room_id\n      AND wr.status = 'closed'\n      AND (\n        is_admin() OR\n        has_autonomy_level('supervisor') OR\n        (EXISTS (\n          SELECT 1 FROM user_permissions\n          WHERE user_permissions.user_id = auth.uid()\n            AND (user_permissions.can_access_management = true OR user_permissions.can_create_war_room = true)\n        ))\n      )\n  )\n);\n\n-- war_room_messages: Update DELETE policy  \nDROP POLICY IF EXISTS \"War room creator can delete messages\" ON public.war_room_messages;\nCREATE POLICY \"Permitted users can delete war room messages\"\nON public.war_room_messages\nFOR DELETE\nUSING (\n  (EXISTS (\n    SELECT 1 FROM war_rooms\n    WHERE war_rooms.id = war_room_messages.war_room_id\n      AND war_rooms.created_by = auth.uid()\n  )) OR\n  is_admin() OR\n  has_autonomy_level('supervisor') OR\n  (EXISTS (\n    SELECT 1 FROM user_permissions\n    WHERE user_permissions.user_id = auth.uid()\n      AND (user_permissions.can_access_management = true OR user_permissions.can_create_war_room = true)\n  ))\n);\n\n-- war_room_timeline: Add DELETE policy\nDROP POLICY IF EXISTS \"Permitted users can delete timeline entries\" ON public.war_room_timeline;\nCREATE POLICY \"Permitted users can delete timeline entries\"\nON public.war_room_timeline\nFOR DELETE\nUSING (\n  is_admin() OR\n  has_autonomy_level('supervisor') OR\n  (EXISTS (\n    SELECT 1 FROM war_rooms\n    WHERE war_rooms.id = war_room_timeline.war_room_id\n      AND war_rooms.created_by = auth.uid()\n  )) OR\n  (EXISTS (\n    SELECT 1 FROM user_permissions\n    WHERE user_permissions.user_id = auth.uid()\n      AND (user_permissions.can_access_management = true OR user_permissions.can_create_war_room = true)\n  ))\n);"], ["20260309015916_d8f81fd9-f007-4d03-9354-bf189d39f47a.sql", "-- Drop and recreate the INSERT policy for war_room_messages with TO authenticated\nDROP POLICY IF EXISTS \"Members can send war room messages\" ON public.war_room_messages;\n\nCREATE POLICY \"Members can send war room messages\" \nON public.war_room_messages\nFOR INSERT \nTO authenticated\nWITH CHECK (\n  (\n    (\n      EXISTS (\n        SELECT 1\n        FROM war_room_members\n        WHERE war_room_members.war_room_id = war_room_messages.war_room_id\n        AND war_room_members.user_id = auth.uid()\n      )\n    ) OR is_admin()\n  ) AND (sender_id = get_current_profile_id())\n);"], ["20260309021807_39636ce7-1b0d-4d72-8d61-5e85f053fe27.sql", "-- Fix War Room chat persistence for supervisors/admins/authorized users\n-- Root cause addressed: users with permission could see the room but not SELECT/INSERT messages unless explicitly a member.\n\n-- Recreate SELECT policy\nDROP POLICY IF EXISTS \"Members can view war room messages\" ON public.war_room_messages;\nDROP POLICY IF EXISTS \"Users can view war room messages\" ON public.war_room_messages;\n\nCREATE POLICY \"Users can view war room messages\"\nON public.war_room_messages\nFOR SELECT\nTO authenticated\nUSING (\n  EXISTS (\n    SELECT 1\n    FROM public.war_room_members m\n    WHERE m.war_room_id = war_room_messages.war_room_id\n      AND m.user_id = auth.uid()\n  )\n  OR public.has_autonomy_level('supervisor')\n  OR public.is_admin()\n  OR EXISTS (\n    SELECT 1\n    FROM public.user_permissions up\n    WHERE up.user_id = auth.uid()\n      AND (up.can_access_management = true OR up.can_create_war_room = true)\n  )\n);\n\n-- Recreate INSERT policy\nDROP POLICY IF EXISTS \"Members can send war room messages\" ON public.war_room_messages;\nDROP POLICY IF EXISTS \"Users can send war room messages\" ON public.war_room_messages;\n\nCREATE POLICY \"Users can send war room messages\"\nON public.war_room_messages\nFOR INSERT\nTO authenticated\nWITH CHECK (\n  sender_id = public.get_current_profile_id()\n  AND (\n    EXISTS (\n      SELECT 1\n      FROM public.war_room_members m\n      WHERE m.war_room_id = war_room_messages.war_room_id\n        AND m.user_id = auth.uid()\n    )\n    OR public.has_autonomy_level('supervisor')\n    OR public.is_admin()\n    OR EXISTS (\n      SELECT 1\n      FROM public.user_permissions up\n      WHERE up.user_id = auth.uid()\n        AND (up.can_access_management = true OR up.can_create_war_room = true)\n    )\n  )\n);"], ["20260309032451_43f2d4c9-51f8-4615-bd15-54f563ba3ae7.sql", "\nCREATE TABLE public.scheduled_summaries (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  target_type TEXT NOT NULL CHECK (target_type IN ('group', 'sector')),\n  target_id UUID NOT NULL,\n  frequency TEXT NOT NULL CHECK (frequency IN ('daily', 'weekly', 'monthly')),\n  send_time TEXT NOT NULL DEFAULT '08:00',\n  weekday INTEGER CHECK (weekday >= 0 AND weekday <= 6),\n  month_day INTEGER CHECK (month_day >= 1 AND month_day <= 28),\n  metrics JSONB NOT NULL DEFAULT '[]'::jsonb,\n  format TEXT NOT NULL DEFAULT 'text' CHECK (format IN ('text', 'visual')),\n  is_active BOOLEAN NOT NULL DEFAULT true,\n  created_by UUID NOT NULL,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.scheduled_summaries ENABLE ROW LEVEL SECURITY;\n\n-- Only admins can manage scheduled summaries\nCREATE POLICY \"Admins can manage scheduled summaries\"\n  ON public.scheduled_summaries\n  FOR ALL\n  TO authenticated\n  USING (is_admin())\n  WITH CHECK (is_admin());\n\n-- Group admins can manage their group summaries\nCREATE POLICY \"Group admins can manage group summaries\"\n  ON public.scheduled_summaries\n  FOR ALL\n  TO authenticated\n  USING (target_type = 'group' AND is_group_admin(target_id))\n  WITH CHECK (target_type = 'group' AND is_group_admin(target_id));\n\n-- Authenticated users can view summaries for their groups/sectors\nCREATE POLICY \"Users can view relevant summaries\"\n  ON public.scheduled_summaries\n  FOR SELECT\n  TO authenticated\n  USING (\n    (target_type = 'group' AND is_group_member(target_id))\n    OR (target_type = 'sector' AND user_has_sector_access(auth.uid(), target_id))\n  );\n"], ["20260309032803_e09c40e2-d202-416f-9aba-28c481934256.sql", "CREATE EXTENSION IF NOT EXISTS pg_net WITH SCHEMA extensions;"], ["20260401101650_23cd7a79-025e-4c82-8153-243ecbc01630.sql", "\n-- Add team_name to supervisor_team_members\nALTER TABLE public.supervisor_team_members ADD COLUMN IF NOT EXISTS team_name text DEFAULT null;\n\n-- Create api_integrations table\nCREATE TABLE public.api_integrations (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name text NOT NULL,\n  api_key text NOT NULL,\n  api_token_hash text NOT NULL,\n  is_active boolean NOT NULL DEFAULT true,\n  created_by uuid NOT NULL,\n  created_at timestamp with time zone NOT NULL DEFAULT now(),\n  updated_at timestamp with time zone NOT NULL DEFAULT now(),\n  last_used_at timestamp with time zone DEFAULT null\n);\n\nALTER TABLE public.api_integrations ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Only admins and supervisors can manage api integrations\" ON public.api_integrations\n  FOR ALL TO authenticated\n  USING (is_admin() OR has_autonomy_level('supervisor'))\n  WITH CHECK (is_admin() OR has_autonomy_level('supervisor'));\n\n-- Create api_access_logs table\nCREATE TABLE public.api_access_logs (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  integration_id uuid REFERENCES public.api_integrations(id) ON DELETE CASCADE NOT NULL,\n  endpoint text NOT NULL,\n  method text NOT NULL,\n  status_code integer NOT NULL,\n  ip_address text DEFAULT null,\n  created_at timestamp with time zone NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.api_access_logs ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Only admins and supervisors can view api logs\" ON public.api_access_logs\n  FOR SELECT TO authenticated\n  USING (is_admin() OR has_autonomy_level('supervisor'));\n\nCREATE POLICY \"System can insert api logs\" ON public.api_access_logs\n  FOR INSERT TO authenticated\n  WITH CHECK (true);\n\n-- Create api_integration_history table for audit\nCREATE TABLE public.api_integration_history (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  integration_id uuid REFERENCES public.api_integrations(id) ON DELETE CASCADE NOT NULL,\n  action text NOT NULL,\n  performed_by uuid NOT NULL,\n  details text DEFAULT null,\n  created_at timestamp with time zone NOT NULL DEFAULT now()\n);\n\nALTER TABLE public.api_integration_history ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Only admins and supervisors can view history\" ON public.api_integration_history\n  FOR SELECT TO authenticated\n  USING (is_admin() OR has_autonomy_level('supervisor'));\n\nCREATE POLICY \"System can insert history\" ON public.api_integration_history\n  FOR INSERT TO authenticated\n  WITH CHECK (true);\n"], ["20260403003620_f33363f6-1ed0-40b9-997d-3c5b4c5c3485.sql", "\n-- Evaluation positions/roles (cargos)\nCREATE TABLE public.eval_positions (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name text NOT NULL,\n  sector_id uuid REFERENCES public.sectors(id) ON DELETE SET NULL,\n  description text,\n  is_active boolean NOT NULL DEFAULT true,\n  created_by uuid NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- Competencies\nCREATE TABLE public.eval_competencies (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name text NOT NULL,\n  description text,\n  category text NOT NULL DEFAULT 'behavioral',\n  is_active boolean NOT NULL DEFAULT true,\n  created_by uuid NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- Position-competency mapping with weights\nCREATE TABLE public.eval_position_competencies (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  position_id uuid NOT NULL REFERENCES public.eval_positions(id) ON DELETE CASCADE,\n  competency_id uuid NOT NULL REFERENCES public.eval_competencies(id) ON DELETE CASCADE,\n  weight numeric NOT NULL DEFAULT 1,\n  min_expected_score numeric DEFAULT 3,\n  requires_comment boolean NOT NULL DEFAULT false,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(position_id, competency_id)\n);\n\n-- Evaluation cycles\nCREATE TABLE public.eval_cycles (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name text NOT NULL,\n  description text,\n  start_date date NOT NULL,\n  end_date date NOT NULL,\n  status text NOT NULL DEFAULT 'active',\n  created_by uuid NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- Evaluations (main record)\nCREATE TABLE public.evaluations (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  cycle_id uuid REFERENCES public.eval_cycles(id) ON DELETE SET NULL,\n  evaluator_id uuid NOT NULL,\n  evaluated_id uuid NOT NULL,\n  position_id uuid REFERENCES public.eval_positions(id) ON DELETE SET NULL,\n  status text NOT NULL DEFAULT 'draft',\n  overall_comment text,\n  overall_score numeric,\n  evaluated_comment text,\n  evaluator_response text,\n  sent_at timestamptz,\n  responded_at timestamptz,\n  finalized_at timestamptz,\n  version integer NOT NULL DEFAULT 1,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- Evaluation items (one per competency)\nCREATE TABLE public.evaluation_items (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  evaluation_id uuid NOT NULL REFERENCES public.evaluations(id) ON DELETE CASCADE,\n  competency_id uuid NOT NULL REFERENCES public.eval_competencies(id) ON DELETE CASCADE,\n  score numeric,\n  weight numeric NOT NULL DEFAULT 1,\n  evaluator_comment text,\n  evaluated_response text,\n  evaluator_reply text,\n  classification text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- Evaluation history/audit trail\nCREATE TABLE public.evaluation_history (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  evaluation_id uuid NOT NULL REFERENCES public.evaluations(id) ON DELETE CASCADE,\n  action text NOT NULL,\n  performed_by uuid NOT NULL,\n  old_status text,\n  new_status text,\n  details text,\n  created_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- Teams table for multi-team support\nCREATE TABLE public.teams (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name text NOT NULL,\n  supervisor_id uuid NOT NULL,\n  description text,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\n-- Team members\nCREATE TABLE public.team_members (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  team_id uuid NOT NULL REFERENCES public.teams(id) ON DELETE CASCADE,\n  profile_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE(team_id, profile_id)\n);\n\n-- RLS\nALTER TABLE public.eval_positions ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.eval_competencies ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.eval_position_competencies ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.eval_cycles ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.evaluations ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.evaluation_items ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.evaluation_history ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.teams ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.team_members ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Authenticated can view positions\" ON public.eval_positions FOR SELECT TO authenticated USING (true);\nCREATE POLICY \"Supervisors can manage positions\" ON public.eval_positions FOR ALL TO authenticated USING (is_admin() OR has_autonomy_level('supervisor')) WITH CHECK (is_admin() OR has_autonomy_level('supervisor'));\n\nCREATE POLICY \"Authenticated can view competencies\" ON public.eval_competencies FOR SELECT TO authenticated USING (true);\nCREATE POLICY \"Supervisors can manage competencies\" ON public.eval_competencies FOR ALL TO authenticated USING (is_admin() OR has_autonomy_level('supervisor')) WITH CHECK (is_admin() OR has_autonomy_level('supervisor'));\n\nCREATE POLICY \"Authenticated can view position competencies\" ON public.eval_position_competencies FOR SELECT TO authenticated USING (true);\nCREATE POLICY \"Supervisors can manage position competencies\" ON public.eval_position_competencies FOR ALL TO authenticated USING (is_admin() OR has_autonomy_level('supervisor')) WITH CHECK (is_admin() OR has_autonomy_level('supervisor'));\n\nCREATE POLICY \"Authenticated can view cycles\" ON public.eval_cycles FOR SELECT TO authenticated USING (true);\nCREATE POLICY \"Supervisors can manage cycles\" ON public.eval_cycles FOR ALL TO authenticated USING (is_admin() OR has_autonomy_level('supervisor')) WITH CHECK (is_admin() OR has_autonomy_level('supervisor'));\n\nCREATE POLICY \"Users can view own evaluations\" ON public.evaluations FOR SELECT TO authenticated USING (evaluator_id = get_current_profile_id() OR evaluated_id = get_current_profile_id() OR is_admin() OR has_autonomy_level('supervisor'));\nCREATE POLICY \"Evaluators can create evaluations\" ON public.evaluations FOR INSERT TO authenticated WITH CHECK (evaluator_id = get_current_profile_id() OR is_admin() OR has_autonomy_level('supervisor'));\nCREATE POLICY \"Evaluators can update evaluations\" ON public.evaluations FOR UPDATE TO authenticated USING (evaluator_id = get_current_profile_id() OR evaluated_id = get_current_profile_id() OR is_admin() OR has_autonomy_level('supervisor'));\nCREATE POLICY \"Admins can delete evaluations\" ON public.evaluations FOR DELETE TO authenticated USING (is_admin());\n\nCREATE POLICY \"Users can view evaluation items\" ON public.evaluation_items FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.evaluations e WHERE e.id = evaluation_items.evaluation_id AND (e.evaluator_id = get_current_profile_id() OR e.evaluated_id = get_current_profile_id() OR is_admin() OR has_autonomy_level('supervisor'))));\nCREATE POLICY \"Evaluators can manage items\" ON public.evaluation_items FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.evaluations e WHERE e.id = evaluation_items.evaluation_id AND (e.evaluator_id = get_current_profile_id() OR is_admin() OR has_autonomy_level('supervisor')))) WITH CHECK (EXISTS (SELECT 1 FROM public.evaluations e WHERE e.id = evaluation_items.evaluation_id AND (e.evaluator_id = get_current_profile_id() OR is_admin() OR has_autonomy_level('supervisor'))));\nCREATE POLICY \"Evaluated can respond to items\" ON public.evaluation_items FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.evaluations e WHERE e.id = evaluation_items.evaluation_id AND e.evaluated_id = get_current_profile_id()));\n\nCREATE POLICY \"Users can view evaluation history\" ON public.evaluation_history FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.evaluations e WHERE e.id = evaluation_history.evaluation_id AND (e.evaluator_id = get_current_profile_id() OR e.evaluated_id = get_current_profile_id() OR is_admin() OR has_autonomy_level('supervisor'))));\nCREATE POLICY \"System can insert evaluation history\" ON public.evaluation_history FOR INSERT TO authenticated WITH CHECK (true);\n\nCREATE POLICY \"Supervisors can manage own teams\" ON public.teams FOR ALL TO authenticated USING (supervisor_id = auth.uid() OR is_admin()) WITH CHECK (supervisor_id = auth.uid() OR is_admin());\nCREATE POLICY \"Authenticated can view teams\" ON public.teams FOR SELECT TO authenticated USING (true);\n\nCREATE POLICY \"Team owners can manage members\" ON public.team_members FOR ALL TO authenticated USING (EXISTS (SELECT 1 FROM public.teams t WHERE t.id = team_members.team_id AND (t.supervisor_id = auth.uid() OR is_admin()))) WITH CHECK (EXISTS (SELECT 1 FROM public.teams t WHERE t.id = team_members.team_id AND (t.supervisor_id = auth.uid() OR is_admin())));\nCREATE POLICY \"Authenticated can view team members\" ON public.team_members FOR SELECT TO authenticated USING (true);\n\n-- Triggers for updated_at\nCREATE TRIGGER update_eval_positions_updated_at BEFORE UPDATE ON public.eval_positions FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_eval_cycles_updated_at BEFORE UPDATE ON public.eval_cycles FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_evaluations_updated_at BEFORE UPDATE ON public.evaluations FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_evaluation_items_updated_at BEFORE UPDATE ON public.evaluation_items FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\nCREATE TRIGGER update_teams_updated_at BEFORE UPDATE ON public.teams FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();\n"], ["20260501011327_17aa0911-391a-44e6-ad11-07fbff288a17.sql", "ALTER TABLE public.user_permissions\n  ADD COLUMN IF NOT EXISTS can_access_bh boolean NOT NULL DEFAULT false,\n  ADD COLUMN IF NOT EXISTS can_access_fechamento boolean NOT NULL DEFAULT false;"], ["20260503005836_bde2fb9b-e09f-4621-b7aa-1973124a54c8.sql", "ALTER TABLE public.user_permissions ADD COLUMN IF NOT EXISTS can_access_orbs boolean NOT NULL DEFAULT false;"], ["20260505185356_13d30b11-e04f-4a76-8a0c-6c2e6f4e8a61.sql", "-- Tabela de anota\u00e7\u00f5es\nCREATE TABLE public.notes (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  owner_id UUID NOT NULL,\n  title TEXT NOT NULL DEFAULT 'Nova anota\u00e7\u00e3o',\n  content TEXT NOT NULL DEFAULT '',\n  background_color TEXT NOT NULL DEFAULT '#FFF9C4',\n  background_texture TEXT,\n  background_image TEXT,\n  is_pinned BOOLEAN NOT NULL DEFAULT false,\n  is_archived BOOLEAN NOT NULL DEFAULT false,\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()\n);\n\nCREATE INDEX idx_notes_owner ON public.notes(owner_id);\n\n-- Tabela de compartilhamentos\nCREATE TABLE public.note_shares (\n  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,\n  note_id UUID NOT NULL REFERENCES public.notes(id) ON DELETE CASCADE,\n  shared_with_user_id UUID NOT NULL,\n  permission TEXT NOT NULL DEFAULT 'read' CHECK (permission IN ('read','edit')),\n  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),\n  UNIQUE (note_id, shared_with_user_id)\n);\n\nCREATE INDEX idx_note_shares_user ON public.note_shares(shared_with_user_id);\n\n-- Helper function: pode editar?\nCREATE OR REPLACE FUNCTION public.can_edit_note(_note_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE SECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1 FROM public.notes WHERE id = _note_id AND owner_id = auth.uid()\n  ) OR EXISTS (\n    SELECT 1 FROM public.note_shares \n    WHERE note_id = _note_id \n      AND shared_with_user_id = auth.uid()\n      AND permission = 'edit'\n  );\n$$;\n\nCREATE OR REPLACE FUNCTION public.can_view_note(_note_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE SECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1 FROM public.notes WHERE id = _note_id AND owner_id = auth.uid()\n  ) OR EXISTS (\n    SELECT 1 FROM public.note_shares \n    WHERE note_id = _note_id AND shared_with_user_id = auth.uid()\n  );\n$$;\n\n-- RLS\nALTER TABLE public.notes ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.note_shares ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Owners and shared users can view notes\"\nON public.notes FOR SELECT TO authenticated\nUSING (owner_id = auth.uid() OR EXISTS (\n  SELECT 1 FROM public.note_shares \n  WHERE note_id = notes.id AND shared_with_user_id = auth.uid()\n));\n\nCREATE POLICY \"Authenticated users can create notes\"\nON public.notes FOR INSERT TO authenticated\nWITH CHECK (owner_id = auth.uid());\n\nCREATE POLICY \"Owners and editors can update notes\"\nON public.notes FOR UPDATE TO authenticated\nUSING (owner_id = auth.uid() OR public.can_edit_note(id));\n\nCREATE POLICY \"Only owners can delete notes\"\nON public.notes FOR DELETE TO authenticated\nUSING (owner_id = auth.uid());\n\n-- note_shares policies\nCREATE POLICY \"Users can view shares related to them\"\nON public.note_shares FOR SELECT TO authenticated\nUSING (\n  shared_with_user_id = auth.uid() OR \n  EXISTS (SELECT 1 FROM public.notes WHERE id = note_shares.note_id AND owner_id = auth.uid())\n);\n\nCREATE POLICY \"Owners can manage shares\"\nON public.note_shares FOR INSERT TO authenticated\nWITH CHECK (EXISTS (SELECT 1 FROM public.notes WHERE id = note_shares.note_id AND owner_id = auth.uid()));\n\nCREATE POLICY \"Owners can update shares\"\nON public.note_shares FOR UPDATE TO authenticated\nUSING (EXISTS (SELECT 1 FROM public.notes WHERE id = note_shares.note_id AND owner_id = auth.uid()));\n\nCREATE POLICY \"Owners can delete shares\"\nON public.note_shares FOR DELETE TO authenticated\nUSING (EXISTS (SELECT 1 FROM public.notes WHERE id = note_shares.note_id AND owner_id = auth.uid()));\n\n-- Trigger updated_at\nCREATE TRIGGER update_notes_updated_at\nBEFORE UPDATE ON public.notes\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\n-- Realtime\nALTER PUBLICATION supabase_realtime ADD TABLE public.notes;\nALTER PUBLICATION supabase_realtime ADD TABLE public.note_shares;"], ["20260506003439_08fedc81-d43c-4c6d-a201-f012a7c2893d.sql", "-- Helper security definer to bypass RLS recursion\nCREATE OR REPLACE FUNCTION public.is_note_owner(_note_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE SECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (SELECT 1 FROM public.notes WHERE id = _note_id AND owner_id = auth.uid());\n$$;\n\nCREATE OR REPLACE FUNCTION public.is_note_shared_with_me(_note_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE SECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (SELECT 1 FROM public.note_shares WHERE note_id = _note_id AND shared_with_user_id = auth.uid());\n$$;\n\n-- Drop old recursive policies\nDROP POLICY IF EXISTS \"Owners and shared users can view notes\" ON public.notes;\nDROP POLICY IF EXISTS \"Owners and editors can update notes\" ON public.notes;\nDROP POLICY IF EXISTS \"Users can view shares related to them\" ON public.note_shares;\nDROP POLICY IF EXISTS \"Owners can manage shares\" ON public.note_shares;\nDROP POLICY IF EXISTS \"Owners can update shares\" ON public.note_shares;\nDROP POLICY IF EXISTS \"Owners can delete shares\" ON public.note_shares;\n\n-- Recreate notes policies without cross-table recursion\nCREATE POLICY \"View notes (owner or shared)\"\nON public.notes FOR SELECT TO authenticated\nUSING (owner_id = auth.uid() OR public.is_note_shared_with_me(id));\n\nCREATE POLICY \"Update notes (owner or editor)\"\nON public.notes FOR UPDATE TO authenticated\nUSING (owner_id = auth.uid() OR public.can_edit_note(id));\n\n-- Recreate note_shares policies using helper\nCREATE POLICY \"View own/owner shares\"\nON public.note_shares FOR SELECT TO authenticated\nUSING (shared_with_user_id = auth.uid() OR public.is_note_owner(note_id));\n\nCREATE POLICY \"Owners insert shares\"\nON public.note_shares FOR INSERT TO authenticated\nWITH CHECK (public.is_note_owner(note_id));\n\nCREATE POLICY \"Owners update shares\"\nON public.note_shares FOR UPDATE TO authenticated\nUSING (public.is_note_owner(note_id));\n\nCREATE POLICY \"Owners delete shares\"\nON public.note_shares FOR DELETE TO authenticated\nUSING (public.is_note_owner(note_id));"], ["20260603001839_d7f8dcf3-67d1-4d74-a321-8e5fcfef978d.sql", "CREATE INDEX IF NOT EXISTS idx_tasks_board_position ON public.tasks (board_id, position);\nCREATE INDEX IF NOT EXISTS idx_tasks_board_active_status_position ON public.tasks (board_id, is_archived, status, position);\nCREATE INDEX IF NOT EXISTS idx_tasks_board_updated_at ON public.tasks (board_id, updated_at DESC);\nCREATE INDEX IF NOT EXISTS idx_task_board_columns_board_position ON public.task_board_columns (board_id, position);\nCREATE INDEX IF NOT EXISTS idx_task_labels_board_name ON public.task_labels (board_id, name);\nCREATE INDEX IF NOT EXISTS idx_task_label_assignments_task_id ON public.task_label_assignments (task_id);\nCREATE INDEX IF NOT EXISTS idx_task_label_assignments_label_id ON public.task_label_assignments (label_id);\nCREATE INDEX IF NOT EXISTS idx_task_assignees_task_id ON public.task_assignees (task_id);\nCREATE INDEX IF NOT EXISTS idx_task_assignees_profile_id ON public.task_assignees (profile_id);\nCREATE INDEX IF NOT EXISTS idx_task_subtasks_task_position ON public.task_subtasks (task_id, position);\nCREATE INDEX IF NOT EXISTS idx_task_subtasks_group_position ON public.task_subtasks (group_id, position);\nCREATE INDEX IF NOT EXISTS idx_subtask_groups_task_position ON public.subtask_groups (task_id, position);\nCREATE INDEX IF NOT EXISTS idx_task_activities_task_created ON public.task_activities (task_id, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_task_decisions_task_created ON public.task_decisions (task_id, decision_date DESC);\nCREATE INDEX IF NOT EXISTS idx_messages_sector_created ON public.messages (sector_id, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_profiles_active_birth_date ON public.profiles (is_active, birth_date);"], ["20260604220452_4ed20dd9-5eaf-4921-a9be-a138ac393ae8.sql", "\n-- 1. api_access_logs: only service_role can insert (edge functions bypass RLS)\nDROP POLICY IF EXISTS \"System can insert api logs\" ON public.api_access_logs;\n\n-- 2. audit_logs: only service_role/triggers can insert\nDROP POLICY IF EXISTS \"System can insert audit logs\" ON public.audit_logs;\n\n-- 3. evaluation_history: only legitimate participants of the evaluation\nDROP POLICY IF EXISTS \"System can insert evaluation history\" ON public.evaluation_history;\nCREATE POLICY \"Participants can insert evaluation history\"\nON public.evaluation_history\nFOR INSERT TO authenticated\nWITH CHECK (\n  EXISTS (\n    SELECT 1 FROM public.evaluations e\n    WHERE e.id = evaluation_history.evaluation_id\n      AND (\n        e.evaluator_id = public.get_current_profile_id()\n        OR e.evaluated_id = public.get_current_profile_id()\n        OR public.is_admin()\n        OR public.has_autonomy_level('supervisor')\n      )\n  )\n  AND performed_by = public.get_current_profile_id()\n);\n\n-- 4. monthly_scores: restrict writes to own profile or admin (service role bypasses RLS)\nDROP POLICY IF EXISTS \"Authenticated can insert scores\" ON public.monthly_scores;\nDROP POLICY IF EXISTS \"Authenticated can update scores\" ON public.monthly_scores;\nCREATE POLICY \"Users insert own monthly scores\"\nON public.monthly_scores\nFOR INSERT TO authenticated\nWITH CHECK (profile_id = public.get_current_profile_id() OR public.is_admin());\nCREATE POLICY \"Users update own monthly scores\"\nON public.monthly_scores\nFOR UPDATE TO authenticated\nUSING (profile_id = public.get_current_profile_id() OR public.is_admin())\nWITH CHECK (profile_id = public.get_current_profile_id() OR public.is_admin());\n\n-- 5. task_comments: SELECT only for board members\nDROP POLICY IF EXISTS \"Users can view task comments\" ON public.task_comments;\nCREATE POLICY \"Board members can view task comments\"\nON public.task_comments\nFOR SELECT TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.tasks t\n    WHERE t.id = task_comments.task_id\n      AND public.is_board_member(t.board_id)\n  )\n);\n\n-- 6. user_notifications: must target self OR be admin\nDROP POLICY IF EXISTS \"Authenticated users can create mention notifications\" ON public.user_notifications;\nCREATE POLICY \"Users create notifications for self or admins for anyone\"\nON public.user_notifications\nFOR INSERT TO authenticated\nWITH CHECK (user_id = auth.uid() OR public.is_admin());\n\n-- 7. task_activities: only board members can log activities for their tasks\nDROP POLICY IF EXISTS \"Authenticated can insert task activities\" ON public.task_activities;\nCREATE POLICY \"Board members can insert task activities\"\nON public.task_activities\nFOR INSERT TO authenticated\nWITH CHECK (\n  user_id = auth.uid()\n  AND EXISTS (\n    SELECT 1 FROM public.tasks t\n    WHERE t.id = task_activities.task_id\n      AND public.is_board_member(t.board_id)\n  )\n);\n\n-- 8. workload_alerts: restrict insert to admin/supervisor (edge fns use service role)\nDROP POLICY IF EXISTS \"Authenticated can insert workload alerts\" ON public.workload_alerts;\nDROP POLICY IF EXISTS \"System can insert workload alerts\" ON public.workload_alerts;\nCREATE POLICY \"Admins and supervisors insert workload alerts\"\nON public.workload_alerts\nFOR INSERT TO authenticated\nWITH CHECK (public.is_admin() OR public.has_autonomy_level('supervisor'));\n\n-- 9. face-images storage: only admins can upload\nDROP POLICY IF EXISTS \"Users can upload their own face images\" ON storage.objects;\nCREATE POLICY \"Only admins can upload face images\"\nON storage.objects\nFOR INSERT TO authenticated\nWITH CHECK (bucket_id = 'face-images' AND public.is_admin());\n"], ["20260604220957_5c79cab1-f94f-42a9-bba0-a38aa6350cae.sql", "\n-- Reabrir user_notifications para permitir men\u00e7\u00f5es e convoca\u00e7\u00f5es entre usu\u00e1rios\nDROP POLICY IF EXISTS \"Users create notifications for self or admins for anyone\" ON public.user_notifications;\nCREATE POLICY \"Authenticated users can create notifications\"\nON public.user_notifications\nFOR INSERT TO authenticated\nWITH CHECK (auth.uid() IS NOT NULL);\n\n-- Permitir membros do quadro escreverem scores do quadro\nDROP POLICY IF EXISTS \"Users insert own monthly scores\" ON public.monthly_scores;\nDROP POLICY IF EXISTS \"Users update own monthly scores\" ON public.monthly_scores;\n\nCREATE POLICY \"Board members or self insert monthly scores\"\nON public.monthly_scores\nFOR INSERT TO authenticated\nWITH CHECK (\n  public.is_admin()\n  OR profile_id = public.get_current_profile_id()\n  OR (board_id IS NOT NULL AND public.is_board_member(board_id))\n);\n\nCREATE POLICY \"Board members or self update monthly scores\"\nON public.monthly_scores\nFOR UPDATE TO authenticated\nUSING (\n  public.is_admin()\n  OR profile_id = public.get_current_profile_id()\n  OR (board_id IS NOT NULL AND public.is_board_member(board_id))\n)\nWITH CHECK (\n  public.is_admin()\n  OR profile_id = public.get_current_profile_id()\n  OR (board_id IS NOT NULL AND public.is_board_member(board_id))\n);\n"], ["20260604223629_08caac6c-a9b8-46c6-9cdb-93104b58e2ab.sql", "CREATE OR REPLACE FUNCTION public.can_view_calendar_event(_event_id uuid, _created_by uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT auth.uid() IS NOT NULL AND (\n    _created_by = auth.uid()\n    OR public.is_admin()\n    OR EXISTS (\n      SELECT 1\n      FROM public.meeting_participants mp\n      WHERE mp.event_id = _event_id\n        AND mp.profile_id = public.get_current_profile_id()\n    )\n  );\n$$;\n\nCREATE OR REPLACE FUNCTION public.can_view_meeting_participants(_event_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT auth.uid() IS NOT NULL AND (\n    public.is_admin()\n    OR EXISTS (\n      SELECT 1\n      FROM public.calendar_events ce\n      WHERE ce.id = _event_id\n        AND ce.created_by = auth.uid()\n    )\n    OR EXISTS (\n      SELECT 1\n      FROM public.meeting_participants mp\n      WHERE mp.event_id = _event_id\n        AND mp.profile_id = public.get_current_profile_id()\n    )\n  );\n$$;\n\nREVOKE ALL ON FUNCTION public.can_view_calendar_event(uuid, uuid) FROM PUBLIC, anon;\nREVOKE ALL ON FUNCTION public.can_view_meeting_participants(uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.can_view_calendar_event(uuid, uuid) TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.can_view_meeting_participants(uuid) TO authenticated, service_role;\n\nDROP POLICY IF EXISTS \"Authenticated users can view calendar events\" ON public.calendar_events;\nCREATE POLICY \"Users can view own or invited calendar events\"\nON public.calendar_events\nFOR SELECT\nTO authenticated\nUSING (public.can_view_calendar_event(id, created_by));\n\nDROP POLICY IF EXISTS \"Users can view meeting participants\" ON public.meeting_participants;\nCREATE POLICY \"Users can view participants for visible events\"\nON public.meeting_participants\nFOR SELECT\nTO authenticated\nUSING (public.can_view_meeting_participants(event_id));\n\nDROP POLICY IF EXISTS \"Users can create task comments\" ON public.task_comments;\nCREATE POLICY \"Board members can create task comments\"\nON public.task_comments\nFOR INSERT\nTO authenticated\nWITH CHECK (\n  author_id = public.get_current_profile_id()\n  AND EXISTS (\n    SELECT 1\n    FROM public.tasks t\n    WHERE t.id = task_comments.task_id\n      AND public.is_board_member(t.board_id)\n  )\n);\n\nCREATE OR REPLACE FUNCTION public.create_user_notification(\n  _target_user_id uuid,\n  _type text,\n  _title text,\n  _message text,\n  _reference_id uuid DEFAULT NULL\n)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  new_notification_id uuid;\n  allowed boolean := false;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'not authenticated';\n  END IF;\n\n  allowed := _target_user_id = auth.uid() OR public.is_admin();\n\n  IF NOT allowed AND _type = 'war_room' AND _reference_id IS NOT NULL THEN\n    SELECT EXISTS (\n      SELECT 1 FROM public.war_rooms wr\n      WHERE wr.id = _reference_id AND wr.created_by = auth.uid()\n    ) INTO allowed;\n  END IF;\n\n  IF NOT allowed AND _type = 'mention' AND _reference_id IS NOT NULL THEN\n    SELECT EXISTS (\n      SELECT 1\n      FROM public.private_group_members actor_member\n      JOIN public.profiles actor_profile ON actor_profile.id = actor_member.profile_id\n      JOIN public.private_group_members target_member ON target_member.group_id = actor_member.group_id\n      WHERE actor_member.group_id = _reference_id\n        AND actor_profile.user_id = auth.uid()\n        AND target_member.user_id = _target_user_id\n    ) INTO allowed;\n  END IF;\n\n  IF NOT allowed THEN\n    RAISE EXCEPTION 'not allowed';\n  END IF;\n\n  INSERT INTO public.user_notifications (user_id, type, title, message, reference_id)\n  VALUES (_target_user_id, _type, _title, _message, _reference_id)\n  RETURNING id INTO new_notification_id;\n\n  RETURN new_notification_id;\nEND;\n$$;\n\nREVOKE ALL ON FUNCTION public.create_user_notification(uuid, text, text, text, uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.create_user_notification(uuid, text, text, text, uuid) TO authenticated, service_role;\n\nDROP POLICY IF EXISTS \"Authenticated users can create notifications\" ON public.user_notifications;\nDROP POLICY IF EXISTS \"Users can create own notifications\" ON public.user_notifications;\nCREATE POLICY \"Users can create own notifications\"\nON public.user_notifications\nFOR INSERT\nTO authenticated\nWITH CHECK (user_id = auth.uid());\n\nDROP POLICY IF EXISTS \"Users can view their own workload alerts\" ON public.workload_alerts;\nCREATE POLICY \"Users can view their own workload alerts\"\nON public.workload_alerts\nFOR SELECT\nTO authenticated\nUSING (profile_id = public.get_current_profile_id());\n\nDROP POLICY IF EXISTS \"System can insert history\" ON public.api_integration_history;\nCREATE POLICY \"Managers can create API history entries\"\nON public.api_integration_history\nFOR INSERT\nTO authenticated\nWITH CHECK (\n  performed_by = auth.uid()\n  AND (public.is_admin() OR public.has_autonomy_level('supervisor'))\n);\n\nDROP POLICY IF EXISTS \"Attachments are publicly accessible for viewing\" ON storage.objects;\nDROP POLICY IF EXISTS \"Avatar images are publicly accessible\" ON storage.objects;\nDROP POLICY IF EXISTS \"Authenticated users can view attachment files\" ON storage.objects;\nDROP POLICY IF EXISTS \"Authenticated users can view avatars\" ON storage.objects;\n\nCREATE POLICY \"Authenticated users can view attachment files\"\nON storage.objects\nFOR SELECT\nTO authenticated\nUSING (bucket_id = 'attachments');\n\nCREATE POLICY \"Authenticated users can view avatars\"\nON storage.objects\nFOR SELECT\nTO authenticated\nUSING (bucket_id = 'avatars');\n\nCREATE OR REPLACE FUNCTION public.get_board_tasks_fast(_board_id uuid)\nRETURNS TABLE (\n  id uuid,\n  task_number integer,\n  title text,\n  description text,\n  status text,\n  priority text,\n  assigned_to uuid,\n  created_by uuid,\n  sector_id uuid,\n  board_id uuid,\n  cover_image text,\n  due_date timestamp with time zone,\n  \"position\" integer,\n  is_archived boolean,\n  is_template boolean,\n  completed_at timestamp with time zone,\n  completed_late boolean,\n  delay_days integer,\n  is_emergency boolean,\n  created_at timestamp with time zone,\n  updated_at timestamp with time zone,\n  assignee jsonb\n)\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT\n    t.id,\n    t.task_number,\n    t.title,\n    t.description,\n    t.status,\n    t.priority,\n    t.assigned_to,\n    t.created_by,\n    t.sector_id,\n    t.board_id,\n    CASE\n      WHEN t.cover_image IS NULL THEN NULL\n      WHEN t.cover_image LIKE 'data:%' THEN NULL\n      WHEN length(t.cover_image) > 2048 THEN NULL\n      ELSE t.cover_image\n    END AS cover_image,\n    t.due_date,\n    t.\"position\",\n    COALESCE(t.is_archived, false) AS is_archived,\n    COALESCE(t.is_template, false) AS is_template,\n    t.completed_at,\n    t.completed_late,\n    t.delay_days,\n    COALESCE(t.is_emergency, false) AS is_emergency,\n    t.created_at,\n    t.updated_at,\n    CASE\n      WHEN p.id IS NULL THEN NULL\n      ELSE jsonb_build_object('id', p.id, 'name', p.name, 'display_name', p.display_name, 'avatar_url', p.avatar_url)\n    END AS assignee\n  FROM public.tasks t\n  LEFT JOIN public.profiles p ON p.id = t.assigned_to\n  WHERE t.board_id = _board_id\n    AND public.is_board_member(_board_id)\n  ORDER BY t.\"position\" ASC;\n$$;\n\nREVOKE ALL ON FUNCTION public.get_board_tasks_fast(uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.get_board_tasks_fast(uuid) TO authenticated, service_role;\n\nREVOKE EXECUTE ON FUNCTION public.get_current_autonomy_level() FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.user_has_sector_access(uuid, uuid) FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.log_deletion() FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.is_admin() FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.is_group_member(uuid) FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.user_is_member_of_group(uuid) FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.is_board_member(uuid) FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.is_board_owner(uuid) FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.has_role(uuid, app_role) FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.get_current_profile_id() FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.is_group_empty(uuid) FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.check_user_is_active() FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.is_group_admin(uuid) FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.update_last_seen() FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.handle_new_user() FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.has_autonomy_level(text) FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.is_board_admin_or_owner(uuid) FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.get_current_sector_id() FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.can_view_note(uuid) FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.can_edit_note(uuid) FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.is_note_shared_with_me(uuid) FROM PUBLIC, anon;\nREVOKE EXECUTE ON FUNCTION public.is_note_owner(uuid) FROM PUBLIC, anon;\n\nGRANT EXECUTE ON FUNCTION public.get_current_autonomy_level() TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.user_has_sector_access(uuid, uuid) TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.log_deletion() TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.is_admin() TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.is_group_member(uuid) TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.user_is_member_of_group(uuid) TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.is_board_member(uuid) TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.is_board_owner(uuid) TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.has_role(uuid, app_role) TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.get_current_profile_id() TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.is_group_empty(uuid) TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.check_user_is_active() TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.is_group_admin(uuid) TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.update_last_seen() TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.handle_new_user() TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.has_autonomy_level(text) TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.is_board_admin_or_owner(uuid) TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.get_current_sector_id() TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.can_view_note(uuid) TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.can_edit_note(uuid) TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.is_note_shared_with_me(uuid) TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.is_note_owner(uuid) TO authenticated, service_role;\n\nCREATE INDEX IF NOT EXISTS idx_calendar_events_created_by_start ON public.calendar_events (created_by, start_date);\nCREATE INDEX IF NOT EXISTS idx_calendar_events_start ON public.calendar_events (start_date);\nCREATE INDEX IF NOT EXISTS idx_meeting_participants_profile_event ON public.meeting_participants (profile_id, event_id);\nCREATE INDEX IF NOT EXISTS idx_meeting_participants_event_profile ON public.meeting_participants (event_id, profile_id);\nCREATE INDEX IF NOT EXISTS idx_task_comments_task_author_created ON public.task_comments (task_id, author_id, created_at);\nCREATE INDEX IF NOT EXISTS idx_user_notifications_user_read_created ON public.user_notifications (user_id, is_read, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_task_board_members_user_board ON public.task_board_members (user_id, board_id);\nCREATE INDEX IF NOT EXISTS idx_tasks_board_archived_template_position ON public.tasks (board_id, is_archived, is_template, status, \"position\");\nCREATE INDEX IF NOT EXISTS idx_direct_messages_receiver_read_created ON public.direct_messages (receiver_id, is_read, created_at DESC);\nCREATE INDEX IF NOT EXISTS idx_messages_sector_created_at ON public.messages (sector_id, created_at DESC);"], ["20260606181612_ded9cb6a-c088-49e1-aed3-9c298926f141.sql", "-- Security + performance hardening for task board and integrations\n\n-- 1) API integrations: keep only hashes for API keys, not plaintext keys\nALTER TABLE public.api_integrations\n  ADD COLUMN IF NOT EXISTS api_key_hash text;\n\nUPDATE public.api_integrations\nSET api_key_hash = encode(extensions.digest(api_key, 'sha256'), 'hex')\nWHERE api_key_hash IS NULL\n  AND api_key IS NOT NULL;\n\nALTER TABLE public.api_integrations\n  ALTER COLUMN api_key_hash SET NOT NULL;\n\nDO $$\nBEGIN\n  IF EXISTS (\n    SELECT 1\n    FROM information_schema.columns\n    WHERE table_schema = 'public'\n      AND table_name = 'api_integrations'\n      AND column_name = 'api_key'\n  ) AND NOT EXISTS (\n    SELECT 1\n    FROM information_schema.columns\n    WHERE table_schema = 'public'\n      AND table_name = 'api_integrations'\n      AND column_name = 'api_key_hint'\n  ) THEN\n    ALTER TABLE public.api_integrations RENAME COLUMN api_key TO api_key_hint;\n  END IF;\nEND $$;\n\nUPDATE public.api_integrations\nSET api_key_hint = 'stored-as-hash'\nWHERE api_key_hint IS NULL OR api_key_hint LIKE 'sk\\_%' ESCAPE '\\';\n\n-- 2) Attachment storage: no broad bucket reads/writes\nDROP POLICY IF EXISTS \"Authenticated users can upload attachments\" ON storage.objects;\nDROP POLICY IF EXISTS \"Authenticated users can view attachment files\" ON storage.objects;\nDROP POLICY IF EXISTS \"Users can view attachments if they have access to the record\" ON storage.objects;\nDROP POLICY IF EXISTS \"Users can delete their own attachments\" ON storage.objects;\n\nCREATE POLICY \"Users can upload attachments to their own folder\"\nON storage.objects\nFOR INSERT\nTO authenticated\nWITH CHECK (\n  bucket_id = 'attachments'\n  AND (storage.foldername(name))[1] = auth.uid()::text\n);\n\nCREATE POLICY \"Users can view permitted attachment files\"\nON storage.objects\nFOR SELECT\nTO authenticated\nUSING (\n  bucket_id = 'attachments'\n  AND (\n    (storage.foldername(name))[1] = auth.uid()::text\n    OR EXISTS (\n      SELECT 1\n      FROM public.attachments a\n      WHERE a.file_url LIKE '%' || storage.objects.name\n        AND (\n          (a.message_id IS NOT NULL AND EXISTS (\n            SELECT 1 FROM public.messages m WHERE m.id = a.message_id\n          ))\n          OR (a.direct_message_id IS NOT NULL AND EXISTS (\n            SELECT 1 FROM public.direct_messages dm\n            WHERE dm.id = a.direct_message_id\n              AND (dm.sender_id = public.get_current_profile_id() OR dm.receiver_id = public.get_current_profile_id())\n          ))\n          OR (a.announcement_id IS NOT NULL AND EXISTS (\n            SELECT 1 FROM public.announcements an WHERE an.id = a.announcement_id\n          ))\n        )\n    )\n    OR EXISTS (\n      SELECT 1\n      FROM public.tasks t\n      WHERE t.cover_image LIKE '%' || storage.objects.name\n        AND public.is_board_member(t.board_id)\n    )\n    OR EXISTS (\n      SELECT 1\n      FROM public.task_board_columns c\n      WHERE c.auto_cover LIKE '%' || storage.objects.name\n        AND public.is_board_member(c.board_id)\n    )\n  )\n);\n\nCREATE POLICY \"Users can delete attachments from their own folder\"\nON storage.objects\nFOR DELETE\nTO authenticated\nUSING (\n  bucket_id = 'attachments'\n  AND (storage.foldername(name))[1] = auth.uid()::text\n);\n\n-- 3) Task activities: only trusted function can create entries\nDROP POLICY IF EXISTS \"Authenticated can insert task activities\" ON public.task_activities;\nDROP POLICY IF EXISTS \"Board members can insert task activities\" ON public.task_activities;\n\nCREATE OR REPLACE FUNCTION public.log_task_activity_secure(\n  _task_id uuid,\n  _action_type text,\n  _description text,\n  _metadata jsonb DEFAULT '{}'::jsonb\n)\nRETURNS uuid\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  _board_id uuid;\n  _profile_id uuid;\n  _user_name text;\n  _activity_id uuid;\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'not authenticated';\n  END IF;\n\n  SELECT t.board_id INTO _board_id\n  FROM public.tasks t\n  WHERE t.id = _task_id;\n\n  IF _board_id IS NULL OR NOT public.is_board_member(_board_id) THEN\n    RAISE EXCEPTION 'not allowed';\n  END IF;\n\n  SELECT p.id, COALESCE(NULLIF(p.display_name, ''), p.name, 'Usu\u00e1rio')\n  INTO _profile_id, _user_name\n  FROM public.profiles p\n  WHERE p.user_id = auth.uid()\n  LIMIT 1;\n\n  IF _profile_id IS NULL THEN\n    RAISE EXCEPTION 'profile not found';\n  END IF;\n\n  INSERT INTO public.task_activities (task_id, user_id, user_name, action_type, description, metadata)\n  VALUES (_task_id, auth.uid(), _user_name, left(_action_type, 50), left(_description, 500), COALESCE(_metadata, '{}'::jsonb))\n  RETURNING id INTO _activity_id;\n\n  RETURN _activity_id;\nEND;\n$$;\n\nREVOKE ALL ON FUNCTION public.log_task_activity_secure(uuid, text, text, jsonb) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.log_task_activity_secure(uuid, text, text, jsonb) TO authenticated, service_role;\n\n-- 4) Monthly scores: no direct self-forged writes; use validated refresh function\nDROP POLICY IF EXISTS \"Board members or self insert monthly scores\" ON public.monthly_scores;\nDROP POLICY IF EXISTS \"Board members or self update monthly scores\" ON public.monthly_scores;\nDROP POLICY IF EXISTS \"Authenticated can insert scores\" ON public.monthly_scores;\nDROP POLICY IF EXISTS \"Authenticated can update scores\" ON public.monthly_scores;\nDROP POLICY IF EXISTS \"Admins and system can insert scores\" ON public.monthly_scores;\nDROP POLICY IF EXISTS \"Admins and system can update scores\" ON public.monthly_scores;\n\nCREATE POLICY \"Admins can insert monthly scores\"\nON public.monthly_scores\nFOR INSERT\nTO authenticated\nWITH CHECK (public.is_admin());\n\nCREATE POLICY \"Admins can update monthly scores\"\nON public.monthly_scores\nFOR UPDATE\nTO authenticated\nUSING (public.is_admin())\nWITH CHECK (public.is_admin());\n\nCREATE OR REPLACE FUNCTION public.refresh_board_monthly_scores(_board_id uuid)\nRETURNS void\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  _month text := to_char(now(), 'YYYY-MM');\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'not authenticated';\n  END IF;\n\n  IF NOT public.is_board_member(_board_id) THEN\n    RAISE EXCEPTION 'not allowed';\n  END IF;\n\n  INSERT INTO public.monthly_scores (\n    profile_id,\n    board_id,\n    year_month,\n    score,\n    total_tasks,\n    completed_tasks,\n    late_tasks,\n    on_time_tasks,\n    updated_at\n  )\n  WITH board_members AS (\n    SELECT DISTINCT tbm.profile_id\n    FROM public.task_board_members tbm\n    WHERE tbm.board_id = _board_id\n  ), task_assignments AS (\n    SELECT t.id, t.assigned_to AS profile_id, t.completed_at, t.due_date\n    FROM public.tasks t\n    WHERE t.board_id = _board_id\n      AND COALESCE(t.is_template, false) = false\n      AND COALESCE(t.is_archived, false) = false\n      AND t.assigned_to IS NOT NULL\n    UNION\n    SELECT t.id, ta.profile_id, t.completed_at, t.due_date\n    FROM public.tasks t\n    JOIN public.task_assignees ta ON ta.task_id = t.id\n    WHERE t.board_id = _board_id\n      AND COALESCE(t.is_template, false) = false\n      AND COALESCE(t.is_archived, false) = false\n  ), aggregates AS (\n    SELECT\n      bm.profile_id,\n      COUNT(ta.id)::int AS total_tasks,\n      COUNT(ta.id) FILTER (WHERE ta.completed_at IS NOT NULL)::int AS completed_tasks,\n      COUNT(ta.id) FILTER (WHERE ta.completed_at IS NOT NULL AND ta.due_date IS NOT NULL AND ta.completed_at > (ta.due_date + interval '24 hours'))::int AS late_tasks\n    FROM board_members bm\n    LEFT JOIN task_assignments ta ON ta.profile_id = bm.profile_id\n    GROUP BY bm.profile_id\n  )\n  SELECT\n    profile_id,\n    _board_id,\n    _month,\n    CASE\n      WHEN total_tasks = 0 THEN 0\n      ELSE ROUND((((completed_tasks - late_tasks)::numeric * (1000.0 / total_tasks)) + (late_tasks::numeric * (1000.0 / total_tasks) * 0.6)))::int\n    END AS score,\n    total_tasks,\n    completed_tasks,\n    late_tasks,\n    (completed_tasks - late_tasks)::int AS on_time_tasks,\n    now()\n  FROM aggregates\n  ON CONFLICT (profile_id, board_id, year_month)\n  DO UPDATE SET\n    score = EXCLUDED.score,\n    total_tasks = EXCLUDED.total_tasks,\n    completed_tasks = EXCLUDED.completed_tasks,\n    late_tasks = EXCLUDED.late_tasks,\n    on_time_tasks = EXCLUDED.on_time_tasks,\n    updated_at = now();\nEND;\n$$;\n\nREVOKE ALL ON FUNCTION public.refresh_board_monthly_scores(uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.refresh_board_monthly_scores(uuid) TO authenticated, service_role;\n\n-- 5) Fast board details: labels, assignees and subtask counts in one RPC\nCREATE OR REPLACE FUNCTION public.get_board_task_details_fast(_board_id uuid)\nRETURNS jsonb\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  _result jsonb;\nBEGIN\n  IF auth.uid() IS NULL OR NOT public.is_board_member(_board_id) THEN\n    RAISE EXCEPTION 'not allowed';\n  END IF;\n\n  SELECT jsonb_build_object(\n    'labels', COALESCE((\n      SELECT jsonb_agg(to_jsonb(l) ORDER BY l.name)\n      FROM public.task_labels l\n      WHERE l.board_id = _board_id\n    ), '[]'::jsonb),\n    'label_assignments', COALESCE((\n      SELECT jsonb_agg(jsonb_build_object('id', la.id, 'task_id', la.task_id, 'label_id', la.label_id, 'created_at', la.created_at))\n      FROM public.task_label_assignments la\n      JOIN public.task_labels l ON l.id = la.label_id\n      WHERE l.board_id = _board_id\n    ), '[]'::jsonb),\n    'assignees', COALESCE((\n      SELECT jsonb_agg(jsonb_build_object(\n        'id', ta.id,\n        'task_id', ta.task_id,\n        'profile_id', ta.profile_id,\n        'profile', jsonb_build_object('id', p.id, 'name', p.name, 'display_name', p.display_name, 'avatar_url', p.avatar_url)\n      ))\n      FROM public.task_assignees ta\n      JOIN public.tasks t ON t.id = ta.task_id\n      LEFT JOIN public.profiles p ON p.id = ta.profile_id\n      WHERE t.board_id = _board_id\n    ), '[]'::jsonb),\n    'subtask_counts', COALESCE((\n      SELECT jsonb_object_agg(task_id, jsonb_build_object('completed', completed, 'total', total))\n      FROM (\n        SELECT st.task_id, COUNT(*)::int AS total, COUNT(*) FILTER (WHERE st.is_completed)::int AS completed\n        FROM public.task_subtasks st\n        JOIN public.tasks t ON t.id = st.task_id\n        WHERE t.board_id = _board_id\n        GROUP BY st.task_id\n      ) s\n    ), '{}'::jsonb)\n  ) INTO _result;\n\n  RETURN _result;\nEND;\n$$;\n\nREVOKE ALL ON FUNCTION public.get_board_task_details_fast(uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.get_board_task_details_fast(uuid) TO authenticated, service_role;\n\n-- 6) Helpful indexes for these RPCs and storage lookup\nCREATE INDEX IF NOT EXISTS idx_api_integrations_api_key_hash ON public.api_integrations(api_key_hash);\nCREATE INDEX IF NOT EXISTS idx_attachments_file_url ON public.attachments(file_url);\nCREATE INDEX IF NOT EXISTS idx_task_activities_user_created ON public.task_activities(user_id, created_at DESC);\n\n-- 7) Limit direct execution exposure to the functions intentionally called by the client.\n-- Helper SECURITY DEFINER functions remain callable where RLS policies depend on them.\nREVOKE EXECUTE ON FUNCTION public.handle_new_user() FROM authenticated;\nREVOKE EXECUTE ON FUNCTION public.log_deletion() FROM authenticated;\nREVOKE EXECUTE ON FUNCTION public.update_last_seen() FROM authenticated;\nGRANT EXECUTE ON FUNCTION public.handle_new_user() TO service_role;\nGRANT EXECUTE ON FUNCTION public.log_deletion() TO service_role;\nGRANT EXECUTE ON FUNCTION public.update_last_seen() TO service_role;"], ["20260701000000_security_hardening.sql", "-- 1. Hardening SECURITY DEFINER functions\n-- Revoke execution from public to prevent anonymous access to helper functions\nREVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA public FROM PUBLIC;\nREVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA public FROM anon;\n\n-- Grant execution to authenticated users and service role\nGRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO authenticated;\nGRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO service_role;\n\n-- 2. Fixing \"Always True\" RLS Policies\n-- Presence: Only authenticated users should see presence\nDROP POLICY IF EXISTS \"Everyone can view presence\" ON public.user_presence;\nCREATE POLICY \"Authenticated users can view presence\"\n  ON public.user_presence FOR SELECT\n  TO authenticated\n  USING (true);\n\n-- Monthly Scores: Restrict INSERT and UPDATE\nDROP POLICY IF EXISTS \"Authenticated can insert scores\" ON public.monthly_scores;\nCREATE POLICY \"Admins and system can insert scores\"\nON public.monthly_scores FOR INSERT\nTO authenticated, service_role\nWITH CHECK (is_admin() OR (SELECT auth.role()) = 'service_role');\n\nDROP POLICY IF EXISTS \"Authenticated can update scores\" ON public.monthly_scores;\nCREATE POLICY \"Admins and system can update scores\"\nON public.monthly_scores FOR UPDATE\nTO authenticated, service_role\nUSING (is_admin() OR (SELECT auth.role()) = 'service_role');\n\n-- 3. Storage Security Hardening\n-- Set buckets to private (requires signed URLs or RLS)\nUPDATE storage.buckets SET public = false WHERE id IN ('attachments', 'avatars');\n\n-- Avatars: Only authenticated users can view\nDROP POLICY IF EXISTS \"Avatar images are publicly accessible\" ON storage.objects;\nCREATE POLICY \"Authenticated users can view avatars\"\n  ON storage.objects FOR SELECT\n  TO authenticated\n  USING (bucket_id = 'avatars');\n\n-- Attachments: Only users with access to the linked content can view\nDROP POLICY IF EXISTS \"Attachments are publicly accessible for viewing\" ON storage.objects;\nCREATE POLICY \"Users can view attachments if they have access to the record\"\n  ON storage.objects FOR SELECT\n  TO authenticated\n  USING (\n    bucket_id = 'attachments' AND \n    EXISTS (\n      SELECT 1 FROM public.attachments a\n      WHERE (storage.foldername(storage.objects.name))[1] = a.id::text -- Assuming folder name is attachment ID or similar\n      -- More precise check would be needed based on how files are stored\n    )\n  );\n\n-- Note: The attachment policy above is a template. \n-- A more secure way is to use signed URLs for private buckets.\n-- Given the app's structure, keeping them private and using RLS is better.\n\n-- 4. Secure the system_settings table even further\nALTER TABLE public.system_settings ENABLE ROW LEVEL SECURITY;\nDROP POLICY IF EXISTS \"Only admins can view system settings\" ON public.system_settings;\nCREATE POLICY \"Admins and service role can view system settings\"\n  ON public.system_settings FOR SELECT\n  TO authenticated, service_role\n  USING (is_admin() OR (SELECT auth.role()) = 'service_role');\n\n"], ["20260703220316_945fff98-4cfd-4825-b6de-59edeb092fa0.sql", "\n-- ============ 1. Profiles: sensitive fields ============\nREVOKE SELECT (phone, address, registration_number, company) ON public.profiles FROM authenticated;\nREVOKE SELECT (phone, address, registration_number, company) ON public.profiles FROM anon;\nREVOKE UPDATE (phone, address, registration_number, company) ON public.profiles FROM authenticated;\nREVOKE UPDATE (phone, address, registration_number, company) ON public.profiles FROM anon;\n\nCREATE OR REPLACE FUNCTION public.get_my_full_profile()\nRETURNS SETOF public.profiles\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\n  SELECT * FROM public.profiles WHERE user_id = auth.uid()\n$$;\n\nCREATE OR REPLACE FUNCTION public.admin_list_profiles_full()\nRETURNS SETOF public.profiles\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$\nBEGIN\n  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;\n  IF NOT (\n    public.is_admin()\n    OR EXISTS (SELECT 1 FROM public.user_permissions WHERE user_id = auth.uid() AND can_access_management = true)\n  ) THEN\n    RAISE EXCEPTION 'not allowed';\n  END IF;\n  RETURN QUERY SELECT * FROM public.profiles ORDER BY name;\nEND;\n$$;\n\nCREATE OR REPLACE FUNCTION public.get_profiles_registration(_ids uuid[])\nRETURNS TABLE(id uuid, registration_number text)\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$\nBEGIN\n  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;\n  IF NOT (\n    public.is_admin()\n    OR public.has_autonomy_level('supervisor')\n    OR EXISTS (SELECT 1 FROM public.user_permissions WHERE user_id = auth.uid() AND can_access_management = true)\n  ) THEN\n    RAISE EXCEPTION 'not allowed';\n  END IF;\n  RETURN QUERY SELECT p.id, p.registration_number FROM public.profiles p WHERE p.id = ANY(_ids);\nEND;\n$$;\n\nCREATE OR REPLACE FUNCTION public.update_profile_sensitive(\n  _user_id uuid,\n  _phone text,\n  _address text,\n  _registration_number text,\n  _company text\n) RETURNS void\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\nBEGIN\n  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;\n  IF NOT (public.is_admin() OR _user_id = auth.uid()) THEN\n    RAISE EXCEPTION 'not allowed';\n  END IF;\n  UPDATE public.profiles\n    SET phone = _phone,\n        address = _address,\n        registration_number = _registration_number,\n        company = _company,\n        updated_at = now()\n  WHERE user_id = _user_id;\nEND;\n$$;\n\nREVOKE ALL ON FUNCTION public.get_my_full_profile() FROM PUBLIC, anon;\nREVOKE ALL ON FUNCTION public.admin_list_profiles_full() FROM PUBLIC, anon;\nREVOKE ALL ON FUNCTION public.get_profiles_registration(uuid[]) FROM PUBLIC, anon;\nREVOKE ALL ON FUNCTION public.update_profile_sensitive(uuid, text, text, text, text) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.get_my_full_profile() TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.admin_list_profiles_full() TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.get_profiles_registration(uuid[]) TO authenticated, service_role;\nGRANT EXECUTE ON FUNCTION public.update_profile_sensitive(uuid, text, text, text, text) TO authenticated, service_role;\n\n-- ============ 2. Realtime channel authorization ============\n\n\n\n\n\n\n\n\n\n-- ============ 3. Attachments: verify sector access on messages ============\nDROP POLICY IF EXISTS \"Users can view attachments in messages they can see\" ON public.attachments;\nCREATE POLICY \"Users can view attachments in messages they can see\"\n  ON public.attachments FOR SELECT\n  USING (\n    ((message_id IS NOT NULL) AND EXISTS (\n      SELECT 1 FROM public.messages m\n      WHERE m.id = attachments.message_id\n        AND public.user_has_sector_access(auth.uid(), m.sector_id)\n    ))\n    OR ((direct_message_id IS NOT NULL) AND EXISTS (\n      SELECT 1 FROM public.direct_messages dm\n      WHERE dm.id = attachments.direct_message_id\n        AND (dm.sender_id = public.get_current_profile_id() OR dm.receiver_id = public.get_current_profile_id())\n    ))\n    OR ((announcement_id IS NOT NULL) AND EXISTS (\n      SELECT 1 FROM public.announcements a\n      WHERE a.id = attachments.announcement_id\n    ))\n  );\n\n-- ============ 4. supervisor_team_members: members can see themselves ============\nDROP POLICY IF EXISTS \"Supervisors can view their team\" ON public.supervisor_team_members;\nCREATE POLICY \"Supervisors and members can view team\"\n  ON public.supervisor_team_members FOR SELECT\n  USING (\n    supervisor_id = auth.uid()\n    OR member_profile_id = public.get_current_profile_id()\n    OR public.is_admin()\n  );\n\n-- ============ 5. user_notifications: force through RPC ============\nDROP POLICY IF EXISTS \"Users can create own notifications\" ON public.user_notifications;\n\nCREATE OR REPLACE FUNCTION public.create_user_notification(\n  _target_user_id uuid,\n  _type text,\n  _title text,\n  _message text,\n  _reference_id uuid DEFAULT NULL::uuid\n) RETURNS uuid\nLANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\nDECLARE\n  new_notification_id uuid;\n  allowed boolean := false;\nBEGIN\n  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;\n\n  allowed := _target_user_id = auth.uid() OR public.is_admin();\n\n  IF NOT allowed AND _type = 'war_room' AND _reference_id IS NOT NULL THEN\n    SELECT EXISTS (\n      SELECT 1 FROM public.war_rooms wr\n      WHERE wr.id = _reference_id AND wr.created_by = auth.uid()\n    ) INTO allowed;\n  END IF;\n\n  IF NOT allowed AND _type = 'mention' THEN\n    IF _reference_id IS NOT NULL THEN\n      SELECT EXISTS (\n        SELECT 1\n        FROM public.private_group_members actor_member\n        JOIN public.profiles actor_profile ON actor_profile.id = actor_member.profile_id\n        JOIN public.private_group_members target_member ON target_member.group_id = actor_member.group_id\n        WHERE actor_member.group_id = _reference_id\n          AND actor_profile.user_id = auth.uid()\n          AND target_member.user_id = _target_user_id\n      ) INTO allowed;\n    END IF;\n    IF NOT allowed THEN\n      -- Allow chat mention when target is active user\n      SELECT EXISTS (\n        SELECT 1 FROM public.profiles WHERE user_id = _target_user_id AND is_active = true\n      ) INTO allowed;\n    END IF;\n  END IF;\n\n  IF NOT allowed THEN RAISE EXCEPTION 'not allowed'; END IF;\n\n  INSERT INTO public.user_notifications (user_id, type, title, message, reference_id)\n  VALUES (_target_user_id, _type, _title, _message, _reference_id)\n  RETURNING id INTO new_notification_id;\n\n  RETURN new_notification_id;\nEND;\n$$;\n\nREVOKE ALL ON FUNCTION public.create_user_notification(uuid, text, text, text, uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.create_user_notification(uuid, text, text, text, uuid) TO authenticated, service_role;\n\n-- ============ 6. war_rooms membership-scoped SELECT ============\nCREATE OR REPLACE FUNCTION public.is_war_room_member(_war_room_id uuid)\nRETURNS boolean\nLANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\n  SELECT EXISTS (\n    SELECT 1 FROM public.war_room_members\n    WHERE war_room_id = _war_room_id AND user_id = auth.uid()\n  )\n$$;\n\nREVOKE ALL ON FUNCTION public.is_war_room_member(uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.is_war_room_member(uuid) TO authenticated, service_role;\n\nDROP POLICY IF EXISTS \"All authenticated can view war rooms\" ON public.war_rooms;\nCREATE POLICY \"Members creators and admins can view war rooms\"\n  ON public.war_rooms FOR SELECT\n  USING (\n    public.is_admin()\n    OR created_by = auth.uid()\n    OR public.is_war_room_member(id)\n    OR EXISTS (\n      SELECT 1 FROM public.user_permissions up\n      WHERE up.user_id = auth.uid()\n        AND (up.can_create_war_room = true OR up.can_access_management = true)\n    )\n  );\n\nDROP POLICY IF EXISTS \"All authenticated can view war room members\" ON public.war_room_members;\nCREATE POLICY \"Members creators and admins can view war room members\"\n  ON public.war_room_members FOR SELECT\n  USING (\n    public.is_admin()\n    OR user_id = auth.uid()\n    OR public.is_war_room_member(war_room_id)\n    OR EXISTS (\n      SELECT 1 FROM public.war_rooms wr\n      WHERE wr.id = war_room_members.war_room_id AND wr.created_by = auth.uid()\n    )\n    OR EXISTS (\n      SELECT 1 FROM public.user_permissions up\n      WHERE up.user_id = auth.uid()\n        AND (up.can_create_war_room = true OR up.can_access_management = true)\n    )\n  );\n\nDROP POLICY IF EXISTS \"All authenticated can view timeline\" ON public.war_room_timeline;\nCREATE POLICY \"Members creators and admins can view timeline\"\n  ON public.war_room_timeline FOR SELECT\n  USING (\n    public.is_admin()\n    OR created_by = auth.uid()\n    OR public.is_war_room_member(war_room_id)\n    OR EXISTS (\n      SELECT 1 FROM public.war_rooms wr\n      WHERE wr.id = war_room_timeline.war_room_id AND wr.created_by = auth.uid()\n    )\n    OR EXISTS (\n      SELECT 1 FROM public.user_permissions up\n      WHERE up.user_id = auth.uid()\n        AND (up.can_create_war_room = true OR up.can_access_management = true)\n    )\n  );\n"], ["20260703220530_53baaf48-d74f-48fa-99d1-1ff0865eae26.sql", "\n-- 1. announcement_comments: require authenticated\nDROP POLICY IF EXISTS \"Todos podem ver coment\u00e1rios\" ON public.announcement_comments;\nCREATE POLICY \"Usuarios autenticados podem ver comentarios\"\n  ON public.announcement_comments FOR SELECT\n  TO authenticated\n  USING (auth.uid() IS NOT NULL);\n\n-- 2. attachments: add auth check on announcement path\nDROP POLICY IF EXISTS \"Users can view attachments in messages they can see\" ON public.attachments;\nCREATE POLICY \"Users can view attachments in messages they can see\"\n  ON public.attachments FOR SELECT\n  TO authenticated\n  USING (\n    ((message_id IS NOT NULL) AND EXISTS (\n      SELECT 1 FROM public.messages m\n      WHERE m.id = attachments.message_id\n        AND public.user_has_sector_access(auth.uid(), m.sector_id)\n    ))\n    OR ((direct_message_id IS NOT NULL) AND EXISTS (\n      SELECT 1 FROM public.direct_messages dm\n      WHERE dm.id = attachments.direct_message_id\n        AND (dm.sender_id = public.get_current_profile_id() OR dm.receiver_id = public.get_current_profile_id())\n    ))\n    OR ((announcement_id IS NOT NULL) AND auth.uid() IS NOT NULL AND EXISTS (\n      SELECT 1 FROM public.announcements a\n      WHERE a.id = attachments.announcement_id\n    ))\n  );\n\n-- 3. board_share_links: drop broad token lookup, expose only via RPC\nDROP POLICY IF EXISTS \"Anyone can look up active share links by token\" ON public.board_share_links;\n\nCREATE OR REPLACE FUNCTION public.resolve_board_share_link(_token text)\nRETURNS TABLE(board_id uuid, board_name text, board_description text, is_active boolean)\nLANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$\nBEGIN\n  IF auth.uid() IS NULL THEN\n    RAISE EXCEPTION 'not authenticated';\n  END IF;\n  RETURN QUERY\n    SELECT bsl.board_id, tb.name, tb.description, bsl.is_active\n    FROM public.board_share_links bsl\n    JOIN public.task_boards tb ON tb.id = bsl.board_id\n    WHERE bsl.share_token = _token\n      AND bsl.is_active = true\n    LIMIT 1;\nEND;\n$$;\n\nREVOKE ALL ON FUNCTION public.resolve_board_share_link(text) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.resolve_board_share_link(text) TO authenticated, service_role;\n"], ["20260703224341_84acc701-284f-4fcb-88fc-0192c9988248.sql", "\nALTER TYPE public.app_role ADD VALUE IF NOT EXISTS 'super_admin';\n"], ["20260703224431_8590ae94-d489-44e8-b87d-5bc0e2051322.sql", "\nCREATE TABLE IF NOT EXISTS public.companies (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  name text NOT NULL,\n  slug text NOT NULL UNIQUE,\n  logo_url text,\n  primary_color text NOT NULL DEFAULT '#0066CC',\n  secondary_color text NOT NULL DEFAULT '#FF6B00',\n  is_active boolean NOT NULL DEFAULT true,\n  is_system boolean NOT NULL DEFAULT false,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT ON public.companies TO authenticated;\nGRANT ALL ON public.companies TO service_role;\nALTER TABLE public.companies ENABLE ROW LEVEL SECURITY;\n\nDROP TRIGGER IF EXISTS trg_companies_updated_at ON public.companies;\nCREATE TRIGGER trg_companies_updated_at\n  BEFORE UPDATE ON public.companies\n  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nINSERT INTO public.companies (id, name, slug, primary_color, secondary_color, is_system)\nVALUES\n  ('00000000-0000-0000-0000-0000000000a1','Admin','admin','#111827','#F59E0B',true),\n  ('00000000-0000-0000-0000-0000000000a2','Grupo ServSul','servsul','#0066CC','#FF6B00',false)\nON CONFLICT (id) DO NOTHING;\n\n-- Add company_id to all relevant tables FIRST (so functions can reference it)\nDO $$\nDECLARE\n  t text;\n  tables text[] := ARRAY[\n    'profiles','sectors','task_boards','tasks','announcements','important_announcements',\n    'messages','direct_messages','private_groups','notes','calendar_events','war_rooms',\n    'evaluations','teams','api_integrations','scheduled_summaries','eval_cycles','eval_positions',\n    'eval_competencies'\n  ];\nBEGIN\n  FOREACH t IN ARRAY tables LOOP\n    EXECUTE format('ALTER TABLE public.%I ADD COLUMN IF NOT EXISTS company_id uuid REFERENCES public.companies(id)', t);\n    EXECUTE format('UPDATE public.%I SET company_id = ''00000000-0000-0000-0000-0000000000a2'' WHERE company_id IS NULL', t);\n    EXECUTE format('ALTER TABLE public.%I ALTER COLUMN company_id SET NOT NULL', t);\n    EXECUTE format('ALTER TABLE public.%I ALTER COLUMN company_id SET DEFAULT ''00000000-0000-0000-0000-0000000000a2''', t);\n    EXECUTE format('CREATE INDEX IF NOT EXISTS idx_%I_company_id ON public.%I(company_id)', t, t);\n  END LOOP;\nEND $$;\n\n-- Now safe to create functions that reference profiles.company_id\nCREATE OR REPLACE FUNCTION public.is_super_admin()\nRETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\n  SELECT EXISTS (\n    SELECT 1 FROM public.user_roles\n    WHERE user_id = auth.uid() AND role::text = 'super_admin'\n  )\n$$;\n\nCREATE OR REPLACE FUNCTION public.current_company_id()\nRETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\n  SELECT company_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1\n$$;\n\nCREATE OR REPLACE FUNCTION public.same_company(_company_id uuid)\nRETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$\n  SELECT public.is_super_admin() OR _company_id = public.current_company_id()\n$$;\n\nDROP POLICY IF EXISTS \"Authenticated see own company\" ON public.companies;\nCREATE POLICY \"Authenticated see own company\"\n  ON public.companies FOR SELECT TO authenticated\n  USING (public.is_super_admin() OR id = public.current_company_id());\n\nDROP POLICY IF EXISTS \"Super admin manages companies\" ON public.companies;\nCREATE POLICY \"Super admin manages companies\"\n  ON public.companies FOR ALL TO authenticated\n  USING (public.is_super_admin()) WITH CHECK (public.is_super_admin());\n\nCREATE OR REPLACE FUNCTION public.handle_new_user()\nRETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$\nBEGIN\n  INSERT INTO public.profiles (user_id, name, display_name, email, company_id)\n  VALUES (\n    NEW.id,\n    COALESCE(NEW.raw_user_meta_data ->> 'name', NEW.email),\n    COALESCE(NEW.raw_user_meta_data ->> 'display_name', split_part(NEW.email, '@', 1)),\n    NEW.email,\n    COALESCE(\n      NULLIF(NEW.raw_user_meta_data ->> 'company_id','')::uuid,\n      '00000000-0000-0000-0000-0000000000a2'::uuid\n    )\n  );\n  RETURN NEW;\nEND;\n$$;\n"], ["20260703224453_9a3ddfd4-2c32-4be6-be26-6a073a62eb6b.sql", "\nDROP POLICY IF EXISTS \"Auth read company logos\" ON storage.objects;\nCREATE POLICY \"Auth read company logos\"\n  ON storage.objects FOR SELECT TO authenticated\n  USING (bucket_id = 'company-logos');\n\nDROP POLICY IF EXISTS \"Super admin writes company logos\" ON storage.objects;\nCREATE POLICY \"Super admin writes company logos\"\n  ON storage.objects FOR INSERT TO authenticated\n  WITH CHECK (bucket_id = 'company-logos' AND public.is_super_admin());\n\nDROP POLICY IF EXISTS \"Super admin updates company logos\" ON storage.objects;\nCREATE POLICY \"Super admin updates company logos\"\n  ON storage.objects FOR UPDATE TO authenticated\n  USING (bucket_id = 'company-logos' AND public.is_super_admin());\n\nDROP POLICY IF EXISTS \"Super admin deletes company logos\" ON storage.objects;\nCREATE POLICY \"Super admin deletes company logos\"\n  ON storage.objects FOR DELETE TO authenticated\n  USING (bucket_id = 'company-logos' AND public.is_super_admin());\n"], ["20260704004823_12cba906-762f-4fe8-bb1d-06ff0c891862.sql", "\n-- messages: drop overly-permissive realtime policies\nDROP POLICY IF EXISTS \"authenticated can broadcast realtime\" ON public.messages;\nDROP POLICY IF EXISTS \"authenticated can read realtime\" ON public.messages;\n\n-- profiles: scope SELECT to same company\nDROP POLICY IF EXISTS \"Authenticated users can view profiles\" ON public.profiles;\nCREATE POLICY \"Authenticated users can view profiles in their company\"\nON public.profiles\nFOR SELECT\nTO authenticated\nUSING (\n  public.check_user_is_active()\n  AND (\n    public.is_super_admin()\n    OR company_id = public.current_company_id()\n    OR user_id = auth.uid()\n  )\n);\n\n-- eval_positions\nDROP POLICY IF EXISTS \"Authenticated can view eval_positions\" ON public.eval_positions;\nDROP POLICY IF EXISTS \"Todos podem ver eval_positions\" ON public.eval_positions;\nDROP POLICY IF EXISTS \"Anyone can view eval_positions\" ON public.eval_positions;\nCREATE POLICY \"Same company can view eval_positions\"\nON public.eval_positions FOR SELECT TO authenticated\nUSING (public.same_company(company_id));\n\n-- eval_competencies\nDROP POLICY IF EXISTS \"Authenticated can view eval_competencies\" ON public.eval_competencies;\nDROP POLICY IF EXISTS \"Todos podem ver eval_competencies\" ON public.eval_competencies;\nDROP POLICY IF EXISTS \"Anyone can view eval_competencies\" ON public.eval_competencies;\nCREATE POLICY \"Same company can view eval_competencies\"\nON public.eval_competencies FOR SELECT TO authenticated\nUSING (public.same_company(company_id));\n\n-- eval_cycles\nDROP POLICY IF EXISTS \"Authenticated can view eval_cycles\" ON public.eval_cycles;\nDROP POLICY IF EXISTS \"Todos podem ver eval_cycles\" ON public.eval_cycles;\nDROP POLICY IF EXISTS \"Anyone can view eval_cycles\" ON public.eval_cycles;\nCREATE POLICY \"Same company can view eval_cycles\"\nON public.eval_cycles FOR SELECT TO authenticated\nUSING (public.same_company(company_id));\n\n-- eval_position_competencies (join table \u2014 scope via parent position)\nDROP POLICY IF EXISTS \"Authenticated can view eval_position_competencies\" ON public.eval_position_competencies;\nDROP POLICY IF EXISTS \"Todos podem ver eval_position_competencies\" ON public.eval_position_competencies;\nDROP POLICY IF EXISTS \"Anyone can view eval_position_competencies\" ON public.eval_position_competencies;\nCREATE POLICY \"Same company can view eval_position_competencies\"\nON public.eval_position_competencies FOR SELECT TO authenticated\nUSING (\n  EXISTS (\n    SELECT 1 FROM public.eval_positions ep\n    WHERE ep.id = eval_position_competencies.position_id\n      AND public.same_company(ep.company_id)\n  )\n);\n\n-- important_announcements\nDROP POLICY IF EXISTS \"Anyone can view active important announcements\" ON public.important_announcements;\nCREATE POLICY \"Same company can view active important announcements\"\nON public.important_announcements FOR SELECT TO authenticated\nUSING (is_active = true AND public.same_company(company_id));\n\n-- sectors\nDROP POLICY IF EXISTS \"Todos podem ver setores\" ON public.sectors;\nCREATE POLICY \"Same company can view sectors\"\nON public.sectors FOR SELECT TO authenticated\nUSING (\n  id = '00000000-0000-0000-0000-000000000001'::uuid\n  OR public.same_company(company_id)\n);\n\n-- teams\nDROP POLICY IF EXISTS \"Authenticated can view teams\" ON public.teams;\nCREATE POLICY \"Same company can view teams\"\nON public.teams FOR SELECT TO authenticated\nUSING (public.same_company(company_id));\n"], ["20260705151829_82d8ae95-84c3-4abc-9210-0eb945085943.sql", "\n-- Drop overly permissive SELECT policies on eval_* tables\nDROP POLICY IF EXISTS \"Authenticated can view competencies\" ON public.eval_competencies;\nDROP POLICY IF EXISTS \"Authenticated can view cycles\" ON public.eval_cycles;\nDROP POLICY IF EXISTS \"Authenticated can view position competencies\" ON public.eval_position_competencies;\nDROP POLICY IF EXISTS \"Authenticated can view positions\" ON public.eval_positions;\n\n-- Fix messages: drop permissive realtime read/broadcast policies\nDROP POLICY IF EXISTS \"authenticated can read realtime\" ON public.messages;\nDROP POLICY IF EXISTS \"authenticated can broadcast realtime\" ON public.messages;\n\n-- Fix realtime.messages: drop permissive broadcast/read policies\n\n\n\n-- Announcement comments: scope to same company via parent announcement\nDROP POLICY IF EXISTS \"Usuarios autenticados podem ver comentarios\" ON public.announcement_comments;\nCREATE POLICY \"Same company can view announcement comments\"\nON public.announcement_comments FOR SELECT\nUSING (\n  auth.uid() IS NOT NULL AND EXISTS (\n    SELECT 1 FROM public.announcements a\n    WHERE a.id = announcement_comments.announcement_id\n      AND public.same_company(a.company_id)\n  )\n);\n\n-- Announcements: replace broad SELECT with same_company scoping\nDROP POLICY IF EXISTS \"Todos podem ver avisos\" ON public.announcements;\nCREATE POLICY \"Same company can view announcements\"\nON public.announcements FOR SELECT\nUSING (auth.uid() IS NOT NULL AND public.same_company(company_id));\n\n-- Team members: scope to same company via parent team\nDROP POLICY IF EXISTS \"Authenticated can view team members\" ON public.team_members;\nCREATE POLICY \"Same company can view team members\"\nON public.team_members FOR SELECT\nUSING (\n  auth.uid() IS NOT NULL AND EXISTS (\n    SELECT 1 FROM public.teams t\n    WHERE t.id = team_members.team_id\n      AND public.same_company(t.company_id)\n  )\n);\n"], ["20260706190525_f4660f80-2118-47f5-bd96-df4f7234d114.sql", "\n-- Fix attachments SELECT policy: enforce same_company scoping via announcement\nDROP POLICY IF EXISTS \"Users can view attachments in messages they can see\" ON public.attachments;\nCREATE POLICY \"Users can view attachments in messages they can see\"\nON public.attachments FOR SELECT\nUSING (\n  (message_id IS NOT NULL AND EXISTS (\n    SELECT 1 FROM public.messages m\n    WHERE m.id = attachments.message_id\n      AND public.user_has_sector_access(auth.uid(), m.sector_id)\n  ))\n  OR (direct_message_id IS NOT NULL AND EXISTS (\n    SELECT 1 FROM public.direct_messages dm\n    WHERE dm.id = attachments.direct_message_id\n      AND (dm.sender_id = public.get_current_profile_id() OR dm.receiver_id = public.get_current_profile_id())\n  ))\n  OR (announcement_id IS NOT NULL AND auth.uid() IS NOT NULL AND EXISTS (\n    SELECT 1 FROM public.announcements a\n    WHERE a.id = attachments.announcement_id\n      AND public.same_company(a.company_id)\n  ))\n  OR (uploaded_by = public.get_current_profile_id())\n  OR public.is_admin()\n);\n\n-- Fix storage.objects SELECT policy for attachments bucket: exact path match, not LIKE\nDROP POLICY IF EXISTS \"Users can view permitted attachment files\" ON storage.objects;\nCREATE POLICY \"Users can view permitted attachment files\"\nON storage.objects FOR SELECT\nUSING (\n  bucket_id = 'attachments'\n  AND (\n    (storage.foldername(name))[1] = (auth.uid())::text\n    OR EXISTS (\n      SELECT 1 FROM public.attachments a\n      WHERE split_part(split_part(a.file_url, '/attachments/', 2), '?', 1) = objects.name\n        AND (\n          (a.message_id IS NOT NULL AND EXISTS (\n            SELECT 1 FROM public.messages m\n            WHERE m.id = a.message_id\n              AND public.user_has_sector_access(auth.uid(), m.sector_id)\n          ))\n          OR (a.direct_message_id IS NOT NULL AND EXISTS (\n            SELECT 1 FROM public.direct_messages dm\n            WHERE dm.id = a.direct_message_id\n              AND (dm.sender_id = public.get_current_profile_id() OR dm.receiver_id = public.get_current_profile_id())\n          ))\n          OR (a.announcement_id IS NOT NULL AND EXISTS (\n            SELECT 1 FROM public.announcements an\n            WHERE an.id = a.announcement_id\n              AND public.same_company(an.company_id)\n          ))\n        )\n    )\n    OR EXISTS (\n      SELECT 1 FROM public.tasks t\n      WHERE split_part(split_part(t.cover_image, '/attachments/', 2), '?', 1) = objects.name\n        AND public.is_board_member(t.board_id)\n    )\n    OR EXISTS (\n      SELECT 1 FROM public.task_board_columns c\n      WHERE split_part(split_part(c.auto_cover, '/attachments/', 2), '?', 1) = objects.name\n        AND public.is_board_member(c.board_id)\n    )\n  )\n);\n"], ["20260706193010_7109658e-8dcb-469a-942b-6ac5502353ad.sql", "-- ============================================================\n-- 1. ISOLAMENTO: super_admin N\u00c3O v\u00ea dados de conte\u00fado de outras empresas.\n--    same_company() passa a comparar somente company_id do pr\u00f3prio profile.\n-- ============================================================\nCREATE OR REPLACE FUNCTION public.same_company(_company_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE SECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT _company_id IS NOT NULL AND _company_id = public.current_company_id()\n$$;\n\n-- ============================================================\n-- 2. M\u00d3DULOS POR EMPRESA\n-- ============================================================\nALTER TABLE public.companies\n  ADD COLUMN IF NOT EXISTS enabled_modules text[] NOT NULL DEFAULT ARRAY[\n    'chat','announcements','tasks','calendar','notes','birthdays',\n    'evaluations','war_room','teams','my_dashboard',\n    'bi','bh','fechamento','orbs'\n  ]::text[];\n\n-- Empresa \"Admin\" (sistema) s\u00f3 precisa dos essenciais para o super-admin operar.\nUPDATE public.companies\n   SET enabled_modules = ARRAY['companies_admin']::text[]\n WHERE is_system = true;\n\n-- ServSul: todos os m\u00f3dulos ativos (default acima j\u00e1 cobre, garantimos explicitamente).\nUPDATE public.companies\n   SET enabled_modules = ARRAY[\n     'chat','announcements','tasks','calendar','notes','birthdays',\n     'evaluations','war_room','teams','my_dashboard',\n     'bi','bh','fechamento','orbs'\n   ]::text[]\n WHERE slug = 'grupo-servsul';\n\n-- ============================================================\n-- 3. RLS de companies: leitura p\u00fablica da pr\u00f3pria + super-admin v\u00ea todas (metadados)\n-- ============================================================\nDROP POLICY IF EXISTS \"companies_select\" ON public.companies;\nDROP POLICY IF EXISTS \"Users can view their company\" ON public.companies;\nDROP POLICY IF EXISTS \"Super admin manages companies\" ON public.companies;\n\nCREATE POLICY \"companies_select_own_or_superadmin\"\n  ON public.companies FOR SELECT\n  TO authenticated\n  USING (\n    id = public.current_company_id()\n    OR public.is_super_admin()\n  );\n\nCREATE POLICY \"companies_super_admin_insert\"\n  ON public.companies FOR INSERT\n  TO authenticated\n  WITH CHECK (public.is_super_admin());\n\nCREATE POLICY \"companies_super_admin_update\"\n  ON public.companies FOR UPDATE\n  TO authenticated\n  USING (public.is_super_admin())\n  WITH CHECK (public.is_super_admin());\n\nCREATE POLICY \"companies_super_admin_delete\"\n  ON public.companies FOR DELETE\n  TO authenticated\n  USING (public.is_super_admin() AND NOT is_system);\n\n-- ============================================================\n-- 4. RPC: estat\u00edsticas de empresas (s\u00f3 super_admin)\n-- ============================================================\nCREATE OR REPLACE FUNCTION public.list_companies_with_stats()\nRETURNS TABLE (\n  id uuid,\n  name text,\n  slug text,\n  logo_url text,\n  primary_color text,\n  secondary_color text,\n  is_active boolean,\n  is_system boolean,\n  enabled_modules text[],\n  total_users integer,\n  active_users integer,\n  admins integer,\n  supervisors integer,\n  colaboradores integer,\n  created_at timestamptz\n)\nLANGUAGE plpgsql\nSTABLE SECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  IF NOT public.is_super_admin() THEN\n    RAISE EXCEPTION 'not allowed';\n  END IF;\n\n  RETURN QUERY\n  SELECT\n    c.id,\n    c.name,\n    c.slug,\n    c.logo_url,\n    c.primary_color,\n    c.secondary_color,\n    c.is_active,\n    c.is_system,\n    c.enabled_modules,\n    COALESCE(u.total, 0)::int      AS total_users,\n    COALESCE(u.active, 0)::int     AS active_users,\n    COALESCE(r.admins, 0)::int     AS admins,\n    COALESCE(r.supervisors, 0)::int AS supervisors,\n    COALESCE(r.colaboradores, 0)::int AS colaboradores,\n    c.created_at\n  FROM public.companies c\n  LEFT JOIN (\n    SELECT company_id,\n           COUNT(*) AS total,\n           COUNT(*) FILTER (WHERE is_active) AS active\n    FROM public.profiles\n    GROUP BY company_id\n  ) u ON u.company_id = c.id\n  LEFT JOIN (\n    SELECT p.company_id,\n           COUNT(*) FILTER (WHERE ur.role::text IN ('admin','super_admin')) AS admins,\n           COUNT(*) FILTER (WHERE p.autonomy_level IN ('supervisor','gerente','diretoria')) AS supervisors,\n           COUNT(*) FILTER (WHERE COALESCE(p.autonomy_level,'colaborador') = 'colaborador') AS colaboradores\n    FROM public.profiles p\n    LEFT JOIN public.user_roles ur ON ur.user_id = p.user_id\n    GROUP BY p.company_id\n  ) r ON r.company_id = c.id\n  ORDER BY c.is_system DESC, c.name;\nEND;\n$$;\n\nGRANT EXECUTE ON FUNCTION public.list_companies_with_stats() TO authenticated;\n\n-- ============================================================\n-- 5. RPC: lista usu\u00e1rios de uma empresa (s\u00f3 super_admin ou admin da pr\u00f3pria empresa)\n-- ============================================================\nCREATE OR REPLACE FUNCTION public.list_company_users(_company_id uuid)\nRETURNS TABLE (\n  profile_id uuid,\n  user_id uuid,\n  name text,\n  display_name text,\n  email text,\n  autonomy_level text,\n  is_active boolean,\n  roles text[]\n)\nLANGUAGE plpgsql\nSTABLE SECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  IF NOT (\n    public.is_super_admin()\n    OR (public.is_admin() AND _company_id = public.current_company_id())\n  ) THEN\n    RAISE EXCEPTION 'not allowed';\n  END IF;\n\n  RETURN QUERY\n  SELECT\n    p.id,\n    p.user_id,\n    p.name,\n    p.display_name,\n    p.email,\n    p.autonomy_level,\n    p.is_active,\n    COALESCE(\n      ARRAY(SELECT ur.role::text FROM public.user_roles ur WHERE ur.user_id = p.user_id),\n      ARRAY[]::text[]\n    )\n  FROM public.profiles p\n  WHERE p.company_id = _company_id\n  ORDER BY p.name;\nEND;\n$$;\n\nGRANT EXECUTE ON FUNCTION public.list_company_users(uuid) TO authenticated;\n\n-- ============================================================\n-- 6. RPC p\u00fablica (sem auth): lista empresas ativas p/ tela de sele\u00e7\u00e3o de login\n--    Retorna somente metadados p\u00fablicos (nome, slug, logo, cores).\n--    N\u00e3o exp\u00f5e empresas do sistema.\n-- ============================================================\nCREATE OR REPLACE FUNCTION public.public_list_companies_for_login()\nRETURNS TABLE (\n  id uuid,\n  name text,\n  slug text,\n  logo_url text,\n  primary_color text,\n  secondary_color text\n)\nLANGUAGE sql\nSTABLE SECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT id, name, slug, logo_url, primary_color, secondary_color\n  FROM public.companies\n  WHERE is_active = true AND is_system = false\n  ORDER BY name\n$$;\n\nGRANT EXECUTE ON FUNCTION public.public_list_companies_for_login() TO anon, authenticated;\n\n-- Tamb\u00e9m exp\u00f5e o metadado da empresa Admin/Vetor para o login do super_admin.\nCREATE OR REPLACE FUNCTION public.public_get_company_by_slug(_slug text)\nRETURNS TABLE (\n  id uuid,\n  name text,\n  slug text,\n  logo_url text,\n  primary_color text,\n  secondary_color text,\n  is_system boolean\n)\nLANGUAGE sql\nSTABLE SECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT id, name, slug, logo_url, primary_color, secondary_color, is_system\n  FROM public.companies\n  WHERE slug = _slug AND is_active = true\n  LIMIT 1\n$$;\n\nGRANT EXECUTE ON FUNCTION public.public_get_company_by_slug(text) TO anon, authenticated;\n"], ["20260707200410_31a0c5bd-f612-43a5-82e4-1f4c1837e528.sql", "\nCREATE OR REPLACE FUNCTION public.public_find_company(_query text)\nRETURNS TABLE(id uuid, name text, slug text, logo_url text, primary_color text, secondary_color text, is_system boolean)\nLANGUAGE sql\nSTABLE SECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT c.id, c.name, c.slug, c.logo_url, c.primary_color, c.secondary_color, c.is_system\n  FROM public.companies c\n  WHERE c.is_active = true\n    AND (\n      lower(c.slug) = lower(coalesce(_query,''))\n      OR lower(c.name) = lower(coalesce(_query,''))\n      OR lower(c.name) LIKE lower(coalesce(_query,'')) || '%'\n      OR lower(c.slug) LIKE lower(coalesce(_query,'')) || '%'\n    )\n  ORDER BY\n    CASE WHEN lower(c.slug) = lower(coalesce(_query,'')) OR lower(c.name) = lower(coalesce(_query,'')) THEN 0 ELSE 1 END,\n    length(c.name)\n  LIMIT 1\n$$;\n\nGRANT EXECUTE ON FUNCTION public.public_find_company(text) TO anon, authenticated;\n"], ["20260710192323_93229c29-dd1c-4501-b7ab-885eff9f0113.sql", "\n-- 1) Fix ambiguous is_active in list_companies_with_stats (RETURNS TABLE column conflicts with p.is_active)\nCREATE OR REPLACE FUNCTION public.list_companies_with_stats()\n RETURNS TABLE(id uuid, name text, slug text, logo_url text, primary_color text, secondary_color text, is_active boolean, is_system boolean, enabled_modules text[], total_users integer, active_users integer, admins integer, supervisors integer, colaboradores integer, created_at timestamp with time zone)\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n#variable_conflict use_column\nBEGIN\n  IF NOT public.is_super_admin() THEN\n    RAISE EXCEPTION 'not allowed';\n  END IF;\n\n  RETURN QUERY\n  SELECT\n    c.id,\n    c.name,\n    c.slug,\n    c.logo_url,\n    c.primary_color,\n    c.secondary_color,\n    c.is_active,\n    c.is_system,\n    c.enabled_modules,\n    COALESCE(u.total_u, 0)::int      AS total_users,\n    COALESCE(u.active_u, 0)::int     AS active_users,\n    COALESCE(r.admins_c, 0)::int     AS admins,\n    COALESCE(r.sup_c, 0)::int        AS supervisors,\n    COALESCE(r.col_c, 0)::int        AS colaboradores,\n    c.created_at\n  FROM public.companies c\n  LEFT JOIN (\n    SELECT p.company_id AS cid,\n           COUNT(*) AS total_u,\n           COUNT(*) FILTER (WHERE p.is_active) AS active_u\n    FROM public.profiles p\n    GROUP BY p.company_id\n  ) u ON u.cid = c.id\n  LEFT JOIN (\n    SELECT p.company_id AS cid,\n           COUNT(*) FILTER (WHERE ur.role::text IN ('admin','super_admin')) AS admins_c,\n           COUNT(*) FILTER (WHERE p.autonomy_level IN ('supervisor','gerente','diretoria')) AS sup_c,\n           COUNT(*) FILTER (WHERE COALESCE(p.autonomy_level,'colaborador') = 'colaborador') AS col_c\n    FROM public.profiles p\n    LEFT JOIN public.user_roles ur ON ur.user_id = p.user_id\n    GROUP BY p.company_id\n  ) r ON r.cid = c.id\n  ORDER BY c.is_system DESC, c.name;\nEND;\n$function$;\n\n-- 2) Exact-only company search\nCREATE OR REPLACE FUNCTION public.public_find_company(_query text)\n RETURNS TABLE(id uuid, name text, slug text, logo_url text, primary_color text, secondary_color text, is_system boolean)\n LANGUAGE sql\n STABLE SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\n  SELECT c.id, c.name, c.slug, c.logo_url, c.primary_color, c.secondary_color, c.is_system\n  FROM public.companies c\n  WHERE c.is_active = true\n    AND (\n      lower(trim(c.slug)) = lower(trim(coalesce(_query,'')))\n      OR lower(trim(c.name)) = lower(trim(coalesce(_query,'')))\n    )\n  LIMIT 1\n$function$;\n\n-- 3) Multi-tenant isolation: rewrite SELECT policies to always enforce same_company()\n\n-- messages\nDROP POLICY IF EXISTS \"Usu\u00e1rios podem ver mensagens dos setores com acesso\" ON public.messages;\nCREATE POLICY \"Same company members can view sector messages\"\nON public.messages FOR SELECT\nUSING (\n  auth.uid() IS NOT NULL\n  AND same_company(company_id)\n  AND (\n    sector_id = get_current_sector_id()\n    OR sector_id = '00000000-0000-0000-0000-000000000001'::uuid\n    OR is_admin()\n    OR EXISTS (\n      SELECT 1 FROM public.user_additional_sectors uas\n      WHERE uas.user_id = auth.uid() AND uas.sector_id = messages.sector_id\n    )\n  )\n);\n\n-- direct_messages\nDROP POLICY IF EXISTS \"Users can only view their own direct messages\" ON public.direct_messages;\nCREATE POLICY \"Users can only view their own direct messages\"\nON public.direct_messages FOR SELECT\nUSING (\n  same_company(company_id)\n  AND (\n    sender_id = get_current_profile_id()\n    OR receiver_id = get_current_profile_id()\n  )\n);\n\n-- private_groups\nDROP POLICY IF EXISTS \"Members can view their groups\" ON public.private_groups;\nCREATE POLICY \"Members can view their groups\"\nON public.private_groups FOR SELECT\nUSING (\n  same_company(company_id)\n  AND (user_is_member_of_group(id) OR created_by = auth.uid())\n);\n\n-- calendar_events\nDROP POLICY IF EXISTS \"Users can view own or invited calendar events\" ON public.calendar_events;\nCREATE POLICY \"Users can view own or invited calendar events\"\nON public.calendar_events FOR SELECT\nUSING (\n  same_company(company_id)\n  AND can_view_calendar_event(id, created_by)\n);\n\n-- tasks (non-board case)\nDROP POLICY IF EXISTS \"Users can view tasks in their sectors\" ON public.tasks;\nCREATE POLICY \"Users can view tasks in their sectors\"\nON public.tasks FOR SELECT\nUSING (\n  same_company(company_id)\n  AND (\n    is_admin()\n    OR (\n      board_id IS NULL\n      AND (\n        sector_id IS NULL\n        OR sector_id = get_current_sector_id()\n        OR sector_id = '00000000-0000-0000-0000-000000000001'::uuid\n        OR EXISTS (\n          SELECT 1 FROM public.user_additional_sectors uas\n          WHERE uas.user_id = auth.uid() AND uas.sector_id = tasks.sector_id\n        )\n      )\n    )\n  )\n);\n"], ["20260803034050_2dc14eed-a646-4d60-9f97-052d820b27b9.sql", "CREATE POLICY \"Users can only insert their own profile\"\nON public.profiles\nFOR INSERT\nTO authenticated\nWITH CHECK (user_id = auth.uid());"], ["20260803041644_39928e67-5163-4fbf-a773-825447fd63ee.sql", "\n-- Default company on insert\nCREATE OR REPLACE FUNCTION public.set_company_id_default()\nRETURNS trigger\nLANGUAGE plpgsql\nSECURITY DEFINER\nSET search_path = public\nAS $$\nBEGIN\n  IF NEW.company_id IS NULL THEN\n    NEW.company_id := public.current_company_id();\n  END IF;\n  RETURN NEW;\nEND;\n$$;\n\nDO $$\nDECLARE t text;\nBEGIN\n  FOREACH t IN ARRAY ARRAY['war_rooms','tasks','task_boards','sectors','teams','notes','private_groups','calendar_events','announcements','messages','direct_messages'] LOOP\n    EXECUTE format('DROP TRIGGER IF EXISTS set_company_id_default ON public.%I', t);\n    EXECUTE format('CREATE TRIGGER set_company_id_default BEFORE INSERT ON public.%I FOR EACH ROW EXECUTE FUNCTION public.set_company_id_default()', t);\n  END LOOP;\nEND $$;\n\n-- WAR ROOMS: company isolation\nDROP POLICY IF EXISTS \"Members creators and admins can view war rooms\" ON public.war_rooms;\nCREATE POLICY \"Members creators and admins can view war rooms\"\nON public.war_rooms FOR SELECT TO authenticated\nUSING (\n  (public.same_company(company_id) OR public.is_super_admin())\n  AND (\n    public.is_admin() OR created_by = auth.uid() OR public.is_war_room_member(id)\n    OR EXISTS (SELECT 1 FROM public.user_permissions up WHERE up.user_id = auth.uid() AND (up.can_create_war_room OR up.can_access_management))\n  )\n);\n\nDROP POLICY IF EXISTS \"Creators and admins can update war rooms\" ON public.war_rooms;\nCREATE POLICY \"Creators and admins can update war rooms\"\nON public.war_rooms FOR UPDATE TO authenticated\nUSING (public.same_company(company_id) AND (created_by = auth.uid() OR public.is_admin()))\nWITH CHECK (public.same_company(company_id));\n\nDROP POLICY IF EXISTS \"Permitted users can delete closed war rooms\" ON public.war_rooms;\nCREATE POLICY \"Permitted users can delete closed war rooms\"\nON public.war_rooms FOR DELETE TO authenticated\nUSING (\n  public.same_company(company_id) AND status = 'closed'\n  AND (public.is_admin() OR public.has_autonomy_level('supervisor')\n    OR EXISTS (SELECT 1 FROM public.user_permissions up WHERE up.user_id = auth.uid() AND (up.can_access_management OR up.can_create_war_room)))\n);\n\nDROP POLICY IF EXISTS \"Permitted users can create war rooms\" ON public.war_rooms;\nCREATE POLICY \"Permitted users can create war rooms\"\nON public.war_rooms FOR INSERT TO authenticated\nWITH CHECK (\n  public.same_company(company_id)\n  AND (public.is_admin() OR public.has_autonomy_level('supervisor')\n    OR EXISTS (SELECT 1 FROM public.user_permissions up WHERE up.user_id = auth.uid() AND (up.can_access_management OR up.can_create_war_room)))\n);\n\n-- WAR ROOM MEMBERS: only within same-company war rooms\nDROP POLICY IF EXISTS \"Members creators and admins can view war room members\" ON public.war_room_members;\nCREATE POLICY \"Members creators and admins can view war room members\"\nON public.war_room_members FOR SELECT TO authenticated\nUSING (\n  EXISTS (SELECT 1 FROM public.war_rooms wr WHERE wr.id = war_room_members.war_room_id AND public.same_company(wr.company_id))\n  AND (\n    public.is_admin() OR user_id = auth.uid() OR public.is_war_room_member(war_room_id)\n    OR EXISTS (SELECT 1 FROM public.war_rooms wr2 WHERE wr2.id = war_room_members.war_room_id AND wr2.created_by = auth.uid())\n    OR EXISTS (SELECT 1 FROM public.user_permissions up WHERE up.user_id = auth.uid() AND (up.can_create_war_room OR up.can_access_management))\n  )\n);\n\n-- PROFILES: admins limited to own company\nDROP POLICY IF EXISTS \"Admins can update any profile\" ON public.profiles;\nCREATE POLICY \"Admins can update profiles in their company\"\nON public.profiles FOR UPDATE TO authenticated\nUSING (public.is_admin() AND (public.same_company(company_id) OR public.is_super_admin()))\nWITH CHECK (public.is_admin() AND (public.same_company(company_id) OR public.is_super_admin()));\n\n-- TASK BOARDS / TASKS: company isolation on read\nDROP POLICY IF EXISTS \"Board members and owners can view boards\" ON public.task_boards;\nCREATE POLICY \"Board members and owners can view boards\"\nON public.task_boards FOR SELECT TO authenticated\nUSING (\n  (public.same_company(company_id) OR public.is_super_admin())\n  AND (owner_id = auth.uid() OR public.is_board_member(id) OR public.is_admin())\n);\n\nDROP POLICY IF EXISTS \"Board members can view board tasks\" ON public.tasks;\nCREATE POLICY \"Board members can view board tasks\"\nON public.tasks FOR SELECT TO authenticated\nUSING (\n  (public.same_company(company_id) OR public.is_super_admin())\n  AND board_id IS NOT NULL\n  AND EXISTS (SELECT 1 FROM public.task_boards b WHERE b.id = tasks.board_id)\n);\n\n-- Storage stats per company (super admin only)\nCREATE OR REPLACE FUNCTION public.get_company_storage_stats()\nRETURNS TABLE (company_id uuid, company_name text, table_name text, row_count bigint)\nLANGUAGE plpgsql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\nDECLARE\n  c record;\n  t text;\n  n bigint;\nBEGIN\n  IF NOT public.is_super_admin() THEN\n    RAISE EXCEPTION 'not authorized';\n  END IF;\n  FOR c IN SELECT id, name FROM public.companies ORDER BY name LOOP\n    FOREACH t IN ARRAY ARRAY['profiles','messages','direct_messages','announcements','tasks','task_boards','notes','sectors','private_groups','calendar_events','war_rooms'] LOOP\n      EXECUTE format('SELECT count(*) FROM public.%I WHERE company_id = $1', t) INTO n USING c.id;\n      company_id := c.id; company_name := c.name; table_name := t; row_count := n;\n      RETURN NEXT;\n    END LOOP;\n  END LOOP;\nEND;\n$$;\n\nREVOKE ALL ON FUNCTION public.get_company_storage_stats() FROM public, anon;\nGRANT EXECUTE ON FUNCTION public.get_company_storage_stats() TO authenticated;\n"], ["20260804034803_bc1216a3-1ca4-4154-8be1-c4021b02c7ac.sql", "-- Strict tenant isolation: super admins are not allowed to bypass ordinary people/chat visibility.\nDROP POLICY IF EXISTS \"Authenticated users can view profiles in their company\" ON public.profiles;\nCREATE POLICY \"Users view profiles only in their company\"\nON public.profiles FOR SELECT TO authenticated\nUSING (\n  public.check_user_is_active()\n  AND company_id = public.current_company_id()\n);\n\nDROP POLICY IF EXISTS \"Admins can update profiles in their company\" ON public.profiles;\nCREATE POLICY \"Admins update profiles only in their company\"\nON public.profiles FOR UPDATE TO authenticated\nUSING (public.is_admin() AND company_id = public.current_company_id())\nWITH CHECK (public.is_admin() AND company_id = public.current_company_id());\n\n-- Normalize existing direct-message ownership from the sender and remove impossible cross-company rows.\nDELETE FROM public.direct_messages dm\nUSING public.profiles sender, public.profiles receiver\nWHERE sender.id = dm.sender_id\n  AND receiver.id = dm.receiver_id\n  AND sender.company_id <> receiver.company_id;\n\nUPDATE public.direct_messages dm\nSET company_id = sender.company_id\nFROM public.profiles sender\nWHERE sender.id = dm.sender_id\n  AND dm.company_id IS DISTINCT FROM sender.company_id;\n\nDROP POLICY IF EXISTS \"Users can only view their own direct messages\" ON public.direct_messages;\nDROP POLICY IF EXISTS \"Users can send direct messages\" ON public.direct_messages;\nDROP POLICY IF EXISTS \"Users can update read status of their received messages\" ON public.direct_messages;\nDROP POLICY IF EXISTS \"Users can delete their own sent messages\" ON public.direct_messages;\n\nCREATE POLICY \"Company participants view direct messages\"\nON public.direct_messages FOR SELECT TO authenticated\nUSING (\n  company_id = public.current_company_id()\n  AND (sender_id = public.get_current_profile_id() OR receiver_id = public.get_current_profile_id())\n);\nCREATE POLICY \"Company users send direct messages\"\nON public.direct_messages FOR INSERT TO authenticated\nWITH CHECK (\n  company_id = public.current_company_id()\n  AND sender_id = public.get_current_profile_id()\n  AND EXISTS (\n    SELECT 1 FROM public.profiles receiver\n    WHERE receiver.id = receiver_id\n      AND receiver.company_id = public.current_company_id()\n      AND receiver.is_active = true\n  )\n);\nCREATE POLICY \"Recipients update direct message read state\"\nON public.direct_messages FOR UPDATE TO authenticated\nUSING (company_id = public.current_company_id() AND receiver_id = public.get_current_profile_id())\nWITH CHECK (company_id = public.current_company_id() AND receiver_id = public.get_current_profile_id());\nCREATE POLICY \"Senders delete own direct messages\"\nON public.direct_messages FOR DELETE TO authenticated\nUSING (company_id = public.current_company_id() AND sender_id = public.get_current_profile_id());\n\n-- Normalize group ownership and discard cross-company memberships before tightening policies.\nUPDATE public.private_groups pg\nSET company_id = p.company_id\nFROM public.profiles p\nWHERE p.user_id = pg.created_by\n  AND pg.company_id IS DISTINCT FROM p.company_id;\n\nDELETE FROM public.private_group_members pgm\nUSING public.private_groups pg, public.profiles p\nWHERE pg.id = pgm.group_id\n  AND p.id = pgm.profile_id\n  AND p.company_id <> pg.company_id;\n\nDROP POLICY IF EXISTS \"Members can view their groups\" ON public.private_groups;\nDROP POLICY IF EXISTS \"Authenticated users can create groups\" ON public.private_groups;\nDROP POLICY IF EXISTS \"Group admins can update their groups\" ON public.private_groups;\nDROP POLICY IF EXISTS \"Group admins can delete their groups\" ON public.private_groups;\nCREATE POLICY \"Company members view private groups\"\nON public.private_groups FOR SELECT TO authenticated\nUSING (company_id = public.current_company_id() AND (public.user_is_member_of_group(id) OR created_by = auth.uid()));\nCREATE POLICY \"Company users create private groups\"\nON public.private_groups FOR INSERT TO authenticated\nWITH CHECK (company_id = public.current_company_id() AND created_by = auth.uid());\nCREATE POLICY \"Company group admins update groups\"\nON public.private_groups FOR UPDATE TO authenticated\nUSING (company_id = public.current_company_id() AND public.is_group_admin(id))\nWITH CHECK (company_id = public.current_company_id() AND public.is_group_admin(id));\nCREATE POLICY \"Company group admins delete groups\"\nON public.private_groups FOR DELETE TO authenticated\nUSING (company_id = public.current_company_id() AND public.is_group_admin(id));\n\nDROP POLICY IF EXISTS \"Members can view group members\" ON public.private_group_members;\nDROP POLICY IF EXISTS \"Admins can add members\" ON public.private_group_members;\nDROP POLICY IF EXISTS \"Admins can update member roles\" ON public.private_group_members;\nDROP POLICY IF EXISTS \"Group admins can remove members\" ON public.private_group_members;\nCREATE POLICY \"Company members view group membership\"\nON public.private_group_members FOR SELECT TO authenticated\nUSING (\n  public.is_group_member(group_id)\n  AND EXISTS (SELECT 1 FROM public.private_groups pg WHERE pg.id = group_id AND pg.company_id = public.current_company_id())\n);\nCREATE POLICY \"Company group admins add members\"\nON public.private_group_members FOR INSERT TO authenticated\nWITH CHECK (\n  (public.is_group_admin(group_id) OR (user_id = auth.uid() AND public.is_group_empty(group_id)))\n  AND EXISTS (SELECT 1 FROM public.private_groups pg WHERE pg.id = group_id AND pg.company_id = public.current_company_id())\n  AND EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = profile_id AND p.user_id = user_id AND p.company_id = public.current_company_id())\n);\nCREATE POLICY \"Company group admins update membership\"\nON public.private_group_members FOR UPDATE TO authenticated\nUSING (public.is_group_admin(group_id) AND EXISTS (SELECT 1 FROM public.private_groups pg WHERE pg.id = group_id AND pg.company_id = public.current_company_id()))\nWITH CHECK (public.is_group_admin(group_id) AND EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = profile_id AND p.user_id = user_id AND p.company_id = public.current_company_id()));\nCREATE POLICY \"Company group admins remove membership\"\nON public.private_group_members FOR DELETE TO authenticated\nUSING ((public.is_group_admin(group_id) OR user_id = auth.uid()) AND EXISTS (SELECT 1 FROM public.private_groups pg WHERE pg.id = group_id AND pg.company_id = public.current_company_id()));\n\nDROP POLICY IF EXISTS \"Users can view messages in their groups\" ON public.private_group_messages;\nDROP POLICY IF EXISTS \"Group members can send messages\" ON public.private_group_messages;\nDROP POLICY IF EXISTS \"Group admins can delete messages\" ON public.private_group_messages;\nCREATE POLICY \"Company members view group messages\"\nON public.private_group_messages FOR SELECT TO authenticated\nUSING (public.is_group_member(group_id) AND EXISTS (SELECT 1 FROM public.private_groups pg WHERE pg.id = group_id AND pg.company_id = public.current_company_id()));\nCREATE POLICY \"Company members send group messages\"\nON public.private_group_messages FOR INSERT TO authenticated\nWITH CHECK (\n  sender_id = public.get_current_profile_id()\n  AND public.is_group_member(group_id)\n  AND EXISTS (SELECT 1 FROM public.private_groups pg WHERE pg.id = group_id AND pg.company_id = public.current_company_id())\n);\nCREATE POLICY \"Company group admins delete group messages\"\nON public.private_group_messages FOR DELETE TO authenticated\nUSING (public.is_group_admin(group_id) AND EXISTS (SELECT 1 FROM public.private_groups pg WHERE pg.id = group_id AND pg.company_id = public.current_company_id()));\n\n-- War-room membership must point to a user in the same company as the room.\nDROP POLICY IF EXISTS \"Permitted users can manage members\" ON public.war_room_members;\nCREATE POLICY \"Permitted company users add war room members\"\nON public.war_room_members FOR INSERT TO authenticated\nWITH CHECK (\n  EXISTS (\n    SELECT 1\n    FROM public.war_rooms wr\n    JOIN public.profiles p ON p.user_id = war_room_members.user_id\n    WHERE wr.id = war_room_members.war_room_id\n      AND wr.company_id = public.current_company_id()\n      AND p.company_id = wr.company_id\n  )\n  AND (\n    public.is_admin()\n    OR public.has_autonomy_level('supervisor')\n    OR EXISTS (\n      SELECT 1 FROM public.user_permissions up\n      WHERE up.user_id = auth.uid()\n        AND (up.can_access_management = true OR up.can_create_war_room = true)\n    )\n  )\n);"], ["20260805043311_fa22e7b1-86cd-4b79-94a1-ac4051357dd0.sql", "-- 1) Restrict all public-role policies in public schema to authenticated\nDO $$\nDECLARE r record;\nBEGIN\n  FOR r IN\n    SELECT schemaname, tablename, policyname\n    FROM pg_policies\n    WHERE schemaname = 'public' AND 'public' = ANY(roles)\n  LOOP\n    EXECUTE format('ALTER POLICY %I ON %I.%I TO authenticated', r.policyname, r.schemaname, r.tablename);\n  END LOOP;\nEND $$;\n\n-- 2) Company scoping inside board membership functions\nCREATE OR REPLACE FUNCTION public.is_board_owner(check_board_id uuid)\nRETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'\nAS $$\n  SELECT EXISTS (\n    SELECT 1 FROM public.task_boards b\n    WHERE b.id = check_board_id\n      AND b.owner_id = auth.uid()\n      AND (b.company_id = public.current_company_id() OR public.is_super_admin())\n  );\n$$;\n\nCREATE OR REPLACE FUNCTION public.is_board_member(check_board_id uuid)\nRETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'\nAS $$\n  SELECT EXISTS (\n    SELECT 1 FROM public.task_boards b\n    WHERE b.id = check_board_id\n      AND (b.company_id = public.current_company_id() OR public.is_super_admin())\n      AND (\n        b.owner_id = auth.uid()\n        OR EXISTS (\n          SELECT 1 FROM public.task_board_members m\n          WHERE m.board_id = b.id AND m.user_id = auth.uid()\n        )\n      )\n  );\n$$;\n\nCREATE OR REPLACE FUNCTION public.is_board_admin_or_owner(check_board_id uuid)\nRETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public'\nAS $$\n  SELECT EXISTS (\n    SELECT 1 FROM public.task_boards b\n    WHERE b.id = check_board_id\n      AND (b.company_id = public.current_company_id() OR public.is_super_admin())\n      AND (\n        b.owner_id = auth.uid()\n        OR EXISTS (\n          SELECT 1 FROM public.task_board_members m\n          WHERE m.board_id = b.id AND m.user_id = auth.uid() AND m.role = 'admin'\n        )\n      )\n  );\n$$;\n\n-- 3) Tasks SELECT policy: require board membership + board company match\nDROP POLICY IF EXISTS \"Board members can view board tasks\" ON public.tasks;\nCREATE POLICY \"Board members can view board tasks\"\nON public.tasks FOR SELECT TO authenticated\nUSING (\n  board_id IS NOT NULL\n  AND (same_company(company_id) OR is_super_admin())\n  AND EXISTS (\n    SELECT 1 FROM public.task_boards b\n    WHERE b.id = tasks.board_id\n      AND b.company_id = tasks.company_id\n  )\n  AND public.is_board_member(board_id)\n);\n\n-- 4) Company logos readable pre-login (branding on company selection screen)\nDROP POLICY IF EXISTS \"Public read company logos\" ON storage.objects;\nCREATE POLICY \"Public read company logos\"\nON storage.objects FOR SELECT TO anon\nUSING (bucket_id = 'company-logos');\n"], ["20260805045733_2a902224-6271-4686-b3ec-e8f8c2575226.sql", "-- WAR ROOMS: remove super admin cross-tenant bypass\nDROP POLICY IF EXISTS \"Members creators and admins can view war rooms\" ON public.war_rooms;\nCREATE POLICY \"Members creators and admins can view war rooms\"\nON public.war_rooms FOR SELECT TO authenticated\nUSING (\n  same_company(company_id)\n  AND (\n    is_admin() OR created_by = auth.uid() OR is_war_room_member(id)\n    OR EXISTS (SELECT 1 FROM user_permissions up WHERE up.user_id = auth.uid() AND (up.can_create_war_room OR up.can_access_management))\n  )\n);\n\nDROP POLICY IF EXISTS \"Users can view war room messages\" ON public.war_room_messages;\nCREATE POLICY \"Users can view war room messages\"\nON public.war_room_messages FOR SELECT TO authenticated\nUSING (\n  EXISTS (SELECT 1 FROM war_rooms wr WHERE wr.id = war_room_messages.war_room_id AND same_company(wr.company_id))\n  AND (\n    is_war_room_member(war_room_id) OR is_admin() OR has_autonomy_level('supervisor')\n    OR EXISTS (SELECT 1 FROM user_permissions up WHERE up.user_id = auth.uid() AND (up.can_access_management OR up.can_create_war_room))\n  )\n);\n\nDROP POLICY IF EXISTS \"Members creators and admins can view timeline\" ON public.war_room_timeline;\nCREATE POLICY \"Members creators and admins can view timeline\"\nON public.war_room_timeline FOR SELECT TO authenticated\nUSING (\n  EXISTS (SELECT 1 FROM war_rooms wr WHERE wr.id = war_room_timeline.war_room_id AND same_company(wr.company_id))\n  AND (\n    is_admin() OR created_by = auth.uid() OR is_war_room_member(war_room_id)\n    OR EXISTS (SELECT 1 FROM user_permissions up WHERE up.user_id = auth.uid() AND (up.can_access_management OR up.can_create_war_room))\n  )\n);\n\n-- EVALUATIONS: company scoping\nDROP POLICY IF EXISTS \"Users can view own evaluations\" ON public.evaluations;\nCREATE POLICY \"Users can view own evaluations\"\nON public.evaluations FOR SELECT TO authenticated\nUSING (\n  same_company(company_id)\n  AND (\n    evaluator_id = get_current_profile_id() OR evaluated_id = get_current_profile_id()\n    OR is_admin() OR has_autonomy_level('supervisor')\n  )\n);\n\nDROP POLICY IF EXISTS \"Evaluators can update evaluations\" ON public.evaluations;\nCREATE POLICY \"Evaluators can update evaluations\"\nON public.evaluations FOR UPDATE TO authenticated\nUSING (\n  same_company(company_id)\n  AND (\n    evaluator_id = get_current_profile_id() OR evaluated_id = get_current_profile_id()\n    OR is_admin() OR has_autonomy_level('supervisor')\n  )\n);\n\nDROP POLICY IF EXISTS \"Admins can delete evaluations\" ON public.evaluations;\nCREATE POLICY \"Admins can delete evaluations\"\nON public.evaluations FOR DELETE TO authenticated\nUSING (same_company(company_id) AND is_admin());\n\nDROP POLICY IF EXISTS \"Users can view evaluation items\" ON public.evaluation_items;\nCREATE POLICY \"Users can view evaluation items\"\nON public.evaluation_items FOR SELECT TO authenticated\nUSING (EXISTS (\n  SELECT 1 FROM evaluations e\n  WHERE e.id = evaluation_items.evaluation_id\n    AND same_company(e.company_id)\n    AND (e.evaluator_id = get_current_profile_id() OR e.evaluated_id = get_current_profile_id() OR is_admin() OR has_autonomy_level('supervisor'))\n));\n\nDROP POLICY IF EXISTS \"Evaluators can manage items\" ON public.evaluation_items;\nCREATE POLICY \"Evaluators can manage items\"\nON public.evaluation_items FOR ALL TO authenticated\nUSING (EXISTS (\n  SELECT 1 FROM evaluations e\n  WHERE e.id = evaluation_items.evaluation_id\n    AND same_company(e.company_id)\n    AND (e.evaluator_id = get_current_profile_id() OR is_admin() OR has_autonomy_level('supervisor'))\n))\nWITH CHECK (EXISTS (\n  SELECT 1 FROM evaluations e\n  WHERE e.id = evaluation_items.evaluation_id\n    AND same_company(e.company_id)\n    AND (e.evaluator_id = get_current_profile_id() OR is_admin() OR has_autonomy_level('supervisor'))\n));\n\nDROP POLICY IF EXISTS \"Evaluated can respond to items\" ON public.evaluation_items;\nCREATE POLICY \"Evaluated can respond to items\"\nON public.evaluation_items FOR UPDATE TO authenticated\nUSING (EXISTS (\n  SELECT 1 FROM evaluations e\n  WHERE e.id = evaluation_items.evaluation_id AND same_company(e.company_id) AND e.evaluated_id = get_current_profile_id()\n));\n\nDROP POLICY IF EXISTS \"Users can view evaluation history\" ON public.evaluation_history;\nCREATE POLICY \"Users can view evaluation history\"\nON public.evaluation_history FOR SELECT TO authenticated\nUSING (EXISTS (\n  SELECT 1 FROM evaluations e\n  WHERE e.id = evaluation_history.evaluation_id\n    AND same_company(e.company_id)\n    AND (e.evaluator_id = get_current_profile_id() OR e.evaluated_id = get_current_profile_id() OR is_admin() OR has_autonomy_level('supervisor'))\n));\n\n-- Evaluation config tables: scope management to same company too\nDROP POLICY IF EXISTS \"Supervisors can manage competencies\" ON public.eval_competencies;\nCREATE POLICY \"Supervisors can manage competencies\"\nON public.eval_competencies FOR ALL TO authenticated\nUSING (same_company(company_id) AND (is_admin() OR has_autonomy_level('supervisor')))\nWITH CHECK (same_company(company_id) AND (is_admin() OR has_autonomy_level('supervisor')));\n\nDROP POLICY IF EXISTS \"Supervisors can manage cycles\" ON public.eval_cycles;\nCREATE POLICY \"Supervisors can manage cycles\"\nON public.eval_cycles FOR ALL TO authenticated\nUSING (same_company(company_id) AND (is_admin() OR has_autonomy_level('supervisor')))\nWITH CHECK (same_company(company_id) AND (is_admin() OR has_autonomy_level('supervisor')));\n\nDROP POLICY IF EXISTS \"Supervisors can manage positions\" ON public.eval_positions;\nCREATE POLICY \"Supervisors can manage positions\"\nON public.eval_positions FOR ALL TO authenticated\nUSING (same_company(company_id) AND (is_admin() OR has_autonomy_level('supervisor')))\nWITH CHECK (same_company(company_id) AND (is_admin() OR has_autonomy_level('supervisor')));"], ["20260808233232_0d1758f9-1c72-49e8-b3fe-c7036d50653c.sql", "-- 1. Remove super_admin cross-company bypass on boards\nCREATE OR REPLACE FUNCTION public.is_board_member(check_board_id uuid)\nRETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$\n  SELECT EXISTS (\n    SELECT 1 FROM public.task_boards b\n    WHERE b.id = check_board_id\n      AND b.company_id = public.current_company_id()\n      AND (\n        b.owner_id = auth.uid()\n        OR EXISTS (SELECT 1 FROM public.task_board_members m WHERE m.board_id = b.id AND m.user_id = auth.uid())\n      )\n  );\n$$;\n\nCREATE OR REPLACE FUNCTION public.is_board_admin_or_owner(check_board_id uuid)\nRETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$\n  SELECT EXISTS (\n    SELECT 1 FROM public.task_boards b\n    WHERE b.id = check_board_id\n      AND b.company_id = public.current_company_id()\n      AND (\n        b.owner_id = auth.uid()\n        OR EXISTS (SELECT 1 FROM public.task_board_members m WHERE m.board_id = b.id AND m.user_id = auth.uid() AND m.role = 'admin')\n      )\n  );\n$$;\n\nCREATE OR REPLACE FUNCTION public.is_board_owner(check_board_id uuid)\nRETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$\n  SELECT EXISTS (\n    SELECT 1 FROM public.task_boards b\n    WHERE b.id = check_board_id AND b.owner_id = auth.uid()\n      AND b.company_id = public.current_company_id()\n  );\n$$;\n\nDROP POLICY IF EXISTS \"Board members and owners can view boards\" ON public.task_boards;\nCREATE POLICY \"Board members and owners can view boards\" ON public.task_boards\nFOR SELECT TO authenticated\nUSING (same_company(company_id) AND (owner_id = auth.uid() OR is_board_member(id) OR is_admin()));\n\nDROP POLICY IF EXISTS \"Board members can view board tasks\" ON public.tasks;\nCREATE POLICY \"Board members can view board tasks\" ON public.tasks\nFOR SELECT TO authenticated\nUSING (\n  board_id IS NOT NULL\n  AND same_company(company_id)\n  AND EXISTS (SELECT 1 FROM public.task_boards b WHERE b.id = tasks.board_id AND b.company_id = tasks.company_id)\n  AND is_board_member(board_id)\n);\n\n-- 2. Profiles listing must stay inside the company\nCREATE OR REPLACE FUNCTION public.admin_list_profiles_full()\nRETURNS SETOF profiles LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$\nBEGIN\n  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not authenticated'; END IF;\n  IF NOT (\n    public.is_admin()\n    OR EXISTS (SELECT 1 FROM public.user_permissions WHERE user_id = auth.uid() AND can_access_management = true)\n  ) THEN\n    RAISE EXCEPTION 'not allowed';\n  END IF;\n  RETURN QUERY SELECT * FROM public.profiles WHERE company_id = public.current_company_id() ORDER BY name;\nEND;\n$$;\n\n-- 3. Clean up cross-company board memberships\nDELETE FROM public.task_board_members m\nUSING public.task_boards b, public.profiles p\nWHERE m.board_id = b.id AND p.user_id = m.user_id AND p.company_id <> b.company_id;\n\n-- 4. System-wide broadcasts (super admin only)\nCREATE TABLE IF NOT EXISTS public.system_broadcasts (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  title text NOT NULL,\n  content text NOT NULL,\n  severity text NOT NULL DEFAULT 'info',\n  is_active boolean NOT NULL DEFAULT true,\n  starts_at timestamptz NOT NULL DEFAULT now(),\n  ends_at timestamptz,\n  created_by uuid NOT NULL DEFAULT auth.uid(),\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT ON public.system_broadcasts TO authenticated;\nGRANT INSERT, UPDATE, DELETE ON public.system_broadcasts TO authenticated;\nGRANT ALL ON public.system_broadcasts TO service_role;\n\nALTER TABLE public.system_broadcasts ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Active users read active broadcasts\" ON public.system_broadcasts\nFOR SELECT TO authenticated\nUSING (check_user_is_active() AND is_active = true AND starts_at <= now() AND (ends_at IS NULL OR ends_at > now()));\n\nCREATE POLICY \"Super admin reads all broadcasts\" ON public.system_broadcasts\nFOR SELECT TO authenticated USING (is_super_admin());\n\nCREATE POLICY \"Super admin creates broadcasts\" ON public.system_broadcasts\nFOR INSERT TO authenticated WITH CHECK (is_super_admin() AND created_by = auth.uid());\n\nCREATE POLICY \"Super admin updates broadcasts\" ON public.system_broadcasts\nFOR UPDATE TO authenticated USING (is_super_admin()) WITH CHECK (is_super_admin());\n\nCREATE POLICY \"Super admin deletes broadcasts\" ON public.system_broadcasts\nFOR DELETE TO authenticated USING (is_super_admin());\n\nCREATE TRIGGER update_system_broadcasts_updated_at\nBEFORE UPDATE ON public.system_broadcasts\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();"], ["20260808233721_b59fa26e-cb76-485b-9a54-30cc8eed91d8.sql", "DROP POLICY IF EXISTS \"War room members can view linked task\" ON public.tasks;\nCREATE POLICY \"War room members can view linked task\"\nON public.tasks FOR SELECT TO authenticated\nUSING (\n  public.same_company(company_id)\n  AND EXISTS (\n    SELECT 1 FROM public.war_rooms wr\n    JOIN public.war_room_members wrm ON wrm.war_room_id = wr.id\n    WHERE wr.task_id = tasks.id\n      AND wrm.user_id = auth.uid()\n      AND wr.status = 'active'\n      AND wr.company_id = tasks.company_id\n  )\n);"], ["20260813195457_d6e0445b-31c5-4e21-9bc5-d34fb775494b.sql", "-- 1. Remove wrong company defaults so the trigger assigns the caller's company\nALTER TABLE public.announcements ALTER COLUMN company_id DROP DEFAULT;\nALTER TABLE public.api_integrations ALTER COLUMN company_id DROP DEFAULT;\nALTER TABLE public.calendar_events ALTER COLUMN company_id DROP DEFAULT;\nALTER TABLE public.direct_messages ALTER COLUMN company_id DROP DEFAULT;\nALTER TABLE public.eval_competencies ALTER COLUMN company_id DROP DEFAULT;\nALTER TABLE public.eval_cycles ALTER COLUMN company_id DROP DEFAULT;\nALTER TABLE public.eval_positions ALTER COLUMN company_id DROP DEFAULT;\nALTER TABLE public.evaluations ALTER COLUMN company_id DROP DEFAULT;\nALTER TABLE public.important_announcements ALTER COLUMN company_id DROP DEFAULT;\nALTER TABLE public.messages ALTER COLUMN company_id DROP DEFAULT;\nALTER TABLE public.notes ALTER COLUMN company_id DROP DEFAULT;\nALTER TABLE public.private_groups ALTER COLUMN company_id DROP DEFAULT;\nALTER TABLE public.scheduled_summaries ALTER COLUMN company_id DROP DEFAULT;\nALTER TABLE public.sectors ALTER COLUMN company_id DROP DEFAULT;\nALTER TABLE public.task_boards ALTER COLUMN company_id DROP DEFAULT;\nALTER TABLE public.tasks ALTER COLUMN company_id DROP DEFAULT;\nALTER TABLE public.teams ALTER COLUMN company_id DROP DEFAULT;\nALTER TABLE public.war_rooms ALTER COLUMN company_id DROP DEFAULT;\n\n-- 2. Ensure the company trigger exists everywhere it is needed\nDO $$\nDECLARE t text;\nBEGIN\n  FOREACH t IN ARRAY ARRAY['api_integrations','eval_competencies','eval_cycles','eval_positions','evaluations','important_announcements','scheduled_summaries'] LOOP\n    EXECUTE format('DROP TRIGGER IF EXISTS set_company_id_default ON public.%I', t);\n    EXECUTE format('CREATE TRIGGER set_company_id_default BEFORE INSERT ON public.%I FOR EACH ROW EXECUTE FUNCTION public.set_company_id_default()', t);\n  END LOOP;\nEND $$;\n\n-- 3. Move heavy base64 cover images out of tasks\nCREATE TABLE IF NOT EXISTS public.task_covers (\n  task_id uuid PRIMARY KEY REFERENCES public.tasks(id) ON DELETE CASCADE,\n  image text NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.task_covers TO authenticated;\nGRANT ALL ON public.task_covers TO service_role;\n\nALTER TABLE public.task_covers ENABLE ROW LEVEL SECURITY;\n\nCREATE POLICY \"Board members can view task covers\"\nON public.task_covers FOR SELECT TO authenticated\nUSING (EXISTS (SELECT 1 FROM public.tasks t WHERE t.id = task_covers.task_id AND t.board_id IS NOT NULL AND public.is_board_member(t.board_id)));\n\nCREATE POLICY \"Board members can manage task covers\"\nON public.task_covers FOR ALL TO authenticated\nUSING (EXISTS (SELECT 1 FROM public.tasks t WHERE t.id = task_covers.task_id AND t.board_id IS NOT NULL AND public.is_board_member(t.board_id)))\nWITH CHECK (EXISTS (SELECT 1 FROM public.tasks t WHERE t.id = task_covers.task_id AND t.board_id IS NOT NULL AND public.is_board_member(t.board_id)));\n\nCREATE TRIGGER update_task_covers_updated_at\nBEFORE UPDATE ON public.task_covers\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nALTER TABLE public.tasks ADD COLUMN IF NOT EXISTS has_cover boolean NOT NULL DEFAULT false;\n\nINSERT INTO public.task_covers (task_id, image)\nSELECT id, cover_image FROM public.tasks\nWHERE cover_image LIKE 'data:%'\nON CONFLICT (task_id) DO NOTHING;\n\nUPDATE public.tasks SET has_cover = true, cover_image = NULL WHERE cover_image LIKE 'data:%';\n\n-- 4. Fast board task list without heavy columns\nDROP FUNCTION IF EXISTS public.get_board_tasks_fast(uuid);\n\nCREATE OR REPLACE FUNCTION public.get_board_tasks_fast(_board_id uuid)\nRETURNS TABLE (\n  id uuid, task_number integer, title text, description text, status text, priority text,\n  assigned_to uuid, created_by uuid, sector_id uuid, board_id uuid, cover_image text,\n  has_cover boolean, due_date timestamptz, \"position\" integer, is_archived boolean,\n  is_template boolean, completed_at timestamptz, completed_late boolean, delay_days integer,\n  is_emergency boolean, created_at timestamptz, updated_at timestamptz, assignee jsonb\n)\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT\n    t.id, t.task_number, t.title, t.description, t.status, t.priority,\n    t.assigned_to, t.created_by, t.sector_id, t.board_id,\n    CASE WHEN t.cover_image LIKE 'data:%' THEN NULL ELSE t.cover_image END AS cover_image,\n    COALESCE(t.has_cover, false) AS has_cover,\n    t.due_date, t.\"position\",\n    COALESCE(t.is_archived, false) AS is_archived,\n    COALESCE(t.is_template, false) AS is_template,\n    t.completed_at, t.completed_late, t.delay_days,\n    COALESCE(t.is_emergency, false) AS is_emergency,\n    t.created_at, t.updated_at,\n    CASE WHEN p.id IS NULL THEN NULL\n      ELSE jsonb_build_object('id', p.id, 'name', p.name, 'display_name', p.display_name, 'avatar_url', p.avatar_url)\n    END AS assignee\n  FROM public.tasks t\n  LEFT JOIN public.profiles p ON p.id = t.assigned_to\n  WHERE t.board_id = _board_id\n    AND public.is_board_member(_board_id)\n  ORDER BY t.\"position\" ASC;\n$$;\n\n-- 5. Fetch a single task cover on demand\nCREATE OR REPLACE FUNCTION public.get_task_cover(_task_id uuid)\nRETURNS text\nLANGUAGE sql\nSTABLE\nSECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT c.image\n  FROM public.task_covers c\n  JOIN public.tasks t ON t.id = c.task_id\n  WHERE c.task_id = _task_id\n    AND t.board_id IS NOT NULL\n    AND public.is_board_member(t.board_id);\n$$;\n\nREVOKE ALL ON FUNCTION public.get_task_cover(uuid) FROM public, anon;\nGRANT EXECUTE ON FUNCTION public.get_task_cover(uuid) TO authenticated;\n"], ["20260817195956_d116c646-7510-4b62-a81e-e684e0208bc5.sql", "CREATE INDEX IF NOT EXISTS idx_workload_alerts_dedup_task\nON public.workload_alerts (profile_id, alert_type, task_id, created_at DESC);\n\nCREATE INDEX IF NOT EXISTS idx_workload_alerts_dedup_without_task\nON public.workload_alerts (profile_id, alert_type, created_at DESC)\nWHERE task_id IS NULL;\n\nCREATE INDEX IF NOT EXISTS idx_workload_alerts_profile_created\nON public.workload_alerts (profile_id, created_at DESC);\n\nCREATE INDEX IF NOT EXISTS idx_companies_active_normalized_name\nON public.companies (lower(btrim(name)))\nWHERE is_active = true;\n\nCREATE INDEX IF NOT EXISTS idx_companies_active_normalized_slug\nON public.companies (lower(btrim(slug)))\nWHERE is_active = true;\n\nDELETE FROM public.workload_alerts\nWHERE created_at < now() - interval '90 days';\n\nWITH ranked AS (\n  SELECT id,\n         row_number() OVER (\n           PARTITION BY profile_id, alert_type, task_id, date_trunc('hour', created_at)\n           ORDER BY created_at DESC, id DESC\n         ) AS duplicate_rank\n  FROM public.workload_alerts\n)\nDELETE FROM public.workload_alerts w\nUSING ranked r\nWHERE w.id = r.id\n  AND r.duplicate_rank > 1;\n\nANALYZE public.workload_alerts;\nANALYZE public.companies;\nANALYZE public.tasks;"], ["20260825120000_fix_company_logos_bucket.sql", "-- Garante que as logos possam ser exibidas antes do login.\nINSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nVALUES ('company-logos', 'company-logos', true, 5242880, ARRAY['image/png', 'image/jpeg', 'image/webp', 'image/gif', 'image/svg+xml'])\nON CONFLICT (id) DO UPDATE\nSET public = true,\n    file_size_limit = 5242880,\n    allowed_mime_types = EXCLUDED.allowed_mime_types;\n\nDROP POLICY IF EXISTS \"Public read company logos\" ON storage.objects;\nCREATE POLICY \"Public read company logos\"\nON storage.objects FOR SELECT\nTO anon, authenticated\nUSING (bucket_id = 'company-logos');\n"], ["20260827150000_fix_company_logos_public_access.sql", "-- Fix company logos visibility for all application surfaces.\n-- Company logos are tenant branding assets and must be readable by the\n-- company-selection screen (before login) and by authenticated users after login.\n\nINSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)\nVALUES (\n  'company-logos',\n  'company-logos',\n  true,\n  5242880,\n  ARRAY['image/png', 'image/jpeg', 'image/webp', 'image/gif', 'image/svg+xml']\n)\nON CONFLICT (id) DO UPDATE\nSET\n  public = true,\n  file_size_limit = 5242880,\n  allowed_mime_types = EXCLUDED.allowed_mime_types;\n\n-- Keep exactly one public read policy for the bucket. This avoids the\n-- previous migration conflict where authenticated users could lose access\n-- after the pre-login policy was recreated for anon only.\nDROP POLICY IF EXISTS \"Public read company logos\" ON storage.objects;\nDROP POLICY IF EXISTS \"Authenticated read company logos\" ON storage.objects;\nDROP POLICY IF EXISTS \"Company logos public read\" ON storage.objects;\n\nCREATE POLICY \"Company logos public read\"\nON storage.objects\nFOR SELECT\nTO anon, authenticated\nUSING (bucket_id = 'company-logos');\n\n-- Upload/update/delete remain restricted by the existing storage policies.\n-- This migration changes read access only; it does not expose write access.\n"], ["20260827185000_enable_scheduled_summary_cron.sql", "-- Run the scheduled chat/group summary worker every minute.\n-- The Edge Function has verify_jwt=false in config.toml, so pg_net can invoke it\n-- without storing a service-role key in the database.\n\nCREATE EXTENSION IF NOT EXISTS pg_cron WITH SCHEMA extensions;\nCREATE EXTENSION IF NOT EXISTS pg_net WITH SCHEMA extensions;\n\nDO $$\nBEGIN\n  IF EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'nuvexa-send-scheduled-summaries') THEN\n    PERFORM cron.unschedule('nuvexa-send-scheduled-summaries');\n  END IF;\nEND\n$$;\n\nSELECT cron.schedule(\n  'nuvexa-send-scheduled-summaries',\n  '* * * * *',\n  $$\n    SELECT net.http_post(\n      url := 'https://efkhsesptcoukapcdllg.supabase.co/functions/v1/send-scheduled-summary',\n      headers := jsonb_build_object('Content-Type', 'application/json'),\n      body := '{}'::jsonb\n    );\n  $$\n);\n"], ["20260829000100_profile_extended_fields.sql", "alter table public.profiles\n  add column if not exists cover_url text,\n  add column if not exists description text,\n  add column if not exists address text;\n\ncomment on column public.profiles.cover_url is 'URL da imagem de capa personalizada do perfil';\ncomment on column public.profiles.description is 'Descri\u00e7\u00e3o pessoal exibida no perfil';\ncomment on column public.profiles.address is 'Endere\u00e7o informado pelo pr\u00f3prio usu\u00e1rio';\n"], ["20260829170000_system_shortcuts.sql", "-- Nuvexa: atalhos configur\u00e1veis por empresa, usu\u00e1rio e setor.\nCREATE TABLE IF NOT EXISTS public.system_shortcuts (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  company_id UUID NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,\n  name TEXT NOT NULL CHECK (char_length(trim(name)) BETWEEN 1 AND 60),\n  url TEXT NOT NULL CHECK (url ~* '^https?://'),\n  icon TEXT NOT NULL DEFAULT 'Link',\n  is_active BOOLEAN NOT NULL DEFAULT true,\n  created_by UUID REFERENCES public.profiles(id) ON DELETE SET NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS public.system_shortcut_users (\n  shortcut_id UUID NOT NULL REFERENCES public.system_shortcuts(id) ON DELETE CASCADE,\n  user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,\n  PRIMARY KEY (shortcut_id, user_id)\n);\n\nCREATE TABLE IF NOT EXISTS public.system_shortcut_sectors (\n  shortcut_id UUID NOT NULL REFERENCES public.system_shortcuts(id) ON DELETE CASCADE,\n  sector_id UUID NOT NULL REFERENCES public.sectors(id) ON DELETE CASCADE,\n  PRIMARY KEY (shortcut_id, sector_id)\n);\n\nCREATE INDEX IF NOT EXISTS idx_system_shortcuts_company ON public.system_shortcuts(company_id);\nCREATE INDEX IF NOT EXISTS idx_system_shortcut_users_user ON public.system_shortcut_users(user_id);\nCREATE INDEX IF NOT EXISTS idx_system_shortcut_sectors_sector ON public.system_shortcut_sectors(sector_id);\n\nALTER TABLE public.system_shortcuts ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.system_shortcut_users ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.system_shortcut_sectors ENABLE ROW LEVEL SECURITY;\n\nDROP POLICY IF EXISTS \"Admins gerenciam atalhos\" ON public.system_shortcuts;\nDROP POLICY IF EXISTS \"Usu\u00e1rios veem seus atalhos\" ON public.system_shortcuts;\nDROP POLICY IF EXISTS \"Admins gerenciam usu\u00e1rios dos atalhos\" ON public.system_shortcut_users;\nDROP POLICY IF EXISTS \"Usu\u00e1rios veem v\u00ednculos dos seus atalhos\" ON public.system_shortcut_users;\nDROP POLICY IF EXISTS \"Admins gerenciam setores dos atalhos\" ON public.system_shortcut_sectors;\nDROP POLICY IF EXISTS \"Usu\u00e1rios veem v\u00ednculos dos seus atalhos por setor\" ON public.system_shortcut_sectors;\n\nCREATE POLICY \"Admins gerenciam atalhos\"\nON public.system_shortcuts FOR ALL TO authenticated\nUSING (public.has_autonomy_level('admin') AND company_id = (SELECT company_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1))\nWITH CHECK (public.has_autonomy_level('admin') AND company_id = (SELECT company_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1));\n\nCREATE POLICY \"Usu\u00e1rios veem seus atalhos\"\nON public.system_shortcuts FOR SELECT TO authenticated\nUSING (\n  is_active = true\n  AND company_id = (SELECT company_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1)\n  AND (\n    EXISTS (\n      SELECT 1 FROM public.system_shortcut_users su\n      JOIN public.profiles p ON p.id = su.user_id\n      WHERE su.shortcut_id = system_shortcuts.id AND p.user_id = auth.uid()\n    )\n    OR EXISTS (\n      SELECT 1 FROM public.system_shortcut_sectors ss\n      JOIN public.profiles p ON p.sector_id = ss.sector_id\n      WHERE ss.shortcut_id = system_shortcuts.id AND p.user_id = auth.uid()\n    )\n  )\n);\n\nCREATE POLICY \"Admins gerenciam usu\u00e1rios dos atalhos\"\nON public.system_shortcut_users FOR ALL TO authenticated\nUSING (\n  public.has_autonomy_level('admin')\n  AND EXISTS (\n    SELECT 1 FROM public.system_shortcuts s\n    WHERE s.id = system_shortcut_users.shortcut_id\n      AND s.company_id = (SELECT company_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1)\n  )\n)\nWITH CHECK (\n  public.has_autonomy_level('admin')\n  AND EXISTS (\n    SELECT 1 FROM public.system_shortcuts s\n    WHERE s.id = system_shortcut_users.shortcut_id\n      AND s.company_id = (SELECT company_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1)\n  )\n);\n\nCREATE POLICY \"Usu\u00e1rios veem v\u00ednculos dos seus atalhos\"\nON public.system_shortcut_users FOR SELECT TO authenticated\nUSING (user_id = public.get_current_profile_id());\n\nCREATE POLICY \"Admins gerenciam setores dos atalhos\"\nON public.system_shortcut_sectors FOR ALL TO authenticated\nUSING (\n  public.has_autonomy_level('admin')\n  AND EXISTS (\n    SELECT 1 FROM public.system_shortcuts s\n    WHERE s.id = system_shortcut_sectors.shortcut_id\n      AND s.company_id = (SELECT company_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1)\n  )\n)\nWITH CHECK (\n  public.has_autonomy_level('admin')\n  AND EXISTS (\n    SELECT 1 FROM public.system_shortcuts s\n    WHERE s.id = system_shortcut_sectors.shortcut_id\n      AND s.company_id = (SELECT company_id FROM public.profiles WHERE user_id = auth.uid() LIMIT 1)\n  )\n);\n\nCREATE POLICY \"Usu\u00e1rios veem v\u00ednculos dos seus atalhos por setor\"\nON public.system_shortcut_sectors FOR SELECT TO authenticated\nUSING (sector_id = public.get_current_sector_id());\n\nDROP TRIGGER IF EXISTS update_system_shortcuts_updated_at ON public.system_shortcuts;\nCREATE TRIGGER update_system_shortcuts_updated_at\nBEFORE UPDATE ON public.system_shortcuts\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n"], ["20260901015029_7dfbe793-1285-4034-90cc-a01c31f13eb9.sql", "CREATE TABLE IF NOT EXISTS public.system_shortcuts (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  company_id uuid NOT NULL REFERENCES public.companies(id) ON DELETE CASCADE,\n  name text NOT NULL,\n  url text NOT NULL,\n  icon text NOT NULL DEFAULT 'Link',\n  is_active boolean NOT NULL DEFAULT true,\n  created_by uuid NOT NULL,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS public.system_shortcut_users (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  shortcut_id uuid NOT NULL REFERENCES public.system_shortcuts(id) ON DELETE CASCADE,\n  user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (shortcut_id, user_id)\n);\n\nCREATE TABLE IF NOT EXISTS public.system_shortcut_sectors (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  shortcut_id uuid NOT NULL REFERENCES public.system_shortcuts(id) ON DELETE CASCADE,\n  sector_id uuid NOT NULL REFERENCES public.sectors(id) ON DELETE CASCADE,\n  created_at timestamptz NOT NULL DEFAULT now(),\n  UNIQUE (shortcut_id, sector_id)\n);\n\nCREATE INDEX IF NOT EXISTS idx_system_shortcuts_company ON public.system_shortcuts(company_id, is_active);\nCREATE INDEX IF NOT EXISTS idx_system_shortcut_users_shortcut ON public.system_shortcut_users(shortcut_id);\nCREATE INDEX IF NOT EXISTS idx_system_shortcut_users_user ON public.system_shortcut_users(user_id);\nCREATE INDEX IF NOT EXISTS idx_system_shortcut_sectors_shortcut ON public.system_shortcut_sectors(shortcut_id);\n\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.system_shortcuts TO authenticated;\nGRANT ALL ON public.system_shortcuts TO service_role;\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.system_shortcut_users TO authenticated;\nGRANT ALL ON public.system_shortcut_users TO service_role;\nGRANT SELECT, INSERT, UPDATE, DELETE ON public.system_shortcut_sectors TO authenticated;\nGRANT ALL ON public.system_shortcut_sectors TO service_role;\n\nALTER TABLE public.system_shortcuts ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.system_shortcut_users ENABLE ROW LEVEL SECURITY;\nALTER TABLE public.system_shortcut_sectors ENABLE ROW LEVEL SECURITY;\n\nCREATE OR REPLACE FUNCTION public.can_view_shortcut(_shortcut_id uuid)\nRETURNS boolean\nLANGUAGE sql\nSTABLE SECURITY DEFINER\nSET search_path = public\nAS $$\n  SELECT EXISTS (\n    SELECT 1 FROM public.system_shortcuts s\n    WHERE s.id = _shortcut_id\n      AND public.same_company(s.company_id)\n      AND (\n        public.is_admin()\n        OR EXISTS (SELECT 1 FROM public.system_shortcut_users u WHERE u.shortcut_id = s.id AND u.user_id = public.get_current_profile_id())\n        OR EXISTS (SELECT 1 FROM public.system_shortcut_sectors sc WHERE sc.shortcut_id = s.id AND public.user_has_sector_access(auth.uid(), sc.sector_id))\n      )\n  );\n$$;\n\nDROP POLICY IF EXISTS \"shortcuts_select_allowed\" ON public.system_shortcuts;\nCREATE POLICY \"shortcuts_select_allowed\" ON public.system_shortcuts\nFOR SELECT TO authenticated\nUSING (public.can_view_shortcut(id));\n\nDROP POLICY IF EXISTS \"shortcuts_admin_manage\" ON public.system_shortcuts;\nCREATE POLICY \"shortcuts_admin_manage\" ON public.system_shortcuts\nFOR ALL TO authenticated\nUSING (public.is_admin() AND public.same_company(company_id))\nWITH CHECK (public.is_admin() AND public.same_company(company_id));\n\nDROP POLICY IF EXISTS \"shortcut_users_select\" ON public.system_shortcut_users;\nCREATE POLICY \"shortcut_users_select\" ON public.system_shortcut_users\nFOR SELECT TO authenticated\nUSING (public.can_view_shortcut(shortcut_id));\n\nDROP POLICY IF EXISTS \"shortcut_users_admin_manage\" ON public.system_shortcut_users;\nCREATE POLICY \"shortcut_users_admin_manage\" ON public.system_shortcut_users\nFOR ALL TO authenticated\nUSING (EXISTS (SELECT 1 FROM public.system_shortcuts s WHERE s.id = shortcut_id AND public.is_admin() AND public.same_company(s.company_id)))\nWITH CHECK (EXISTS (SELECT 1 FROM public.system_shortcuts s WHERE s.id = shortcut_id AND public.is_admin() AND public.same_company(s.company_id)));\n\nDROP POLICY IF EXISTS \"shortcut_sectors_select\" ON public.system_shortcut_sectors;\nCREATE POLICY \"shortcut_sectors_select\" ON public.system_shortcut_sectors\nFOR SELECT TO authenticated\nUSING (public.can_view_shortcut(shortcut_id));\n\nDROP POLICY IF EXISTS \"shortcut_sectors_admin_manage\" ON public.system_shortcut_sectors;\nCREATE POLICY \"shortcut_sectors_admin_manage\" ON public.system_shortcut_sectors\nFOR ALL TO authenticated\nUSING (EXISTS (SELECT 1 FROM public.system_shortcuts s WHERE s.id = shortcut_id AND public.is_admin() AND public.same_company(s.company_id)))\nWITH CHECK (EXISTS (SELECT 1 FROM public.system_shortcuts s WHERE s.id = shortcut_id AND public.is_admin() AND public.same_company(s.company_id)));\n\nDROP TRIGGER IF EXISTS update_system_shortcuts_updated_at ON public.system_shortcuts;\nCREATE TRIGGER update_system_shortcuts_updated_at BEFORE UPDATE ON public.system_shortcuts\nFOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();\n\nALTER TABLE public.api_integrations\n  ADD COLUMN IF NOT EXISTS scope_all_companies boolean NOT NULL DEFAULT false;"], ["20260902000000_add_team_alert_times.sql", "ALTER TABLE public.profiles \nADD COLUMN IF NOT EXISTS team_alert_times text[] DEFAULT ARRAY['09:00'];\n\n-- Update existing profiles to have the default\nUPDATE public.profiles SET team_alert_times = ARRAY['09:00'] WHERE team_alert_times IS NULL;\n"]];
